
import { Col, Row, Button, Icon, Spin, Form } from 'antd'
import { useEffect } from 'react'
import { connect } from 'react-redux'
import PermissionChecker from '../../../../components/permissionChecker'
import serviceCenterActions from '../../../redux/serviceCenter/actions'
import errorActions from '../../../../redux/error/actions'
import loadingActions from '../../../../redux/loading/actions'

import {
  StatusContainer
} from './serviceCenterForm.style'

const FormItem = Form.Item

// TODO: right now there are 3 calls to list, try to call 1 time only

const {
  getServiceCenterBrandList,
  resetServiceCenterRedux,
  getServiceCenterList
} = serviceCenterActions

const {
  resetErrorRedux
} = errorActions

const {
  resetLoadingRedux
} = loadingActions

const brandConst = 'sc_brand'
const serviceCenterConst = 'service_center'
const serviceBranchCenterConst = 'servicecenter_branch'

const antIcon = <Icon type='loading' style={{ fontSize: 24 }} spin />

const Loader = <Spin indicator={antIcon} />

function ViewServiceCenterForm ({
  resetErrorRedux,
  resetLoadingRedux,
  serviceCenterListLoading,
  serviceCenterListError,
  servicecenterList = [],
  thisInstance,
  formName,
  attributes,
  permissions = [],
  confirmReject,
  disableEventButtons,
  getServiceCenterList,
  brandList,
  getServiceCenterBrandList
}) {
  const isBrandAttributeExists = attributes?.some((attribute) => attribute.name === brandConst)

  useEffect(() => {
    if (isBrandAttributeExists) {
      getServiceCenterBrandList()
    }
  }, [isBrandAttributeExists])

  useEffect(() => {
    if (servicecenterList.length === 0 && !serviceCenterListError) {
      getServiceCenterList()
    }
  }, [
    serviceCenterListError,
    getServiceCenterList,
    servicecenterList
  ])

  useEffect(() => {
    return () => {
      resetErrorRedux(['GET_SERVICE_CENTER_LIST'])
      resetLoadingRedux(['GET_SERVICE_CENTER_LIST'])
    }
  })

  const { branch_info: branchInfo = {} } = attributes.find(({ name }) => name === 'servicecenter_branch') || {}

  const renderInfo = attributes.map(({ value, name, label, required, events, status }) => {
    const data = {
      name,
      label,
      required,
      events,
      status
    }
    if (name === brandConst) {
      return {
        ...data,
        value: brandList?.find(({ id }) => id === value)?.name || (
          serviceCenterListLoading ? Loader : value
        )
      }
    }

    if (name === serviceCenterConst) {
      return {
        ...data,
        value: servicecenterList.find(({ code }) => branchInfo.servicecenter_code === code)?.name || (
          serviceCenterListLoading ? Loader : value
        )
      }
    }

    if (name === serviceBranchCenterConst) {
      const { branch_name: branchName, address, is_active: isActive } = branchInfo
      return {
        ...data,
        value: (
          <div>
            <div>{`${branchName} -  ${address}`}</div>
            <div>Branch status:
              {
                isActive
                  ? <StatusContainer isActive={isActive}> Active</StatusContainer>
                  : <StatusContainer isActive={isActive}> Inactive</StatusContainer>
              }
            </div>
          </div>)
      }
    }

    return (
      {
        ...data,
        value
      }
    )
  })

  return (
    <>
      {
        renderInfo.map(({ label, value, required, events, name, status }) => {
          return (
            <Row
              key={label}
              style={{
                marginBottom: '10px'
              }}
            >
              <Col xs={24} sm={24} md={7} lg={7}>
                <div>
                  <div>
                    {required && (
                      <span
                        style={{
                          color: 'red'
                        }}
                      >
                        *
                      </span>
                    )}
                    &nbsp;
                    <label>
                      <strong>{label}</strong>
                    </label>
                  </div>
                </div>
              </Col>
              <Col
                sm={24}
                md={12}
                style={{
                  display: 'flex',
                  marginBottom: '20px '
                }}
              >
                :&nbsp;&nbsp;{' '}
                <div
                  style={{
                    display: 'flex',
                    flexWrap: 'wrap'
                  }}
                >
                  {value}
                </div>
              </Col>

              <Col
                sm={24}
                md={5}
                style={{
                  float: 'right',
                  // position: 'absolute',
                  top: '0',
                  right: '0'
                }}
              >
                {!!events &&
                  events.map((d, index) => {
                    const permissionToCheck =
                      d.display_name === 'Accept'
                        ? 'ops.document_approve'
                        : 'ops.document_reject'
                    return (
                      <PermissionChecker
                        permissionSetter={permissionToCheck}
                        permissionGetter={permissions}
                        key={index}
                      >
                        <div
                          style={{
                            display: 'inline',
                            marginBottom: '5px',
                            marginRight: '10px',
                            float: 'right'
                          }}
                        >
                          <Button
                            key={index}
                            type={
                              ['Accept', 'Accept by Pasarpolis'].includes(
                                d.display_name
                              )
                                ? 'primary'
                                : 'error'
                            }
                            onClick={() => (confirmReject.bind(thisInstance))(d, name, formName)}
                            style={{
                              width: ['Accept', 'Reject'].includes(d.display_name)
                                ? 80
                                : 170
                            }}
                            disabled={disableEventButtons(status)}
                          >
                            {d.display_name}
                          </Button>
                        </div>
                      </PermissionChecker>
                    )
                  })}
              </Col>
            </Row>
          )
        })
      }
      <PermissionChecker
        permissionGetter={permissions}
        permissionSetter='ops.save_uploaded_document'
      >
        <FormItem>
          <Button
            style={{ float: 'right' }}
            type='primary'
            className='button'
            htmlType='submit'
            disabled
          >
            Save
          </Button>
        </FormItem>
      </PermissionChecker>
    </>

  )
}

const ReduxWrapper = connect((state) => ({
  servicecenterList: state.ServiceCenter.serviceCenterList,
  serviceCenterListLoading: state.Loading.GET_SERVICE_CENTER_LIST,
  serviceCenterListError: state.Error.GET_SERVICE_CENTER_LIST,

  brandList: state.ServiceCenter.brandList
}), {
  resetErrorRedux,
  resetLoadingRedux,
  resetServiceCenterRedux,
  getServiceCenterList,
  getServiceCenterBrandList
})(ViewServiceCenterForm)

export default ReduxWrapper
