import { Fragment, useEffect } from 'react'
import { connect } from 'react-redux'
import { useParams } from 'react-router'
import { Form, Select, Row, Col, Button, Tag, Rate } from 'antd'
import {
  DocumentsAcceptStyle
} from './serviceCenterForm.style'
import PermissionChecker from '../../../../components/permissionChecker'

import claimActions from '../../../redux/claims/actions'
import serviceCenterActions from '../../../redux/serviceCenter/actions'

const {
  getServiceCenterOnClaim,
  getCityListForServiceCenter,
  getServiceCenterBranchOnClaim,
  getPostalCodeForServiceCenter,
  getProvinceListForServiceCenter,
  resetReduxStateClaim
} = claimActions

const {
  getServiceCenterBrandList
} = serviceCenterActions

const { Option } = Select
const FormItem = Form.Item

const brandConst = 'sc_brand'
const provinceConst = 'sc_province'
const cityConst = 'sc_city'
const postalCodeConst = 'sc_postal_code'
const serviceCenterConst = 'service_center'
const serviceBranchCenterConst = 'servicecenter_branch'

function AddressForm ({
  form,
  submitForm,
  cityLoader,
  formData = {},
  getInitValue,
  cityList = [],
  confirmReject,
  provinceLoader,
  permissions = [],
  postalCodeLoader,
  provinceList = [],
  postalCodeList = [],
  serviceBranchList,
  serviceCenterList = [],
  getServiceCenterOnClaim,
  serviceCenterListLoader,
  resetReduxStateClaim,
  serviceCenterBranchLoader,
  getCityListForServiceCenter,
  getServiceCenterBranchOnClaim,
  getPostalCodeForServiceCenter,
  getProvinceListForServiceCenter,
  getServiceCenterBrandList,
  brandListLoading,
  brandList,
  serviceCenterBranchListOnClaimMessage
}) {
  const params = useParams()
  const claimId = params.id

  const { getFieldDecorator } = form
  const { attributes = [] } = formData
  const isBrandAttributeExist = attributes.some(attribute => attribute.name === brandConst)

  useEffect(() => {
    if (isBrandAttributeExist) {
      getServiceCenterBrandList()
    }
  }, [isBrandAttributeExist, getServiceCenterBrandList])

  useEffect(() => {
    const payload = form.getFieldsValue()

    for (const key in payload) {
      if (payload[key] === null) {
        delete payload[key]
      } else {
        const keyName = key.split('---')[0]
        payload[keyName] = payload[key]
        delete payload[key]
      }
    }

    getProvinceListForServiceCenter({
      claim_id: claimId
    })

    if (payload[provinceConst]) {
      getCityListForServiceCenter({
        province_code: payload[provinceConst],
        claim_id: claimId
      })
    }

    if (payload[provinceConst] && payload[cityConst]) {
      getPostalCodeForServiceCenter({
        province_code: payload[provinceConst],
        city_code: payload[cityConst],
        claim_id: claimId
      })
    }
    if (payload[provinceConst] && payload[cityConst] && payload[postalCodeConst]) {
      getServiceCenterOnClaim({
        province_code: payload[provinceConst],
        city_code: payload[cityConst],
        postal_code: payload[postalCodeConst],
        claim_id: claimId
      })
    }
    if (payload[provinceConst] && payload[cityConst] && payload[postalCodeConst] && payload[serviceCenterConst]) {
      getServiceCenterBranchOnClaim({
        province_code: payload[provinceConst],
        city_code: payload[cityConst],
        postal_code: payload[postalCodeConst],
        service_center_code: payload[serviceCenterConst],
        claim_id: claimId
      })
    }
    // eslint-disable-next-line
  }, [
    claimId,
    form.getFieldsValue,
    getCityListForServiceCenter,
    getPostalCodeForServiceCenter,
    getServiceCenterOnClaim,
    getServiceCenterBranchOnClaim,
    getProvinceListForServiceCenter
  ])

  const getOptions = (name) => {
    switch (name) {
      case brandConst:
        return Array.isArray(brandList) ? brandList.map(({ name, code, id }) => ({ value: code, displayName: name })) : []
      case provinceConst:
        return provinceList
      case cityConst:
        return cityList
      case postalCodeConst:
        return postalCodeList
      case serviceCenterConst:
        return serviceCenterList
      case serviceBranchCenterConst:
        return serviceBranchList
      default:
        return []
    }
  }

  const changeHandler = (value, name) => {
    const payload = { ...form.getFieldsValue() }
    for (const key in payload) {
      if (payload[key] === null) {
        delete payload[key]
      } else {
        const keyName = key.split('---')[0]
        payload[keyName] = payload[key]
        delete payload[key]
      }
    }

    switch (name) {
      case brandConst:
        resetReduxStateClaim([
          'cityListOfServiceCenter',
          'postalCodeListOnServiceCenter',
          'serviceCenterOnClaim',
          'serviceCenterBranchListOnClaim',
          'serviceCenterBranchListOnClaimMessage'
        ])
        form.setFieldsValue({
          [`${provinceConst}---${formData.name}`]: null,
          [`${cityConst}---${formData.name}`]: null,
          [`${postalCodeConst}---${formData.name}`]: null,
          [`${serviceCenterConst}---${formData.name}`]: null,
          [`${serviceBranchCenterConst}---${formData.name}`]: null
        })
        return

      case provinceConst:
        getCityListForServiceCenter({
          province_code: value,
          claim_id: claimId
        })

        resetReduxStateClaim([
          'cityListOfServiceCenter',
          'postalCodeListOnServiceCenter',
          'serviceCenterOnClaim',
          'serviceCenterBranchListOnClaim',
          'serviceCenterBranchListOnClaimMessage'
        ])
        form.setFieldsValue({
          [`${cityConst}---${formData.name}`]: null,
          [`${postalCodeConst}---${formData.name}`]: null,
          [`${serviceCenterConst}---${formData.name}`]: null,
          [`${serviceBranchCenterConst}---${formData.name}`]: null
        })
        return

      case cityConst:
        getPostalCodeForServiceCenter({
          province_code: payload[provinceConst],
          city_code: value,
          claim_id: claimId
        })
        resetReduxStateClaim([
          'postalCodeListOnServiceCenter',
          'serviceCenterOnClaim',
          'serviceCenterBranchListOnClaim',
          'serviceCenterBranchListOnClaimMessage'
        ])
        form.setFieldsValue({
          [`${postalCodeConst}---${formData.name}`]: null,
          [`${serviceCenterConst}---${formData.name}`]: null,
          [`${serviceBranchCenterConst}---${formData.name}`]: null
        })
        return

      case postalCodeConst:
        getServiceCenterOnClaim({
          province_code: payload[provinceConst],
          city_code: payload[cityConst],
          postal_code: value,
          claim_id: claimId
        })

        resetReduxStateClaim([
          'serviceCenterOnClaim',
          'serviceCenterBranchListOnClaim',
          'serviceCenterBranchListOnClaimMessage'
        ])

        form.setFieldsValue({
          [`${serviceCenterConst}---${formData.name}`]: null,
          [`${serviceBranchCenterConst}---${formData.name}`]: null
        })
        return

      case serviceCenterConst:
        getServiceCenterBranchOnClaim({
          province_code: payload[provinceConst],
          city_code: payload[cityConst],
          postal_code: payload[postalCodeConst],
          brand: payload[brandConst],
          service_center_code: value
        })

        resetReduxStateClaim([
          'serviceCenterBranchListOnClaim',
          'serviceCenterBranchListOnClaimMessage'
        ])

        form.setFieldsValue({
          [`${serviceBranchCenterConst}---${formData.name}`]: null
        })
        break
      default:
    }
  }

  const getLoadingState = (name) => {
    if (name === brandConst) return brandListLoading
    if (name === provinceConst) return provinceLoader
    if (name === cityConst) return cityLoader
    if (name === postalCodeConst) return postalCodeLoader
    if (name === serviceCenterConst) return serviceCenterListLoader
    if (name === serviceBranchCenterConst) return serviceCenterBranchLoader

    return false
  }

  const getSpecialisation = (name) => {
    const payload = form.getFieldsValue()
    if (name !== serviceBranchCenterConst) return
    if (serviceCenterBranchListOnClaimMessage) return serviceCenterBranchListOnClaimMessage
    if (serviceBranchList &&
      Array.isArray(serviceBranchList) &&
      serviceBranchList.length > 0 &&
      brandList &&
      Array.isArray(brandList)) {
      if (serviceBranchList.find(b => b.specializing)) {
        const selectedBrand = brandList.find(b => b.id === payload[`${brandConst}---${formData.name}`])?.name
        if (selectedBrand) {
          return (
            <div style={{ marginTop: -35 }}>
              <Rate value={1} count={1} />
              specializes in {selectedBrand}
            </div>
          )
        }
      }
    }
  }

  const renderInputType = (form, attribute, initValue, update) => {
    const { name } = attribute
    const loading = getLoadingState(name)
    const options = getOptions(name)

    return (
      <Select
        key={name}
        showSearch
        placeholder='Pilih ...'
        style={{
          width: '100%'
        }}
        onChange={(value) => changeHandler(value, name)}
        filterOption={(input, option) => {
          const search = option?.props?.children?.props?.children

          if (!search) return true

          return (String(search)?.toLowerCase()
            ?.indexOf(input?.toLowerCase()) >= 0)
        }}
        getPopupContainer={() => document.getElementById('area')}
        loading={loading}
      >
        {Array.isArray(options)
          ? options.map(({ value, displayName, specializing = false }) => (
            <Option key={value} value={value}>
              <div style={{
                height: 'auto',
                width: '100%',
                overflow: 'visible'
              }}
              >
                {displayName}
                {specializing
                  ? (
                    <span style={{ marginLeft: 12 }}>
                      <Rate count={1} value={1} />
                    </span>
                    )
                  : null}
              </div>
            </Option>
            ))
          : null}
      </Select>
    )
  }

  const fieldsName = attributes.map(({ name }) => name)
  const identifier = formData.name

  const values = form.getFieldsValue()

  const isDisabled = (
    !provinceList.find(({ value }) => value === values[`${provinceConst}---${formData.name}`]) ||
    !cityList.find(({ value }) => value === values[`${cityConst}---${formData.name}`]) ||
    !postalCodeList.find(({ value }) => value === values[`${postalCodeConst}---${formData.name}`]) ||
    !serviceCenterList?.find(({ value }) => value === values[`${serviceCenterConst}---${formData.name}`]) ||
    !serviceBranchList?.find(({ value }) => value === values[`${serviceBranchCenterConst}---${formData.name}`])
  )

  return (
    <>
      {attributes.map((attribute, index) => {
        const { is_hidden: isHidden } = attribute
        const initValue = getInitValue(attribute)
        return (
          <Fragment key={index}>
            <Row key={index} className={isHidden && 'hidden'}>
              <Col sm={24} md={7} style={{ marginTop: '5px' }}>
                <>
                  <div>
                    {attribute.required && (
                      <span
                        style={{
                          color: 'red'
                        }}
                      >
                        *
                      </span>
                    )}
                    &nbsp;
                    <label>
                      <strong>{attribute.label}</strong>
                    </label>
                  </div>
                  <div>
                    {attribute.status === 'invalid' && (
                      <Tag
                        color='red'
                        style={{
                          whiteSpace: 'unset',
                          height: 'auto'
                        }}
                      >
                        Rejected
                      </Tag>
                    )}
                  </div>
                </>
              </Col>
              <Col xs={24} sm={24} md={11} lg={11}>
                <FormItem>
                  {getFieldDecorator(
                    `${attribute.name}---${formData.name}`,
                    {
                      rules: [
                        {
                          required: attribute.required,
                          message: attribute.required
                            ? `${attribute.label} tidak boleh kosong`
                            : ''
                        }
                      ],
                      initialValue: initValue
                    }
                  )(renderInputType(formData, attribute, initValue))}
                </FormItem>
                <>
                  {getSpecialisation(attribute.name)}
                </>
              </Col>

              <Col xs={24} sm={24} md={6} lg={6}>
                {!!attribute.events &&
                  attribute.events.map((d, index) => {
                    return (
                      <PermissionChecker
                        key={index}
                        permissionSetter='ops.document_approve'
                        permissionGetter={permissions}
                      >
                        <DocumentsAcceptStyle>
                          <Button
                            key={index}
                            type={d.display_name === 'Accept' ? 'primary' : 'error'}
                            onClick={() =>
                              confirmReject(d, attribute.name, formData.name)}
                            style={{
                              width: ['Accept', 'Reject'].includes(d.display_name)
                                ? 80
                                : 170
                            }}
                            disabled={attribute.status !== 'pending'}
                          >
                            {d.display_name}
                          </Button>
                        </DocumentsAcceptStyle>
                      </PermissionChecker>
                    )
                  })}
              </Col>
            </Row>
          </Fragment>
        )
      })}
      <PermissionChecker
        permissionGetter={permissions}
        permissionSetter='ops.save_uploaded_document'
      >
        <FormItem>
          <Button
            style={{ float: 'right' }}
            type='primary'
            className='button'
            htmlType='submit'
            onClick={() =>
              submitForm(
                identifier,
                fieldsName,
                formData.name,
                formData
              )}
            disabled={form.is_valid || isDisabled}
          >
            Save
          </Button>
        </FormItem>
      </PermissionChecker>
    </>

  )
}

const ServiceCenterForm = connect((state) => ({
  cityList: state.Claims.cityListOfServiceCenter,
  provinceList: state.Claims.provinceListOfServiceCenter,
  serviceCenterList: state.Claims.serviceCenterOnClaim,
  serviceBranchList: state.Claims.serviceCenterBranchListOnClaim,
  postalCodeList: state.Claims.postalCodeListOnServiceCenter,

  serviceCenterBranchListOnClaimMessage: state.Claims.serviceCenterBranchListOnClaimMessage,

  provinceLoader: state.Loading.GET_PROVINCE_LIST_FOR_SERVICE_CENTER,
  cityLoader: state.Loading.GET_CITY_LIST_FOR_SERVICE_CENTER,
  postalCodeLoader: state.Loading.GET_POSTAL_CODE_FOR_SERVICE_CENTER,
  serviceCenterListLoader: state.Loading.GET_SERVICE_CENTER_LIST_ON_CLAIM,
  serviceCenterBranchLoader: state.Loading.GET_SERVICE_CENTER_BRANCH_LIST_ON_CLAIM,
  brandListLoading: state.Loading.GET_SERVICE_CENTER_BRAND_LIST,
  brandList: state.ServiceCenter.brandList
}), {
  getServiceCenterBrandList,
  resetReduxStateClaim,
  getServiceCenterOnClaim,
  getCityListForServiceCenter,
  getServiceCenterBranchOnClaim,
  getPostalCodeForServiceCenter,
  getProvinceListForServiceCenter
})(AddressForm)

export default ServiceCenterForm
