import React, { useEffect, useRef, useState } from 'react';
import html2canvas from 'html2canvas';
import { Button, message, notification } from 'antd';
import {
  ButtonContainer,
  CarContainer,
  CarImage,
  Container,
  Marker,
} from './CarSketch.style';

const CarSketch = ({
  claimId,
  value,
  generateSignedUrlAndUpload,
  identifier,
  formIdentifier,
  statusGroup
}) => {
  const imageRef = useRef(null);
  const [selectedParts, setSelectedParts] = useState([]);
  const [svgContent, setSvgContent] = useState('');
  const [error, setError] = useState(null);
  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSketchSaved, setIsSketchSaved] = useState(false);

  useEffect(() => {
    const loadSvg = async () => {
      try {
        const response = await fetch('https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/tap-auto/Car+Frame.svg');
        const svgText = await response.text();
        setSvgContent(svgText);
      } catch (err) {
        console.error('Failed to load SVG', err);
      }
    };
    loadSvg();
  }, []);

  const toggleMarker = (event) => {
    if (!imageRef.current) return;

    const rect = imageRef.current.getBoundingClientRect();
    const offsetX = ((event.clientX - rect.left) / rect.width) * 100;
    const offsetY = ((event.clientY - rect.top) / rect.height) * 100;

    const newMarker = {
      id: `${offsetX}-${offsetY}`,
      top: `${offsetY}%`,
      left: `${offsetX}%`
    };

    setSelectedParts(prev =>
      prev.some(p => p.id === newMarker.id)
        ? prev.filter(p => p.id !== newMarker.id)
        : [...prev, newMarker]
    );
  };

  const clearAllMarkers = () => setSelectedParts([]);

  const validateFile = (file) => {
    const isLt10KB = file.size / 1024 / 1024 < 0.01;
    const isGt10MB = file.size / 1024 / 1024 > 10;

    if (isLt10KB) {
      message.error('Photo too small, min 10KB');
      return false;
    }
    if (isGt10MB) {
      message.error('Photo too large, max 10MB');
      return false;
    }

    const validTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'video/mp4',
      'application/pdf'
    ];

    if (!validTypes.includes(file.type)) {
      notification.error({ message: 'Invalid file type' });
      return false;
    }

    return true;
  };

  const handleSaveSketch = async () => {
    if (!imageRef.current || selectedParts.length === 0) {
      setError(selectedParts.length === 0 ? 'Please select at least one part.' : null);
      return;
    }

    setIsSaving(true);
    setError(null);

    try {
      const canvas = await html2canvas(imageRef.current);

      canvas.toBlob(async (blob) => {
        if (!blob) {
          setIsSaving(false);
          return;
        }

        const sketchFile = new File(
          [blob],
          `car-sketch.png`,
          { type: 'image/png' }
        );

        // Validate the generated file
        if (!validateFile(sketchFile)) {
          setIsSaving(false);
          return;
        }

        // Create the info object
        const info = {
          file: {
            status: 'done',
            size: sketchFile.size,
            type: sketchFile.type,
            name: sketchFile.name,
            originFileObj: sketchFile,
          }
        };

        // Prepare for upload
        setIsUploading(true);
        try {
          await generateSignedUrlAndUpload(info, identifier, formIdentifier, false);
          message.success('Sketch uploaded successfully');
          setIsSketchSaved(true);
        } catch (uploadError) {
          message.error('Failed to upload sketch');
          console.error('Upload error:', uploadError);
        } finally {
          setIsSaving(false);
          setIsUploading(false);
        }
      }, 'image/png');
    } catch (error) {
      setIsSaving(false);
      setIsUploading(false);
      message.error('Failed to save sketch');
      console.error('Error saving sketch:', error);
    }
  };

  return (
    <Container>
        <>
          <CarContainer onClick={toggleMarker} ref={imageRef}>
            <CarImage dangerouslySetInnerHTML={{ __html: svgContent }} />
            {selectedParts.map(({ id, top, left }) => (
              <Marker key={id} style={{ top, left }}>
                X
              </Marker>
            ))}
          </CarContainer>
          {(value && statusGroup !== 'document_reprocess') || isSketchSaved ? (
            null
          ) : (
            <ButtonContainer>
                <Button onClick={clearAllMarkers} type="danger">
                Clear Marker
                </Button>
                <Button
                onClick={handleSaveSketch}
                type="primary"
                loading={isSaving || isUploading}
                disabled={isSaving || isUploading}
                >
                Save Sketch
                </Button>
            </ButtonContainer>
          )}
          {error && <div style={{ color: 'red', marginTop: 8 }}>{error}</div>}
        </>
    </Container>
  );
};

export default CarSketch;
