export const getClaimAmountWithCurrency = (claimAmount, packageCountry) => {
  let currency, locale

  switch (packageCountry) {
    case 'Indonesia':
      currency = 'IDR'
      locale = 'id-ID'
      break
    case 'Singapore':
      currency = 'SGD'
      locale = 'en-SG'
      break
    case 'Thailand':
      currency = 'THB'
      locale = 'th-TH'
      break
    case 'Vietnam':
      currency = 'VND'
      locale = 'vi-VN'
      break
    default:
      currency = 'IDR'
      locale = 'id-ID'
  }

  const formatted = new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
    currencyDisplay: 'code'
  }).format(claimAmount)

  // Force currency code to be in front
  return `${currency} ${formatted.replace(currency, '').trim()}`
}
