import React, { Component } from 'react'
import { connect } from 'react-redux'
import _ from 'lodash/object'
import { Form, Spin, Input, InputNumber, Button, Row, notification, Select } from 'antd'

import { UpdateDetailsWrapper } from './claimDetailComponent.style'
import claimActions from '../../../redux/claims/actions'
import errorAction from '../../../../redux/error/actions'
import loadingAction from '../../../../redux/loading/actions'

const FormItem = Form.Item
const TextArea = Input.TextArea
const { Option } = Select

const { updateDetails, getClaimAllStatus } = claimActions
const { resetErrorRedux } = errorAction
const { resetLoadingRedux } = loadingAction

class UpdateDetail extends Component {
  state = {
    visible: false
  }

  componentDidMount () {
    this.props.getClaimAllStatus()
    this.props.resetLoadingRedux(['UPDATE_DETAILS'])
    this.props.resetErrorRedux(['UPDATE_DETAILS'])
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      updateDetailsLoading,
      updateDetailsError,
      updateDetailsMessage,
      showUpdateDetailsModal
    } = nextProps
    const { visible } = this.state
    if (updateDetailsLoading === false) {
      if (updateDetailsError === false) {
        this.props.alterModal('showUpdateDetailsModal', false)
      }
      notification[updateDetailsError ? 'error' : 'success']({ message: updateDetailsMessage })
      this.props.resetLoadingRedux(['UPDATE_DETAILS'])
      this.props.resetErrorRedux(['UPDATE_DETAILS'])
    }
    if (showUpdateDetailsModal !== visible) {
      this.setState({ visible: showUpdateDetailsModal })
      if (!showUpdateDetailsModal) {
        this.props.form.resetFields()
      }
    }
  }

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((error, values) => {
      if (!error) {
        const { detailData, type } = this.props
        const claimID = _.get(detailData, 'claim_id')
        this.props.updateDetails({
          query: {
            claim_id: claimID
          },
          body: {
            ...values,
            update_type: type === 'amount' ? 'amount' : 'status'
          }
        })
      }
    })
  }

  render () {
    const { type, form, updateDetailsLoading, allClaimStatusLoading, allClaimStatus = [] } = this.props
    const { getFieldDecorator } = form
    const TypeAmount = type === 'amount'

    return (
      <UpdateDetailsWrapper>
        <Spin spinning={!!updateDetailsLoading}>
          <Form onSubmit={this.handleSubmit}>
            <label>
              {TypeAmount ? 'Amount' : 'Claim State'}
            </label>
            <FormItem>
              {
                getFieldDecorator(TypeAmount ? 'amount' : 'status',
                  {
                    rules: [
                      {
                        required: true,
                        message: `${TypeAmount ? 'Amount' : 'Claim State'} tidak boleh kosong`
                      }
                    ]
                  }
                )(TypeAmount
                  ? <InputNumber min={0} placeholder='Enter Amount' />
                  : <Select
                      showSearch
                      placeholder='Select Claim State'
                      loading={!!allClaimStatusLoading}
                      dropdownMatchSelectWidth={false}
                      optionFilterProp='children'
                      filterOption={(input, option) =>
                        option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                    >
                    {
                      allClaimStatus.map(status => <Option key={status} value={status}>{status}</Option>)
                    }
                  </Select>
                )
              }
            </FormItem>
            <label>Remarks</label>
            <FormItem>
              {
                getFieldDecorator('remarks',
                  {
                    rules: [
                      {
                        required: true,
                        message: 'Remarks tidak boleh kosong'
                      }
                    ]
                  }
                )(<TextArea placeholder='Enter Remarks' />
                )
              }
            </FormItem>
            <Row type='flex' justify='end'>
              <Button
                type='primary'
                htmlType='submit'
              >
                {`Update Claim ${TypeAmount ? 'Amount' : 'State'}`}
              </Button>
            </Row>
          </Form>
        </Spin>
      </UpdateDetailsWrapper>
    )
  }
}

const WrappedUpdateDetail = Form.create()(UpdateDetail)

export default connect(state => ({
  updateDetailsLoading: state.Loading.UPDATE_DETAILS,
  updateDetailsError: state.Error.UPDATE_DETAILS,
  updateDetailsMessage: state.Claims.updateDetailsMessage,

  allClaimStatus: state.Claims.allClaimStatus,
  allClaimStatusLoading: state.Loading.GET_CLAIM_ALL_STATUS
}), {
  updateDetails,
  getClaimAllStatus,
  resetLoadingRedux,
  resetErrorRedux
})(WrappedUpdateDetail)
