import { Col, Row, Button } from 'antd'
import PermissionChecker from '../../../../components/permissionChecker'

const provinceConst = 'sc_province'
const cityConst = 'sc_city'
const workshopConst = 'sc_workshop'

const workshopFieldNames = [provinceConst, cityConst, workshopConst]

function ViewWorkshopSelectionForm ({
  thisInstance,
  formName,
  attributes = [],
  permissions = [],
  confirmReject,
  disableEventButtons
}) {
  const renderInfo = attributes.map(({ value, name, label, required, events, status }) => ({
    name,
    label,
    required,
    events,
    status,
    value: workshopFieldNames.includes(name) ? value : value
  }))

  return (
    <>
      {renderInfo.map(({ label, value, required, events, name, status }) => {
        return (
          <Row
            key={name}
            style={{
              marginBottom: '10px'
            }}
          >
            <Col xs={24} sm={24} md={7} lg={7}>
              <div>
                <div>
                  {required && (
                    <span
                      style={{
                        color: 'red'
                      }}
                    >
                      *
                    </span>
                  )}
                  &nbsp;
                  <label>
                    <strong>{label}</strong>
                  </label>
                </div>
              </div>
            </Col>
            <Col
              sm={24}
              md={12}
              style={{
                display: 'flex',
                marginBottom: '20px '
              }}
            >
              :&nbsp;&nbsp;{' '}
              <div
                style={{
                  display: 'flex',
                  flexWrap: 'wrap'
                }}
              >
                {value}
              </div>
            </Col>

            <Col
              xs={24}
              sm={24}
              md={5}
              style={{
                float: 'right',
                top: '0',
                right: '0'
              }}
            >
              {!!events &&
                events.map((d, index) => {
                  const permissionToCheck =
                    d.display_name === 'Accept'
                      ? 'ops.document_approve'
                      : 'ops.document_reject'
                  return (
                    <PermissionChecker
                      permissionSetter={permissionToCheck}
                      permissionGetter={permissions}
                      key={index}
                    >
                      <div
                        style={{
                          display: 'inline',
                          marginBottom: '5px',
                          marginRight: '10px',
                          float: 'right'
                        }}
                      >
                        <Button
                          key={index}
                          type={
                            ['Accept', 'Accept by Pasarpolis'].includes(
                              d.display_name
                            )
                              ? 'primary'
                              : 'error'
                          }
                          onClick={() => (confirmReject.bind(thisInstance))(d, name, formName)}
                          style={{
                            width: ['Accept', 'Reject'].includes(d.display_name)
                              ? 80
                              : 170
                          }}
                          disabled={disableEventButtons(status)}
                        >
                          {d.display_name}
                        </Button>
                      </div>
                    </PermissionChecker>
                  )
                })}
            </Col>
          </Row>
        )
      })}
    </>
  )
}

export default ViewWorkshopSelectionForm
