import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Col, Icon, Row, Tag } from 'antd'
import { get } from 'lodash'

import { ClaimDetailSectionStyle } from './claimDetailComponent.style'
import PermissionCheckerV2 from '../../../../components/permissionCheckerV2'
import EditIcon from '../../../../image/pencil-icon.png'
import { ViewWorkOrderDocument } from './index.style'
import UserFraudComponent from './userFraudComponent'
import { replaceAgentAndAgencyDash } from 'opsModule/helpers'
import { getClaimAmountWithCurrency } from '../../../../utilities'

const STATUS_FOR_NOT_UPDATE_CLAIM_DETAIL = ['rejected']

const serviceCenterTitle = [
  {
    dataIndex: 'service_center_repair_quoatation',
    title: 'Service Center Repair Quotation',
    type: 'image'
  }, {
    dataIndex: 'service_center_repair_final_invoice',
    title: 'Service Center Repair Final Invoice',
    type: 'image'
  }, {
    dataIndex: 'service_center_customer_deductible',
    title: 'Service Center Customer Deductible'
  }, {
    dataIndex: 'service_center_cancellation_fee',
    title: 'Service Center Cancellation Fee'
  }, {
    dataIndex: 'service_center_total_spare_part_cost',
    title: 'Service Center Total Spare Part Cost'
  }, {
    dataIndex: 'service_center_delivery_cost',
    title: 'Service Center Delivery Cost'
  }, {
    dataIndex: 'service_center_vat',
    title: 'Service Center Vat'
  }, {
    dataIndex: 'service_center_pickup_airwaybill_number',
    title: 'Service Center Pickup Airwaybill Number'
  }, {
    dataIndex: 'service_center_delivery_airwaybill_number',
    title: 'Service Center Delivery Airwaybill Number'
  }, {
    dataIndex: 'service_center_inhouse_repiar_cost',
    title: 'Service Center Inhouse/external Repiar Cost'
  }, {
    dataIndex: 'service_center_cancellation_fee_invoice',
    title: 'Service Center Cancellation Fee Invoice',
    type: 'image'
  }, {
    dataIndex: 'service_center_service_cost',
    title: 'Service Center Service Cost'
  }, {
    dataIndex: 'service_center_beyond_economic_repair',
    title: 'Service Center Beyond Economic Repair'
  }, {
    dataIndex: 'service_center_ber_invoice',
    title: 'Service Center Beyond Economic Repair Invoice',
    type: 'image'
  }
]

class ClaimDetailSection extends Component {
  renderKeyValue = (key, value) => {
    return (
      <Col span={8} className='item-container' key={key}>
        <div className='header'>{key}</div>
        <div className='value'>{value ?? '-'}</div>
      </Col>
    )
  }

  render () {
    const { claimDetail = {}, policyDetail = {} } = this.props
    const {
      claim_no: claimNumber, application_no: applicationNumber, policy_number: policyNumber,
      display_name: productName, benefit, package_name: packageName, provider_claim_id: providerClaimIID,
      claim_amount: claimAmount, user_email: userEmail, user_phone: userPhone, user_name: userName,
      source, feedback_details: feedbackDetails, user_claim_history: userClaimHistory = [], status_group: statusGroup,
      work_order_release_document: workOrderReleaseDocument, type, agent_user_name: agentUserName, agent_user_email: agentUserEmail,
      agent_user_phone: agentUserPhone, user_status: userFraudStatus, claim_id: claimId,
      policy_holder_name: policyHolderName, policy_holder_phone: policyHolderPhone, policy_holder_email: policyUserEmail,
      package_country: packageCountry
    } = claimDetail
    const { policyEndDate, Name, Email, MobileNo } = policyDetail

    const serviceCenterDetails = serviceCenterTitle.map(({ title, dataIndex, type }) => {
      if (claimDetail[dataIndex] === null || claimDetail[dataIndex] === undefined) {
        return {
          header: title,
          value: null
        }
      }

      if (type === 'image') {
        return ({
          header: title,
          value: (
            <ViewWorkOrderDocument
              href={claimDetail[dataIndex]}
              target='_blank'
              rel='noreferrer'
              style={{ color: '#2DB7F5' }}
            >
              view
              <Icon type='eye' className='icon' />
            </ViewWorkOrderDocument>)
        })
      }

      return {
        header: title,
        value: claimDetail[dataIndex]
      }
    }).filter(({ header, value }) => !(value === null || value === undefined))

    let claimData = [{
      header: 'Claim ID',
      value: claimNumber
    }, {
      header: 'Application Number',
      value: (
        <PermissionCheckerV2 requiredPermission='ops.view_application_number_detail'>
          {/* <span className='link' onClick={() => this.props.onPolicyClick(applicationNumber, 'appNo')}> */}
          <span className='link' onClick={() => this.props.onPolicyClick(applicationNumber, 'applicationNo')}>
            {applicationNumber}
          </span>
        </PermissionCheckerV2>
      )
    }, {
      header: 'Policy Number',
      value: (
        <PermissionCheckerV2 requiredPermission='ops.view_policy_number_detail'>
          <span className='link' onClick={() => this.props.onPolicyClick(policyNumber, 'insurancePolicyNo')}>
            {/* <span className='link' onClick={() => this.props.onPolicyClick(policyNumber, 'PolicyNo')}> */}
            {policyNumber}
          </span>
        </PermissionCheckerV2>
      )
    }, {
      header: 'Product Name',
      value: replaceAgentAndAgencyDash(productName)
    }, {
      header: 'Package Name',
      value: replaceAgentAndAgencyDash(packageName)
    }, {
      header: 'Benefit',
      value: benefit
    }, {
      header: 'Provider Claim ID',
      value: providerClaimIID
    }, {
      header: 'Policy End Date',
      value: policyEndDate
    }, {
      header: 'Claim Amount',
      value: (
        <span>
          {getClaimAmountWithCurrency(claimAmount, packageCountry)}
          {!STATUS_FOR_NOT_UPDATE_CLAIM_DETAIL.includes(statusGroup) &&
            <PermissionCheckerV2 requiredPermission='ops.update_claim_details'>
              <img
                src={EditIcon}
                width={18}
                className='btn-icon-pencil'
                onClick={() => this.props.onUpdateModal('amount')}
                alt='amount'
              />
            </PermissionCheckerV2>}
        </span>
      )
    }, {
      header: 'User Email',
      value: userEmail
    }, {
      header: 'User Phone',
      value: userPhone
    }, {
      header: 'Source',
      value: source
    },
    ...serviceCenterDetails,
    ...(userFraudStatus
      ? [{
          header: 'User Fraud Status',
          value: <UserFraudComponent
            claimId={claimId}
            userFraudStatus={userFraudStatus}
                 />
        }]
      : [])
    ]

    if (type === 'agency') {
      const agencyData = [
        {
          header: 'Work Order Release Document',
          value: workOrderReleaseDocument && (
            <ViewWorkOrderDocument
              href={workOrderReleaseDocument}
              target='_blank'
              rel='noreferrer'
              style={{ color: '#2DB7F5' }}
            >
              view <Icon type='eye' className='icon' />
            </ViewWorkOrderDocument>
          )
        },
        {
          header: 'Mitra Name',
          value: agentUserName
        },
        {
          header: 'Mitra Email',
          value: agentUserEmail
        },
        {
          header: 'Mitra Phone',
          value: agentUserPhone
        }
      ]
      claimData = claimData.concat(agencyData)
    }

    const policyData = [{
      header: 'Policy Holder Name',
      value: Name || policyHolderName || userName
    }, {
      header: 'Policy Holder Email',
      value: Email || policyUserEmail || userEmail
    }, {
      header: 'Policy Holder Phone',
      value: MobileNo || policyHolderPhone || userPhone
    }]

    return (
      <ClaimDetailSectionStyle>
        <Row type='flex' justify='space-between'>
          {
            claimData.map(({ header, value }) => this.renderKeyValue(header, value))
          }
          {
            policyData.map(({ header, value }) => this.renderKeyValue(header, value))
          }
        </Row>

        <div>
          <div className='header'> Customer Feedback</div>
          {
            get(feedbackDetails, 'is_rated')
              ? (
                <>
                  <div>
                    <span className='sub-heading'>Rating: </span> <Tag color='#13C2C2'>{get(feedbackDetails, 'feedback_rating')}</Tag>
                  </div>
                  <div>
                    <span className='sub-heading'>Comment: </span> <span>{get(feedbackDetails, 'feedback_review')}</span>
                  </div>
                </>
                )
              : '-'
          }
        </div>
        <div>
          <div className='header'>Claim History</div>
          {
            userClaimHistory.map(
              ({ claim_number: claimNumber, claim_id: claimID }) => (
                <div key={`claimAnchor_${claimID}`}>
                  <a
                    href={claimID}
                    target='_blank'
                    rel='noopener noreferrer'
                  >
                    {claimNumber}
                  </a>
                </div>
              )
            )
          }
        </div>
      </ClaimDetailSectionStyle>
    )
  }
}

export default connect(state => ({
  policyDetail: state.Insurance.policyDetail
}), {
})(ClaimDetailSection)
