import { useErrorContextValue, useLoaderContextValue, usePost } from '@pasarpolis/common-react-hooks'
import { Button, Col, Icon, message, Modal, notification, Spin, Upload } from 'antd'
import { useEffect, useState, useRef } from 'react'
import { uploadImgApiConfig } from '../apiConfig'
import { UploadImgStyleWrapper } from './index.style'
import { Document, Page } from 'react-pdf/dist/esm/entry.webpack'

const dummyRequest = ({ file, onSuccess }) => {
  setTimeout(() => {
    onSuccess('ok')
  }, 0)
}

const getLoaderKey = (name) => String(name).split(' ').join('_').toUpperCase() + '_LOADER'
const getErrorKey = (name) => String(name).split(' ').join('_').toUpperCase() + '_ERROR'
const getDataKey = (name) => String(name).split(' ').join('_').toUpperCase()

const UploadImgContainer = ({ attribute, state, setState, form }) => {
  const { getFieldDecorator, setFieldsValue } = form
  const errorKey = getErrorKey(attribute.name)
  const loaderKey = getLoaderKey(attribute.name)
  const [showPdfModal, setShowPdfModal] = useState(false)
  const [pdfFile, setPdfFile] = useState(null)
  const [numPage, setNumPage] = useState(null)
  const [pdfRotation, setPdfRotation] = useState(0)

  const downloadRef = useRef(null)

  const [response, uploadRequest] = usePost(uploadImgApiConfig(getDataKey(attribute.name)))
  const [{ [errorKey]: ERROR_KEY }] = useErrorContextValue()
  const [{ [loaderKey]: LOADER_KEY }] = useLoaderContextValue()

  const handleChange = (info) => {
    if (info.file.status === 'done' || info.file.status === 'error') {
      const isLt10KB = info.file.size / 1024 / 1024 < 0.01
      const isGt20000KB = info.file.size / 1024 / 1024 > 20
      if (isLt10KB) {
        message.error('Photo terlalu kecil, min 10kb')
        return
      }
      if (isGt20000KB) {
        message.error('Photo terlalu besar, max 20mb')
        return
      }
      if (
        (info.file.type === 'image/jpeg' ||
          info.file.type === 'image/jpg' ||
          info.file.type === 'image/png' ||
          info.file.type === 'application/pdf') &&
        !isLt10KB &&
        !isGt20000KB
      ) {
        const file = info.file.originFileObj
        try {
          const formData = new FormData()
          formData.append('file', file)
          uploadRequest(formData)
        } catch (error) {
          message.error('Ada yang bermasalah, reload dan ulangi kembali')
        }
      } else {
        notification.error({ message: 'Check your file type' })
      }
    }
  }

  const renderImage = (value) => {
    if (value?.length > 0) {
      if (Array.isArray(value)) {
        return value.map((val, index) => {
          if (val.search('.pdf') > -1) {
            return (
              <div key={index} className='display-image'>
                <a href={val} target='_blank' rel='noopener noreferrer' className='file-link'>
                  View File
                </a>
              </div>
            )
          }
          return (
            <div key={index} className='image-container'>
              <img className='single-image' src={val} alt='document' />
            </div>
          )
        })
      } else if (value.toLowerCase().endsWith('.pdf')) {
        return (
          <div className='display-image'>
            <div
              className='file-link'
              style={{ cursor: 'pointer', color: '#0000FF' }}
              onClick={() => handlePDFOpen(value)}
            >
              View File
            </div>
          </div>
        )
      } else {
        return <img className='image' src={value} alt='document' />
      }
    }
    return ''
  }

  const imgComponent = <div className='image-component'>{renderImage(response?.url)}</div>

  const renderUpload = (value) => {
    const uploadedUrl = response?.url
    const disableButton = !!uploadedUrl?.length
    return (
      <Upload
        name='avatar'
        accept='.jpeg,.png,.jpg,.pdf,.doc,.docx'
        showUploadList={false}
        multiple={false}
        customRequest={dummyRequest}
        onChange={(file) => handleChange(file, value.name)}
      >
        <Button className='upload-btn' disabled={disableButton}>
          <Icon type='upload' />
          Upload
        </Button>
      </Upload>
    )
  }

  useEffect(() => {
    if (ERROR_KEY) {
      message.error('Image failed to upload. Please try again')
    }
  }, [ERROR_KEY])

  useEffect(() => {
    if (response?.url) {
      setFieldsValue({ [attribute.name]: response.url })
    }
  }, [response, setFieldsValue, attribute])

  const handlePDFOpen = (value) => {
    setShowPdfModal(true)
    setPdfFile(value)
  }

  const handlePDFClose = () => {
    setShowPdfModal(false)
    setPdfFile(null)
    setNumPage(null)
  }

  const handleOnDocumentLoadSuccess = ({ numPages }) => {
    setNumPage(numPages)
  }

  const getCurrentPageOrientation = () =>
    pdfRotation === 90 || pdfRotation === 270 || pdfRotation === -90 || pdfRotation === -270
      ? 'landscape'
      : 'portrait'

  const handleRotateLeftPDF = () => {
    setPdfRotation((prev) => prev - 90)
  }

  const handleRotateRightPDF = () => {
    setPdfRotation((prev) => prev + 90)
  }

  const handleDownload = () => {
    if (downloadRef.current && pdfFile) {
      downloadRef.current.href = pdfFile
      downloadRef.current.download = 'document.pdf'
      downloadRef.current.click()
    }
  }

  const renderPDFModal = () => {
    return (
      <Modal
        title='PDF Viewer'
        visible={showPdfModal}
        onCancel={handlePDFClose}
        footer={null}
        width={getCurrentPageOrientation() === 'landscape' ? '90%' : '60%'}
        bodyStyle={{
          overflow: 'auto',
          display: 'flex',
          justifyContent: 'center',
          paddingBottom: '60px'
        }}
      >
        {pdfFile && (
          <Document
            file={pdfFile}
            onLoadSuccess={handleOnDocumentLoadSuccess}
            onLoadError={(error) => console.error('Error while loading document:', error)}
          >
            <Page pageNumber={1} rotate={pdfRotation} />
            {numPage > 1 &&
              Array.from({ length: numPage - 1 }, (_, index) => (
                <Page key={index + 2} pageNumber={index + 2} rotate={pdfRotation} />
              ))}
            <div
              style={{
                position: 'fixed',
                bottom: 0,
                width: getCurrentPageOrientation() === 'landscape' ? '90%' : '60%',
                backgroundColor: '#fff',
                padding: '10px 20px',
                borderTop: '1px solid #ddd',
                textAlign: 'right',
                zIndex: 1000,
                display: 'flex',
                gap: '16px',
                alignItems: 'center',
                justifyContent: 'flex-end'
              }}
            >
              <Button type='default' onClick={handleRotateLeftPDF}>
                <Icon type='rollback' style={{ fontSize: 20 }} />
              </Button>
              <Button type='default' onClick={handleRotateRightPDF}>
                <Icon type='rollback' style={{ fontSize: 20, transform: 'scaleX(-1)' }} />
              </Button>
              <Button key='download' type='primary' onClick={handleDownload}>
                Download
              </Button>
              <a ref={downloadRef} style={{ display: 'none' }} rel='noopener noreferrer' />
            </div>
          </Document>
        )}
      </Modal>
    )
  }

  return (
    <UploadImgStyleWrapper>
      {getFieldDecorator(attribute.name)}
      <Spin spinning={!!LOADER_KEY} tip='Uploading ...'>
        {renderUpload(attribute)}
        {renderPDFModal()}
        <Col>{imgComponent}</Col>
      </Spin>
    </UploadImgStyleWrapper>
  )
}
export default UploadImgContainer
