import React, { Component } from 'react'
import { Row, Col, Button } from 'antd'
import { get, map, find } from 'lodash'

import { ClaimDetailHeaderStyle, StatusTag } from './claimDetailComponent.style'
import PermissionCheckerV2 from '../../../../components/permissionCheckerV2'
import EditIcon from '../../../../image/pencil-icon.png'
import AssignOwnerDropdown from '../assignOwnerDropdown'

const STATUS_FOR_NOT_UPDATE_CLAIM_DETAIL = ['rejected']
const STATUS_FOR_NOT_UPDATE_BANK_DETAIL = ['initiated', 'rejected', 'settled']
const OWNER_ROLES_WITHOUT_ASSIGN = ['INSURANCE_CLAIM_HANDLER']

class ClaimDetailHeader extends Component {
  render () {
    const { claimDetail = {} } = this.props
    const {
      status = {}, status_group: statusGroup, owner_role: ownerRole, owner_id: ownerID, payment_forms: paymentForms,
      next_followup_date: nextFollowupDate, forms = []
    } = claimDetail
    const formNames = map(forms, 'name')

    return (
      <ClaimDetailHeaderStyle>
        <Row type='flex' justify='space-between'>
          <Col span={8}>
            <Row type='flex'>
              <div className='header'>Status: </div>
              <StatusTag color='#13c2c2'>
                {get(status, 'display_name', '-')}
              </StatusTag>
              {!STATUS_FOR_NOT_UPDATE_CLAIM_DETAIL.includes(statusGroup) &&
                <PermissionCheckerV2 requiredPermission='ops.update_claim_details'>
                  <img src={EditIcon} width={18} className='btn-icon-pencil' onClick={() => this.props.onUpdateModal('status')} alt='Status' />
                </PermissionCheckerV2>}
            </Row>
          </Col>
          <Col span={6}>
            {!OWNER_ROLES_WITHOUT_ASSIGN.includes(ownerRole) && (
              <PermissionCheckerV2 requiredPermission='ops.add_claim_owner'>
                <AssignOwnerDropdown claimId={this.props.match.params.id} currentOwnerId={ownerID} />
              </PermissionCheckerV2>
            )}
          </Col>
          <Col span={10}>
            <Row type='flex' justify='end'>
              <Col>
                {
                  !STATUS_FOR_NOT_UPDATE_BANK_DETAIL.includes(statusGroup) &&
                  (formNames.includes('bank-details') ||
                    formNames.includes('bank-details-without-validation') ||
                    find(paymentForms, { name: 'bank-details' })
                  ) &&
                  (
                    <PermissionCheckerV2 requiredPermission='ops.update_bank_detail'>
                      <Button
                        type='primary'
                        onClick={this.props.onUpdateBankDetailsClick}
                      >
                        Update Bank Detail
                      </Button>
                    </PermissionCheckerV2>
                  )
                }
              </Col>
              <Col>
                <PermissionCheckerV2 requiredPermission='ops.soft_delete_claims'>
                  <Button
                    type='danger'
                    onClick={this.props.onClickDelete}
                  >
                    Delete this claim
                  </Button>
                </PermissionCheckerV2>
              </Col>
              <Col>
                <PermissionCheckerV2 requiredPermission='ops.next_follow_up'>
                  <Button
                    type='primary'
                    onClick={() => this.props.nextFollowUpVisible()}
                  >
                    Next followup
                  </Button>
                </PermissionCheckerV2>
              </Col>
              <Col>
                {
                  !!nextFollowupDate && (
                    <Button type='primary' onClick={() => this.props.completeFollowUpVisible()}>
                      Close followup
                    </Button>
                  )
                }
              </Col>
            </Row>
          </Col>
        </Row>
      </ClaimDetailHeaderStyle>
    )
  }
}

export default ClaimDetailHeader
