import React, { Component } from 'react'
import { connect } from 'react-redux'
import _ from 'lodash/object'
import { Modal, Form, Select, Input, Button, Row, notification, Spin } from 'antd'
import ClaimActions from '../../redux/claims/actions'
import errorAction from '../../../redux/error/actions'
import loadingAction from '../../../redux/loading/actions'
import { UpdateBankDetailsStyled } from './updateBankDetails.style'

const Option = Select.Option

const { verifyBankData, updateBankDetails } = ClaimActions
const { resetErrorRedux } = errorAction
const { resetLoadingRedux } = loadingAction

class UpdateBankDetail extends Component {
  state = {
    showUpdateBankDetailForm: false,
    showBankAccountHolderName: false,
    accountHolderName: ''
  }

  componentDidMount () {
    this.setState({ showUpdateBankDetailForm: this.props.showUpdateBankDetailForm })
    this.props.form.resetFields()
    this.props.resetLoadingRedux(['VERIFY_BANK_ACCOUNT'])
    this.props.resetErrorRedux(['VERIFY_BANK_ACCOUNT'])
  }

  componentWillReceiveProps (nextProps) {
    const {
      verifyBankAccountLoading,
      verifyBankAccountError,
      verifyAccountDataStatus,
      verifyAccountData
    } = nextProps

    if (nextProps.showUpdateBankDetailForm !== this.state.showUpdateBankDetailForm) {
      this.setState({ showUpdateBankDetailForm: nextProps.showUpdateBankDetailForm, showBankAccountHolderName: false, accountHolderName: '' })
      this.props.form.resetFields()
    }
    if (verifyBankAccountLoading === false) {
      if (verifyBankAccountError === false) {
        this.setState({ showBankAccountHolderName: true, accountHolderName: _.get(verifyAccountData, 'account_holder_name', '') })
      }
      notification[verifyBankAccountError ? 'error' : 'success']({ message: verifyAccountDataStatus })
      this.props.resetLoadingRedux(['VERIFY_BANK_ACCOUNT'])
      this.props.resetErrorRedux(['VERIFY_BANK_ACCOUNT'])
    }
  }

  renderInputType = attribute => {
    const { claimBankList = [] } = this.props
    const { showBankAccountHolderName } = this.state
    const { type, is_hidden: isHidden, name: attributeName } = attribute
    switch (type) {
      case 'choices':
        return <Select
          showSearch
          placeholder='Pilih ...'
          disabled={showBankAccountHolderName}
          style={{
            width: '100%'
          }}
          dropdownMatchSelectWidth={false}
          filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}>
          {
            !isHidden && (
              attributeName === 'bank_name'
                ? claimBankList.map(bank => (
                  <Option key={bank[0]} value={bank[0]}>
                    {bank[1]}
                  </Option>
                ))
                : attribute.options.map((bank, index) => (<Option key={index} value={bank[0]}>
                  {bank[1]}
                </Option>
                ))
            )
          }
        </Select>
      default:
        return <Input
          disabled={showBankAccountHolderName}
          type={attribute.type}
        />
    }
  }

  handleUpdateBankDetailsSubmit = e => {
    e.preventDefault()
    const { claimId, bankForm } = this.props
    const { accountHolderName, showBankAccountHolderName } = this.state

    this.props.form.validateFields((err, values) => {
      if (!err) {
        values['master_bank_id'] = values['bank_name']
        values['bank_code'] = values['bank_name']
        if (bankForm.name !== 'bank-details-without-validation') {
          if (!showBankAccountHolderName) {
            this.props.verifyBankData({ body: values, query: { claim_id: claimId } })
          } else {
            values['account_holder_name'] = accountHolderName
            this.props.updateBankDetails({ body: values, query: { claim_id: claimId } })
          }
        } else {
          this.props.updateBankDetails({ body: values, query: { claim_id: claimId } })
        }
      }
    })
  }

  renderAccountHolderName = (attribute) => {
    const { showBankAccountHolderName, accountHolderName } = this.state

    return showBankAccountHolderName &&
      <div className='acc-holder-name-container' key={attribute.label} >
        <div className='acc-holder-name-label'>{attribute.label}</div>
        <div className='acc-holder-name-value'>{accountHolderName}</div>
      </div>
  }

  render () {
    const { bankForm, showUpdateBankDetailForm, form, verifyBankAccountLoading, updateBankDetailsLoading } = this.props
    const { showBankAccountHolderName } = this.state
    const { getFieldDecorator } = form
    const formName = _.get(bankForm, 'name', '')

    return (
      <Modal
        visible={showUpdateBankDetailForm}
        title={'Update Bank Detail'}
        onCancel={() => this.props.updateVisibleState()}
        footer={null}
      >
        <Spin spinning={!!verifyBankAccountLoading || !!updateBankDetailsLoading}>
          <UpdateBankDetailsStyled>
            <Form onSubmit={this.handleUpdateBankDetailsSubmit}>
              {
                bankForm.attributes && bankForm.attributes.map(attribute => {
                  if (bankForm.name !== 'bank-details-without-validation' && attribute.name === 'account_holder_name') {
                    return this.renderAccountHolderName(attribute)
                  } else {
                    return (
                      <Form.Item key={attribute.label} label={attribute.label} style={{ marginBottom: '0px' }} className={_.get(attribute, 'is_hidden') && 'hidden'}>
                        {getFieldDecorator(attribute.name, {
                          initialValue: attribute.value,
                          rules: [{ required: attribute.required }]
                        })(
                          this.renderInputType(attribute)
                        )}
                      </Form.Item>
                    )
                  }
                }
                )
              }
              <Form.Item>
                <Row type='flex' justify='end'>
                  <Button htmlType='submit' type='primary' className='submit-button'>
                    {
                      formName !== 'bank-details-without-validation' && !showBankAccountHolderName
                        ? 'Verify'
                        : 'Update'
                    }
                  </Button>
                </Row>
              </Form.Item>
            </Form>
          </UpdateBankDetailsStyled>
        </Spin>
      </Modal>
    )
  }
}

const WrappedUpdateBankDetail = Form.create()(UpdateBankDetail)

export default connect(state => ({
  verifyBankAccountLoading: state.Loading.VERIFY_BANK_ACCOUNT,
  verifyBankAccountError: state.Error.VERIFY_BANK_ACCOUNT,
  verifyAccountData: state.Claims.verifyAccountData,
  verifyAccountDataStatus: state.Claims.verifyAccountDataStatus,

  updateBankDetailsLoading: state.Loading.UPDATE_BANK_DETAILS,
  claimBankList: state.Claims.claimBankList
}), {
  verifyBankData,
  updateBankDetails,
  resetLoadingRedux,
  resetErrorRedux
})(WrappedUpdateBankDetail)
