import React from 'react'
import { connect } from 'react-redux'
import {
  Select,
  Form,
  Input,
  Button,
  Modal,
  notification,
  Spin,
  message,
  Tooltip,
  InputNumber,
  Row,
  DatePicker,
  TimePicker,
} from 'antd'
import validator from '../../../helpers/validator'
import claimActions from '../../redux/claims/actions'
import errorAction from '../../../redux/error/actions'
import loadingAction from '../../../redux/loading/actions'
import { PopupStyleWrapper } from './popup.style'
import UploadImg from './UploadImg'
import UploadFile from './UploadFile'

import { timezoneOptions } from '../../../helpers/constant'

import moment from 'moment'
import momentTimezone from 'moment-timezone'
import MultiBenefitAutoApprovalEvent from './MultiBenefitAutoApprovalEvent'

const { Option } = Select
const FormItem = Form.Item
const { TextArea } = Input

const { resetReduxStateClaim,
  submitEvent,
  uploadImage,
  submitEventSalvage,
  sumbitAutoApprovalMultiBenefitData } = claimActions
const { resetErrorRedux } = errorAction
const { resetLoadingRedux } = loadingAction

function disableDateRanges(range = { startDate: false, endDate: false }) {
  const { startDate, endDate } = range
  return function disabledDate(current) {
    let startCheck = true
    let endCheck = true
    if (startDate) {
      startCheck = current && current < moment(startDate, 'YYYY-MM-DD')
    }
    if (endDate) {
      endCheck = current && current > moment().endOf('day')
    }
    return (startDate && startCheck) || (endDate && endCheck)
  }
}

class PopupForm extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      loaderSuccessSubmitEvent: false,
      submitEventLoader: false,
      getStatusSubmitEvent: '',
      uploadLoader: false,
      uploadedUrl: [],
      openCommentBox: false,
      userSelectedTimezone: 'Asia/Jakarta',
      userSelectedDate: undefined,
      selectedBenefit: [],
      multiBenefitAutoApprovalPayload: {},
      selectedComment: '',
      fileList: [],
      selectedRemarks: this.handleDefaultValue(props.mainEvent.code) || '',
    }
  }

  componentDidMount() {
    this.props.resetLoadingRedux(['SUBMIT_EVENTS_CLAIM', 'SUBMIT_EVENTS_SALVAGE'])
    this.props.resetErrorRedux(['SUBMIT_EVENTS_CLAIM', 'SUBMIT_EVENTS_SALVAGE'])
  }

  UNSAFE_componentWillReceiveProps(nextProps) {
    const {
      getStatusSubmitEvent, getSubmitEventLoading, getSubmitEventError,
      getSubmitSalvageEventLoading, getSubmitSalvageEventError,
      sumbitAutoApprovalMultiBenefitDataMessage,
      sumbitAutoApprovalMultiBenefitDataStatus
    } = nextProps

    if (sumbitAutoApprovalMultiBenefitDataStatus === false) {
      notification[sumbitAutoApprovalMultiBenefitDataStatus.toLowerCase()]({
        message: sumbitAutoApprovalMultiBenefitDataMessage
      })
      if (sumbitAutoApprovalMultiBenefitDataStatus === 'success') {
        this.props.form.resetFields()
        this.props.onClosePopupForm()
        this.props.resetLoadingRedux(['SUBMIT_EVENTS_CLAIM', 'SUBMIT_AUTO_APPROVAL_MULTIPLE_BENEFIT_DATA'])
        this.props.resetErrorRedux(['SUBMIT_EVENTS_CLAIM', 'SUBMIT_AUTO_APPROVAL_MULTIPLE_BENEFIT_DATA'])
      }
    }

    if (getSubmitEventLoading === false) {
      notification[getSubmitEventError ? 'error' : 'success']({ message: getStatusSubmitEvent })
      if (getSubmitEventError === false) {
        this.props.form.resetFields()
        this.resetState()
        this.props.onClosePopupForm()
        this.setState({ submitEventLoader: false, getStatusSubmitEvent: getStatusSubmitEvent, openCommentBox: false })
      }
      this.props.resetLoadingRedux(['SUBMIT_EVENTS_CLAIM'])
      this.props.resetErrorRedux(['SUBMIT_EVENTS_CLAIM'])
    }

    if (getSubmitSalvageEventLoading === false) {
      notification[getSubmitSalvageEventError ? 'error' : 'success']({ message: getStatusSubmitEvent })
      if (getSubmitSalvageEventError === false) {
        this.props.form.resetFields()
        this.resetState()
        this.props.onClosePopupForm()
        this.setState({ submitEventLoader: false, getStatusSubmitEvent: getStatusSubmitEvent, openCommentBox: false })
      }
      this.props.resetLoadingRedux(['SUBMIT_EVENTS_SALVAGE'])
      this.props.resetErrorRedux(['SUBMIT_EVENTS_SALVAGE'])
    }
  }

  resetState = () => {
    this.props.resetReduxStateClaim()
  }

  async validateForm() {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    const { openCommentBox, userSelectedDate, selectedComment } = this.state
    const { form, mainEvent, detailData, claimId, slab } = this.props

    e.preventDefault()

    form.setFieldsValue({
      date: userSelectedDate
    })

    this.resetState()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    this.setState({ submitEventLoader: true })
    let payload = form.getFieldsValue()

    let startingDateTime; let startingTime; let dateTimeFlag = true
    const { form_data: formData } = mainEvent

    formData && formData.forEach((data) => {
      const { type, starting_date: startingDateOption, starting_time: startingTimeOption } = data
      if (type === 'datetime') {
        startingDateTime = moment(startingDateOption).utc()
      }
      if (type === 'time') {
        startingTime = moment(startingTimeOption).utc()
      }
    })

    if (startingDateTime && startingTime) {
      const { date, time } = payload
      const userTimeZone = this.state.userSelectedTimezone || this.props.dataProfile.user_timezone

      const selectedDateInDashedFormat = moment(date).format('YYYY-MM-DD')
      const selectedTimeInDashedFormat = moment(time).format('HH:mm:ss')

      const selectedDateTimeLocalFormat = momentTimezone.tz(`${selectedDateInDashedFormat} ${selectedTimeInDashedFormat}`, userTimeZone)

      const selectedDateTimeUTCFormat = moment.utc(selectedDateTimeLocalFormat)

      const difference = selectedDateTimeUTCFormat.diff(startingDateTime)

      if (difference <= 0) {
        notification.error({
          message: `time should be greater than ${momentTimezone(startingDateTime).tz(userTimeZone).format('YYYY-MM-DD HH:mm:ss')}`
        })
        this.setState({ submitEventLoader: false })
        dateTimeFlag = false
      }

      if (selectedDateTimeUTCFormat.diff(moment()) > 0) {
        notification.error({
          message: `time should be lesser than ${momentTimezone(moment()).tz(userTimeZone).format('YYYY-MM-DD HH:mm:ss')}`
        })
        this.setState({ submitEventLoader: false })
        dateTimeFlag = false
      }

      if (dateTimeFlag) {
        payload.date = selectedDateTimeUTCFormat.format('YYYY-MM-DD')
        payload.time = selectedDateTimeUTCFormat.format('HH:mm:ss')
      }
    }

    if (dateTimeFlag) {
      if (slab === null) {
        notification.error({message: `You dont have permission to disburse claim.`})
        this.setState({submitEventLoader: false})
      } else if (parseInt(slab.min_amount) > parseInt(payload.amount)) {
        notification.error({message: `You dont have permission to disburse amount lower than ${slab.min_amount}`})
        this.setState({submitEventLoader: false})
      } else if (parseInt(payload.amount) > parseInt(slab.max_amount)) {
        notification.error({message: `You dont have permission to disburse amount greater than ${slab.max_amount}`})
        this.setState({submitEventLoader: false})
      } else {
        const isNotProductionEnv = process.env.REACT_APP_ENV !== 'production'

        if (openCommentBox && selectedComment && isNotProductionEnv) {
          const comments = document.getElementById('commentBox').value
          if (comments !== '') {
            payload.remarks = comments
            payload.fraud_flag = selectedComment
          } else {
            message.error('comments are required')
            this.setState({ submitEventLoader: false })
            return
          }
        } else if (openCommentBox) {
          const comments = document.getElementById('commentBox').value
          if (comments !== '') { payload.remarks = comments } else {
            message.error('comments are required')
            this.setState({ submitEventLoader: false })
            return
          }
        } else if ('tx_id' in payload) {
          payload.remarks = payload.tx_id
        }

        if (mainEvent?.is_salvage) {
          const data = {
            salvage_slug: mainEvent.salvage_slug,
            salvage_status: mainEvent.salvage_status,
            event_code: mainEvent.code,
            id: claimId,
            data: {
              name: 'remarks',
              remarks: payload.remarks
            }
          }
          this.props.submitEventSalvage(data)
        } else {
          payload = {
            ...payload,
            // images: (
            //   uploadImageUrl.length > 0
            //     ? uploadImageUrl[0]
            //     : null)
          }
          if (Object.prototype.hasOwnProperty.call(mainEvent, 'form_name') && mainEvent.form_name !== undefined) {
            this.props.submitEvent({
              id: claimId,
              event_code: mainEvent.code,
              status: detailData.status.status_code,
              data: {
                ...payload,
                name: mainEvent.name,
                form_name: mainEvent.form_name
              }
            })
          } else {
            this.props.submitEvent({ id: claimId, event_code: mainEvent.code, status: detailData.status.status_code, data: payload })
          }
          this.setState({ submitEventLoader: false })
          this.setState({ uploadedUrl: [] })
        }
      }
    }
  }
  
  handleCancel = () => {
    this.props.form.resetFields()
    this.props.onClosePopupForm()
    this.setState({ uploadedUrl: [] })
    this.resetState()
  }

  renderImage = value => {
    if (value.length > 0) {
      if (Array.isArray(value)) {
        return value.map((val, index) => {
          if (val.search('.pdf') > -1) {
            return (
              <div
                key={index}
                className='display-image'
              >
                <a
                  href={val}
                  target='_blank'
                  rel='noopener noreferrer'
                  className='file-link'
                >
                  View File
                </a>
              </div>
            )
          }
          return (
            <div
              key={index}
              className='image-container'
            >
              <img
                className='single-image'
                src={val}
                alt='document'
              />
            </div>
          )
        })
      } else {
        return (
          <img
            className='image'
            src={value}
            alt='document'
          />
        )
      }
    }
    return ''
  }

  handleChange = (value) => {
    this.setState({
      userSelectedTimezone: value
    })
  };

  renderTimezoneSelect = () => {
    return (
      <Select
        placeholder='Select a timezone'
        defaultValue='GMT+7:00'
        onChange={this.handleChange}
        className='select'
      >
        {timezoneOptions.map(({ value, label }) => {
          return (
            <Option value={value} key={value}>
              {label}
            </Option>
          )
        })}
      </Select>
    )
  }

  handleDatePickerChange = (value) => {
    this.setState({
      userSelectedDate: value
    })
  }

  handleChangeSelect = (value) => {
    const isNotProductionEnv = process.env.REACT_APP_ENV !== 'production'
    this.setState({ selectedRemarks: value });
    if (value === 'other') {
      this.setState({ openCommentBox: true })
    } else if (value === 'FRAUD_CONFIRM' && isNotProductionEnv) {
      this.setState({ openCommentBox: true, selectedComment: value })
    } else {
      const { openCommentBox } = this.state
      if (openCommentBox) {
        this.setState({ openCommentBox: false })
      }
    }
  }

  handleDefaultValue = (code) => {
    switch (code) {
      case "document_approved_by_pp":
      case "document_verified":
        return "diverifikasi"
      default: return ''
    }
  }

  renderInputType = (attribute = {}) => {
    const {
      type,
      options,
      name,
      starting_date: startingDate
    } = attribute

    const { userSelectedTimezone } = this.state

    const userTimeZone = userSelectedTimezone || this.props.dataProfile.user_timezone
    const date = startingDate ? momentTimezone(startingDate).tz(userTimeZone).format('YYYY-MM-DD') : false
    switch (type) {
      case 'choices':
        return (
          <Select
            // disabled={options?.length === 1} 
            className='remarks-select'
            onSelect={this.handleChangeSelect}
          >
            {
              options.map((val, index) => (
                <Option
                  key={index}
                  value={val[0]}
                  className='select-option'
                >
                  <Tooltip placement='top' title={val[1]}>
                    <div>{val[1]}</div>
                  </Tooltip>
                </Option>
              ))
            }
          </Select>
        )
      case 'image':
        return (
          <UploadImg
            attribute={attribute}
            state={this.state}
            setState={this.setState}
            form={this.props.form}
          />
        )
      case 'text':
        if (name === 'amount') {
          return (
            <InputNumber
              formatter={value => `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
              parser={value => value.replace(/\$\s?|(,*)/g, '')}
              className='input-number'
            />
          )
        } else {
          return <Input />
        }
      case 'time':
        return (
          <TimePicker
            defaultOpenValue={moment('00:00:00', 'HH:mm:ss')}
            format='HH:mm:ss'
          />
        )
      case 'date':
        return (
          <DatePicker
            disabledDate={disableDateRanges({ endDate: true, startDate: date })}
          />

        )
      case 'datetime':
        return (
          <div className='flex'>
            <DatePicker
              onChange={this.handleDatePickerChange}
              disabledDate={disableDateRanges({ endDate: true, startDate: date })}
            />
            {this.renderTimezoneSelect()}
          </div>

        )
      case 'date-timezone':
        return (
          <div className='flex'>
            <DatePicker
              onChange={this.handleDatePickerChange}
              disabledDate={disableDateRanges({ endDate: true, startDate: date })}
            />
            {this.renderTimezoneSelect()}
          </div>

        )
      
        case 'int': 
        return (
          <InputNumber
            formatter={value => `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
            parser={value => value.replace(/\$\s?|(,*)/g, '')}
            className='input-number'
          />
        )

        case 'csv' : 
          return <UploadFile 
                attribute={attribute}
                state={this.state}
                setState={this.setState}
                form={this.props.form}
          />
        
      default:
        return <TextArea />
    }
  }

  changeBenefitSelected = (benefit) => {
    const { selectedBenefit } = this.state
    let newSelectedBenefit = []
    if (selectedBenefit.includes(benefit)) {
      newSelectedBenefit = [...selectedBenefit].filter((id) => id !== benefit)
    } else {
      newSelectedBenefit = [...selectedBenefit, benefit]
    }
    this.setState({
      selectedBenefit: newSelectedBenefit
    })
  }

  updateMultiBenefitAutoApproval = (benefit, payload) => {
    let newmultiBenefitAutoApprovalData = {
      ...this.state.multiBenefitAutoApprovalPayload,
      [benefit]: {
        ...payload
      }
    }
    this.setState({
      multiBenefitAutoApprovalPayload: newmultiBenefitAutoApprovalData
    })
  }

  sumbitAutoApprovalMultiBenefitData = () => {
    const { mainEvent = {}, detailData, claimId } = this.props
    const {
      form_data: formData,
    } = mainEvent
    const { multi_benefit_form_data: multiBenefitFormData } = formData

    const { multiBenefitAutoApprovalPayload = {} } = this.state
    let count = 0

    for (const key in multiBenefitFormData) {
      if (!multiBenefitFormData[key].is_auto_approved) {
        count++
      }
    }

    if ((multiBenefitAutoApprovalPayload && Object.keys(multiBenefitAutoApprovalPayload).length) === count) {
      const payload = {
        multi_benefit_amount_details: multiBenefitAutoApprovalPayload
      }
      this.props.submitEvent({
        id: claimId,
        event_code: mainEvent.code,
        status: detailData.status.status_code,
        data: {
          ...payload,
          name: mainEvent.name,
          form_name: mainEvent.form_name
        }
      })
    } else {
      notification.error({ message: 'Form is not fully filled' })
    }
  }

  render() {
    const { mainEvent = {}, form, getSubmitEventLoading, getSubmitSalvageEventLoading, isOpen } = this.props
    const { getFieldDecorator } = form
    const {
      display_name: displayName,
      form_data: formData,
    } = mainEvent
    const { openCommentBox, submitEventLoader, selectedBenefit, multiBenefitAutoApprovalPayload, selectedRemarks } = this.state
    const { multi_benefit_form_data: multiBenefitFormData } = formData
    return (
      <Modal
        visible={isOpen}
        onCancel={this.handleCancel}
        footer={null}
        closable='closable'
        title={`${displayName} Claim`}
        maskClosable={false}
      >
        <PopupStyleWrapper>
          <Spin spinning={!!getSubmitEventLoading || !!getSubmitSalvageEventLoading}>
            {
              formData && Array.isArray(formData) && formData.length && formData.map((attribute, index) => {
                const { name, required, regex, value, type, label, options } = attribute
                return (
                  <Form id='event-form' key={index} onSubmit={(e) => this.onSubmit(e)}>
                    <FormItem label={label}>
                      {
                        getFieldDecorator(name, {
                          rules: [
                            {
                              required: required,
                              message: required
                                ? `${name.replace(/'_'/g, ' ')} can not be empty`
                                : ''
                            }, {
                              validator: validator.checkValidator !== undefined && validator.checkValidator,
                              regex: regex
                            }
                          ],
                          initialValue: name === 'remarks' && selectedRemarks !== '' 
                          ? selectedRemarks 
                          : type === 'choices' && options?.length === 1 
                            ? options[0][0] 
                            : value
                        })(this.renderInputType(attribute, this.state, this.setState))
                      }
                      {openCommentBox && type === 'choices' && (<TextArea id='commentBox' />)}
                    </FormItem>
                  </Form>
                )
              })
            }
            {
              formData && Array.isArray(formData) && formData.length
                ?
                  <Row type='flex' justify='end'>
                    <FormItem>
                      <Button
                        form='event-form'
                        key='submit'
                        type='primary'
                        htmlType='submit'
                        loading={submitEventLoader}
                      >
                        Save
                      </Button>
                    </FormItem>
                  </Row>
                : null
            }

            {multiBenefitFormData && Object.keys(multiBenefitFormData).map((benefitKey) => {
              return (
                <MultiBenefitAutoApprovalEvent
                  key={benefitKey}
                  benefit={benefitKey}
                  selectedBenefit={selectedBenefit}
                  formData={multiBenefitFormData[benefitKey].form_data}
                  data={multiBenefitFormData[benefitKey]}
                  multiBenefitAutoApprovalPayload={multiBenefitAutoApprovalPayload}
                  changeBenefitSelected={this.changeBenefitSelected}
                  updateMultiBenefitAutoApproval={this.updateMultiBenefitAutoApproval}
                />
              )
            })}

            {multiBenefitFormData && Object.keys(multiBenefitFormData).length
              ? (
                <Button
                  onClick={this.sumbitAutoApprovalMultiBenefitData}
                >
                  Save
                </Button>
              )
              : null}

          </Spin>
        </PopupStyleWrapper>
      </Modal>
    )
  }
}

const WrappedPopupForm = Form.create()(PopupForm)

export default connect(state => ({
  getSubmitEventLoading: state.Loading.SUBMIT_EVENTS_CLAIM,
  getSubmitEventError: state.Error.SUBMIT_EVENTS_CLAIM,
  getStatusSubmitEvent: state.Claims.getStatusSubmitEvent,

  getSubmitSalvageEventLoading: state.Loading.SUBMIT_EVENTS_SALVAGE,
  getSubmitSalvageEventError: state.Error.SUBMIT_EVENTS_SALVAGE,

  slab: state.Auth.slab,
  saveUploadGenericFileStatus: state.Claims.saveUploadGenericFileStatus,
  dataProfile: state.Auth.profile,
  url: state.Claims.url,
  sumbitAutoApprovalMultiBenefitDataStatus: state.Claims.sumbitAutoApprovalMultiBenefitDataStatus,
  sumbitAutoApprovalMultiBenefitDataMessage: state.Claims.sumbitAutoApprovalMultiBenefitDataMessage,
}), {
  resetReduxStateClaim,
  submitEvent,
  uploadImage,
  submitEventSalvage,
  resetErrorRedux,
  resetLoadingRedux,
  sumbitAutoApprovalMultiBenefitData
})(WrappedPopupForm)
