import React, { useRef } from 'react'
import { Modal, Button, Icon } from 'antd'
import { Document, Page } from 'react-pdf/dist/esm/entry.webpack'

const PDFModal = ({
  visible,
  pdfFile,
  numPages,
  pdfRotation,
  onCancel,
  onDocumentLoadSuccess,
  onRotateLeft,
  onRotateRight
}) => {
  const downloadRef = useRef(null)

  const getCurrentPageOrientation = () => {
    return pdfRotation === 90 || pdfRotation === 270 || pdfRotation === -90 || pdfRotation === -270 ? 'landscape' : 'portrait'
  }

  const handleDownload = async () => {
    try {
      const response = await fetch(pdfFile, {
        method: 'GET'
      })

      if (!response.ok) {
        throw new Error('Failed to fetch file.')
      }

      const blob = await response.blob()
      const url = URL.createObjectURL(blob)

      if (downloadRef.current) {
        downloadRef.current.href = url
        downloadRef.current.download = pdfFile.split('/').pop()
        downloadRef.current.click()

        URL.revokeObjectURL(url)
      }
    } catch (error) {
      console.error('Error downloading file:', error)
      alert('Unable to download the file. Please try again.')
    }
  }

  return (
    <Modal
      visible={visible}
      title='PDF Preview'
      onCancel={onCancel}
      footer={null}
      width={getCurrentPageOrientation() === 'landscape' ? '90%' : '60%'}
      bodyStyle={{
        overflow: 'auto',
        display: 'flex',
        justifyContent: 'center',
        paddingBottom: '60px'
      }}
    >
      {pdfFile && (
        <Document
          file={pdfFile}
          onLoadSuccess={onDocumentLoadSuccess}
          onLoadError={(error) => console.error('Error while loading document:', error)}
        >
          <Page pageNumber={1} rotate={pdfRotation} />
          {numPages > 1 &&
            Array.from({ length: numPages - 1 }, (_, index) => (
              <Page key={index + 2} pageNumber={index + 2} />
            ))}
        </Document>
      )}
      <div
        style={{
          position: 'fixed',
          bottom: 0,
          width: getCurrentPageOrientation() === 'landscape' ? '90%' : '60%',
          backgroundColor: '#fff',
          padding: '10px 20px',
          borderTop: '1px solid #ddd',
          textAlign: 'right',
          zIndex: 1000,
          display: 'flex',
          gap: '16px',
          alignItems: 'center',
          justifyContent: 'flex-end'
        }}
      >
        <Button type='default' onClick={onRotateLeft}>
          <Icon type='rollback' style={{ fontSize: 20 }} />
        </Button>
        <Button type='default' onClick={onRotateRight}>
          <Icon type='rollback' style={{ fontSize: 20, transform: 'scaleX(-1)' }} />
        </Button>
        <Button key='download' type='primary' onClick={handleDownload}>
          Download
        </Button>
        {/* eslint-disable-next-line */}
        <a ref={downloadRef} style={{ display: 'none' }} rel='noopener noreferrer' />
      </div>
    </Modal>
  )
}

export default PDFModal
