const uploadedImage = (form, payload = {}) => {
  form.attributes.forEach(val => {
    for (let key in payload.payload) {
      if (val.name === key && val.type === 'image') {
        let imageValue
        if(Array.isArray(val.value)) {
          imageValue = val.value.map(value => value.split('?')[0])
        } else {
          imageValue = val.value && val.value.split('?')[0]
        }
        payload.payload[val.name] = imageValue
      }
    }
  })
  return payload
}

export default uploadedImage
