import { useErrorContextValue, useLoaderContextValue, usePost } from '@pasarpolis/common-react-hooks'
import { Button, Icon, message, notification, Spin, Upload } from 'antd'
import { useEffect, useState } from 'react'
import { uploadImgApiConfig } from '../../UploadImg/apiConfig'
import { UploadImgStyleWrapper } from '../../UploadImg/container/index.style'

const dummyRequest = ({ file, onSuccess }) => {
  setTimeout(() => {
    onSuccess('ok')
  }, 0)
}

const getLoaderKey = (name) => {
  return String(name).split(' ').join('_').toUpperCase() + '_LOADER'
}

const getErrorKey = (name) => {
  return String(name).split(' ').join('_').toUpperCase() + '_ERROR'
}

const getDataKey = (name) => {
  return String(name).split(' ').join('_').toUpperCase()
}

const UploadImgContainer = ({ attribute, form }) => {
  const { getFieldDecorator, setFieldsValue } = form
  const errorKey = getErrorKey(attribute.name)
  const loaderKey = getLoaderKey(attribute.name)
  const [response, uploadRequest] = usePost(uploadImgApiConfig(getDataKey(attribute.name)))
  const [uploadedUrl, setUploadedUrl] = useState('')
  const [{ [errorKey]: ERROR_KEY }] = useErrorContextValue()
  const [{ [loaderKey]: LOADER_KEY }] = useLoaderContextValue()

  const onHandleFileUpload = (file) => {
    const allowedMimeTypes = [
      'application/vnd.ms-excel',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'text/csv'
    ]
    const isLt2M = file.size / 1024 / 1024 < 2 // 2MB limit

    if (!allowedMimeTypes.includes(file.type)) {
      message.error('Only XLSX, XLS, and CSV files are allowed')
      return Upload.LIST_IGNORE
    }
    if (!isLt2M) {
      message.error('File must be smaller than 2MB!')
      return Upload.LIST_IGNORE
    }

    return true
  }

  const handleChange = (info) => {
    const allowedMimeTypes = [
      'application/vnd.ms-excel',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'text/csv'
    ]
    const isGt20000KB = info.file.size / 1024 / 1024 > 20

    if (info.file.status === 'removed') {
      setUploadedUrl('') // Reset uploadedUrl when the file is removed
      setFieldsValue({ [attribute.name]: '' })
      return
    }

    if (isGt20000KB) {
      message.error('File terlalu besar, max 20mb')
      return
    }

    if (allowedMimeTypes.includes(info.file.type) && !isGt20000KB) {
      if (info.file.status === 'done') {
        const file = info.file.originFileObj
        try {
          const formData = new FormData()
          formData.append('file', file)
          uploadRequest(formData)
        } catch (error) {
          message.error('Ada yang bermasalah, reload dan ulangi kembali')
        }
      } else if (info.file.status === 'error') {
        notification.error({ message: 'Upload failed. Please check your file type and size.' })
      }
    } else {
      notification.error({ message: 'Check your file type' })
    }
  }

  const renderUpload = value => {
    const disableButton = !!uploadedUrl?.length
    return (
      <Upload
        name='file'
        accept='.csv,.xls,.xlsx'
        showUploadList
        multiple={false}
        customRequest={dummyRequest}
        onChange={handleChange}
        beforeUpload={onHandleFileUpload}
      >
        <Button
          className='upload-btn'
          disabled={disableButton}
        >
          <Icon type='upload' />Upload
        </Button>
      </Upload>
    )
  }

  useEffect(() => {
    if (ERROR_KEY) {
      message.error('File failed to upload. Please try again')
    }
  }, [ERROR_KEY])

  useEffect(() => {
    if (response?.url) {
      setFieldsValue({ [attribute.name]: response.url })
      setUploadedUrl(response.url)
    }
  }, [response, setFieldsValue, attribute])

  return (
    <UploadImgStyleWrapper>
      {getFieldDecorator(attribute.name)}
      <Spin
        spinning={!!LOADER_KEY}
        tip='Uploading ...'
      >
        {renderUpload(attribute)}
      </Spin>
    </UploadImgStyleWrapper>
  )
}
export default UploadImgContainer
