import React, { PureComponent } from 'react'
import PropTypes from 'prop-types'
import ImageComponentWrapper from './imageComponent.style'
import { Document, Page } from 'react-pdf/dist/esm/entry.webpack'
import { Modal, Button, Icon } from 'antd'

export default class ImageComponent extends PureComponent {
  state = {
    viewImageButton: false,
    showPDFModal: false,
    pdfFile: null,
    numPages: null,
    pdfRotation: 0
  }

  downloadRef = React.createRef();

  renderTableRow = (label, extractedValue, key) => {
    return (
      <tr key={key}>
        <td className='table-cell'>
          {label}
        </td>
        <td className='table-cell'>
          {
            (extractedValue && typeof extractedValue === 'object')
              ? extractedValue.join(', ')
              : extractedValue
          }
        </td>
      </tr>
    )
  }

  handleImageError = () => {
    this.setState({ viewImageButton: true })
  }

  handleOpenPDFModal = (fileUrl) => {
    this.setState({
      showPDFModal: true,
      pdfFile: fileUrl
    })
  };

  handleClosePDFModal = () => {
    this.setState({
      showPDFModal: false,
      pdfFile: null,
      numPages: null
    })
  };

  handleOnDocumentLoadSuccess = ({ numPages }) => {
    this.setState({ numPages })
  };

  handleDownload = async () => {
    const { pdfFile } = this.state

    try {
      const response = await fetch(pdfFile, {
        method: 'GET'
      })

      if (!response.ok) {
        throw new Error('Failed to fetch file.')
      }

      const blob = await response.blob()
      const url = URL.createObjectURL(blob)

      if (this.downloadRef.current) {
        this.downloadRef.current.href = url
        this.downloadRef.current.download = pdfFile.split('/').pop()
        this.downloadRef.current.click()

        URL.revokeObjectURL(url)
      }
    } catch (error) {
      console.error('Error downloading file:', error)
      alert('Unable to download the file. Please try again.')
    }
  };

  handleRotateRightPDF = () => {
    this.setState((prevState) => ({
      pdfRotation: (prevState.pdfRotation + 90) % 360
    }))
  };

  handleRotateLeftPDF = () => {
    this.setState((prevState) => ({
      pdfRotation: (prevState.pdfRotation - 90) % 360
    }))
  }

  getCurrentPageOrientation = () => {
    const { pdfRotation } = this.state
    return pdfRotation === 90 || pdfRotation === 270 || pdfRotation === -90 || pdfRotation === -270 ? 'landscape' : 'portrait'
  };

  render () {
    const {
      value,
      index,
      divStyle,
      imgStyle,
      additionalInfo,
      onClick,
      isPDF
    } = this.props
    const { viewImageButton, showPDFModal, numPages, pdfFile } = this.state
    const additionalInfoKeys = Object.keys(additionalInfo)

    return (
      <ImageComponentWrapper>
        <Modal
          title='PDF Viewer'
          onCancel={this.handleClosePDFModal}
          visible={showPDFModal}
          footer={null}
          width={this.getCurrentPageOrientation() === 'landscape' ? '90%' : '60%'}
          bodyStyle={{
            overflow: 'auto',
            display: 'flex',
            justifyContent: 'center',
            paddingBottom: '60px'
          }}
        >
          {pdfFile && (
            <Document
              file={pdfFile}
              onLoadSuccess={this.handleOnDocumentLoadSuccess}
              onLoadError={(error) =>
                console.error('Error while loading document:', error)}
            >
              <Page pageNumber={1} rotate={this.state.pdfRotation} />
              {numPages > 1 &&
                Array.from({ length: numPages - 1 }, (_, index) => (
                  <Page key={index + 2} pageNumber={index + 2} />
                ))}
            </Document>
          )}
          <div
            style={{
              position: 'fixed',
              bottom: 0,
              width: this.getCurrentPageOrientation() === 'landscape' ? '90%' : '60%',
              backgroundColor: '#fff',
              padding: '10px 20px',
              borderTop: '1px solid #ddd',
              textAlign: 'right',
              zIndex: 1000,
              display: 'flex',
              gap: '16px',
              alignItems: 'center',
              justifyContent: 'flex-end'
            }}
          >
            <Button type='default' onClick={this.handleRotateLeftPDF}>
              <Icon type='rollback' style={{ fontSize: 20 }} />
            </Button>
            <Button type='default' onClick={this.handleRotateRightPDF}>
              <Icon type='rollback' style={{ fontSize: 20, transform: 'scaleX(-1)' }} />
            </Button>
            <Button key='download' type='primary' onClick={this.handleDownload}>
              Download
            </Button>
            <a ref={this.downloadRef} style={{ display: 'none' }} rel='noopener noreferrer' />
          </div>
        </Modal>
        <div key={index} style={divStyle}>
          <div>
            {
              isPDF
                ? (
                  <div style={divStyle} className='pdf-view-file' key={index}>
                    <a target='_blank' rel='noopener noreferrer' onClick={() => this.handleOpenPDFModal(value)}>
                      View File
                    </a>
                  </div>
                  )
                : viewImageButton
                  ? (
                    <a
                      target='_blank'
                      href={value}
                      rel='noopener noreferrer'
                      className='view-file-button'
                      type='primary'
                    >
                      View File
                    </a>
                    )
                  : <img
                      style={imgStyle}
                      src={value}
                      onClick={() => onClick()}
                      alt='View File'
                      onError={this.handleImageError}
                    />
            }
          </div>
          <div>
            <table>
              {additionalInfoKeys?.length > 0 && (
                <>
                  {this.renderTableRow('Attribute', 'Scanned Values', 'header-row')}
                  {additionalInfoKeys?.map((val, index) => {
                    const infoObj = additionalInfo[val]
                    const { label, extracted_value: extractedValue } = infoObj
                    return this.renderTableRow(label, extractedValue, index)
                  })}
                </>
              )}
            </table>
          </div>
        </div>
      </ImageComponentWrapper>
    )
  }
}

ImageComponent.propTypes = {
  value: PropTypes.string.isRequired,
  index: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
  divStyle: PropTypes.object,
  imgStyle: PropTypes.object,
  additionalInfo: PropTypes.object,
  onClick: PropTypes.func
}

ImageComponent.defaultProps = {
  value: '',
  index: 0,
  divStyle: {},
  imgStyle: {},
  additionalInfo: {},
  onClick: () => console.log('hey')
}
