import { Collapse, Tag } from 'antd'
import {
  Container,
  Header,
  HeaderContent,
  HeaderTitle,
  InfoGrid,
  InfoCard,
  InfoCardLabel,
  InfoCardValue,
  DamagesSection,
  DamagesHeader,
  DamageDescription,
  DamageImageWrapper,
  DamageContent,
  DamagePart,
  DamageCard,
  DamageCardTitle,
  DamageDivider,
  SectionLabel,
  TemperedReasonText
} from './styles'
import Viewer from 'react-viewer'
import 'react-viewer/dist/index.css'
import { useState, Fragment } from 'react'
import ImageComponent from '../../../imageComponent'

const statusTags = [
  {
    key: 'plate',
    show: (d) => Boolean(d.plate),
    value: (d) => d.plate ?? 'N/A',
    color: (d) => d.isPlateMatch ? 'green' : 'red'
  },
  {
    key: 'damage',
    show: (d) => d.isDamaged,
    value: () => 'Damaged',
    color: () => 'red'
  },
  {
    key: 'temper',
    show: (d) => d.isTempered,
    value: () => 'Tempered',
    color: () => 'red'
  },
  {
    key: 'timestamp',
    show: (d) => d.hasTimestamp !== undefined,
    value: (d) => d.hasTimestamp && d.timestampValue
      ? `${d.timestampValue.date} ${d.timestampValue.time}`
      : 'No Timestamp',
    color: (d) => d.hasTimestamp ? 'green' : 'red'
  }
]

const CarIncidentDescription = ({ plateNumber, damages = [], color, brand }) => {
  const [previewVisible, setPreviewVisible] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)
  const handlePreview = (imageUrl, index) => {
    setActiveIndex(index)
    setPreviewVisible(true)
  }

  const handleClose = () => {
    setPreviewVisible(false)
  }

  return (
    <Collapse defaultActiveKey={['1']}>
      <Collapse.Panel key='1' header='Incident Information'>
        <Container>
          <Header>
            <HeaderContent>
              <HeaderTitle>Recap incident by AI.</HeaderTitle>
            </HeaderContent>
          </Header>

          <InfoGrid>
            <InfoCard>
              <InfoCardLabel>Plate Number By Policy</InfoCardLabel>
              <InfoCardValue variant='plate'>{plateNumber}</InfoCardValue>
            </InfoCard>
            <InfoCard>
              <InfoCardLabel>Brand By Policy</InfoCardLabel>
              <InfoCardValue variant='brand'>{brand}</InfoCardValue>
            </InfoCard>
            <InfoCard>
              <InfoCardLabel>Color By Policy</InfoCardLabel>
              <InfoCardValue variant='Color'>{color}</InfoCardValue>
            </InfoCard>
          </InfoGrid>

          <DamagesSection>
            <DamagesHeader>Description</DamagesHeader>
            {damages.map((damage, index) => (
              <DamageCard key={`${damage.panel}-${damage.description}`} hasAlert={damage.isDamaged || damage.isTempered}>
                <DamageCardTitle>
                  <DamagePart>
                    {damage.panel}
                    {statusTags.map(s => {
                      if (!s.show(damage)) return null
                      return <Fragment key={s.key}> | <Tag color={s.color(damage)}>{s.value(damage)}</Tag></Fragment>
                    })}
                  </DamagePart>
                </DamageCardTitle>
                <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-start' }}>
                  <DamageImageWrapper>
                    <ImageComponent
                      value={damage.image}
                      index={index}
                      divStyle={{ display: 'flex', alignItems: 'center' }}
                      imgStyle={{
                        width: '120px',
                        height: '80px',
                        objectFit: 'cover',
                        borderRadius: '4px',
                        cursor: 'pointer'
                      }}
                      onClick={() => handlePreview(damage.image, index)}
                    />
                  </DamageImageWrapper>
                  <DamageContent>
                    <SectionLabel>Damaged</SectionLabel>
                    <DamageDescription>{damage.description}</DamageDescription>
                    {damage.isTempered && damage.temperedReason?.length > 0 && (
                      <>
                        <DamageDivider />
                        <SectionLabel>Tempered</SectionLabel>
                        {damage.temperedReason.map((reason, idx) => (
                          <TemperedReasonText key={idx}>{reason}</TemperedReasonText>
                        ))}
                      </>
                    )}
                  </DamageContent>
                </div>
              </DamageCard>
            ))}
          </DamagesSection>

          <Viewer
            visible={previewVisible}
            onClose={handleClose}
            activeIndex={activeIndex}
            images={damages.map((damage) => ({ src: damage.image, alt: damage.panel }))}
            drag={false}
            zoom
            rotatable
            scalable
            inline={false}
          />
        </Container>
      </Collapse.Panel>
    </Collapse>
  )
}

export default CarIncidentDescription
