import React from 'react'
import { connect } from 'react-redux'
import {
  Select
} from 'antd'
import PropTypes from 'prop-types'
import AssignOwnerDropdownWrapper from './assignOwnerDropdown.style'
import ClaimActions from '../../redux/claims/actions'

const Option = Select.Option

const { assignOwner, getClaimUsers } = ClaimActions

class AssignOwnerDropdown extends React.Component {
    state = {
      isFocus: false
    }
    componentDidMount () {
      this.props.getClaimUsers()
    }
    focus = () => {
      this.setState({
        isFocus: true
      })
    }
    blur = () => {
      this.setState({
        isFocus: false
      })
    }
    onSelect = value => {
      const {
        currentOwnerId,
        claimId
      } = this.props
      this.props.assignOwner({
        body: {
          current_owner: currentOwnerId,
          new_owner: value,
          claim_id: claimId
        }
      })
    }
    render () {
      const {
        currentOwnerId,
        claimUsers,
        claimsUsersLoading,
        assignOwnerLoading
      } = this.props
      return (
        <AssignOwnerDropdownWrapper>
          <strong>Owner</strong>:&nbsp;
          <Select
            className='owner-select'
            showSearch
            showArrow={false}
            defaultValue={currentOwnerId ? Number(currentOwnerId) : undefined}
            placeholder='Unassigned'
            size={'small'}
            optionFilterProp='children'
            onBlur={this.blur}
            onSelect={this.onSelect}
            filterOption={(input, option) =>
              option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
            }
            style={{ width: '200px' }}
            disabled={!!claimsUsersLoading}
            loading={!!claimsUsersLoading || !!assignOwnerLoading}
          >
            {claimUsers.map(({ id, name }) => (
              <Option key={id} value={id}>{name}</Option>
            ))}
          </Select>
        </AssignOwnerDropdownWrapper>
      )
    }
}

AssignOwnerDropdown.propTypes = {
  claimUsers: PropTypes.array.isRequired
}

AssignOwnerDropdown.defaultProps = {
  claimUsers: []
}

export default connect(
  state => ({
    claimUsers: state.Claims.claimUsers,
    claimUsersStatus: state.Claims.claimUsersStatus,
    claimsUsersLoading: state.Loading.CLAIM_USERS,
    claimsUsersError: state.Error.CLAIM_USERS,
    assignOwnerLoading: state.Loading.ASSIGN_OWNER,
    assignOwnerError: state.Error.ASSIGN_OWNER,
    assignOwnerStatus: state.Claims.assignOwnerStatus
  }),
  {
    assignOwner,
    getClaimUsers
  }
)(AssignOwnerDropdown)
