import React from 'react'
import { connect } from 'react-redux'
import { Form, Modal, Input, Button, Alert } from 'antd'
import ClaimActions from '../../redux/claims/actions'

const { completeFollowUp, resetReduxStateClaim } = ClaimActions

const FormItem = Form.Item
const { TextArea } = Input

class CompleteFollowUp extends React.Component {
    state = {
      submitting: false,
      completeFollowUpStatus: ''
    }
    async validateForm () {
      return new Promise((resolve) => {
        this.props.form.validateFields((error, values) => {
          resolve(!error)
        })
      })
    }
    componentWillReceiveProps (nextProps) {
      const { completeFollowUpStatus } = nextProps.claim
      if (completeFollowUpStatus !== '' && completeFollowUpStatus !== 'success') {
        this.setState({
          completeFollowUpStatus: completeFollowUpStatus,
          submitting: false
        })
      }
      if (completeFollowUpStatus !== '' && completeFollowUpStatus === 'success') {
        this.props.form.resetFields()
        this.props.resetReduxStateClaim()
        this.props.isClose()
        this.setState({ submitting: false })
      }
    }
    onSubmit = async e => {
      e.preventDefault()
      this.props.resetReduxStateClaim()
      this.setState({ submitting: true })
      const valid = await this.validateForm()
      if (!valid) {
        this.setState({ submitting: false })
        return
      }
      const { form, claimId, profile } = this.props
      let data = form.getFieldsValue()

      let payload = {
        ...data,
        user_id: profile.id,
        claim_id: claimId
      }
      this.props.completeFollowUp(payload)
    }
    handleCancelCompleteFollowUp = () => {
      this.props.form.resetFields()
      this.props.isClose()
      this.props.resetReduxStateClaim()
      this.setState({ completeFollowUpStatus: '' })
    }
    onClose = () => {
      this.props.resetReduxStateClaim()
      this.setState({ completeFollowUpStatus: '' })
    }
    render () {
      const { form } = this.props
      const { getFieldDecorator } = form
      return (
        <div>
          <Modal
            title='Complete follow up'
            visible={this.props.isOpen}
            width='50%'
            closable={false}
            maskClosable={false}
            footer={null}
          >
            {
              this.state.completeFollowUpStatus !== '' && (
                <Alert
                  message={this.state.completeFollowUpStatus}
                  type='error'
                  closable
                  onClose={this.onClose}
                  style={{ marginBottom: '10px' }}
                />
              )
            }
            <Form onSubmit={this.onSubmit}>
              <label className='custom-label'>Remark</label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('remark', {
                  rules: [
                    { required: true, message: 'Remark can not be empty' }
                  ]
                })(
                  <TextArea rows={4} />
                )}
              </FormItem>
              <div style={{ textAlign: 'right' }}>
                <Button key='back' onClick={this.handleCancelCompleteFollowUp}>Cancel</Button>
                <Button
                  key='submit'
                  type='primary'
                  htmlType='submit'
                  loading={this.state.submitting}
                  style={{ marginLeft: '10px' }}
                >
                                                        Submit
                </Button>
              </div>
            </Form>
          </Modal>
        </div>
      )
    }
}

const WrappedForm = Form.create({})(CompleteFollowUp)

export default connect(
  state => ({
    profile: state.Auth.profile,
    claim: state.Claims
  }),
  { completeFollowUp, resetReduxStateClaim }
)(WrappedForm)
