  handleConfirmBlur = (form, attribute) => {
    const { getFieldsValue } = this.props.form
    const fieldsName = form.attributes.map(
      ({ name: attributeName }) => attributeName
    )
    const payload = getFieldsValue(fieldsName)
    const attributeFieldArray = get(form, ['attributes'])
    const validationObj = filter(attributeFieldArray, function (o) {
      return !_isEmpty(o.validations)
    })

    if (validationObj.length > 0) {
      const validationObjKeyFirst = Object.keys(
        validationObj[0].validations
      )[0]

      const operator = get(
        validationObj[0].validations[validationObjKeyFirst],
        ['operator']
      )

      const validationObjKeySecond = get(
        validationObj[0].validations[validationObjKeyFirst],
        ['value']
      ).slice(1)

      const validationObjKeyFirstValue = get(payload, [validationObjKeyFirst])
      const validationObjKeySecondValue = get(payload, [
        validationObjKeySecond
      ])

      const validationResult = validatorCheck(
        validationObjKeyFirstValue,
        validationObjKeySecondValue,
        operator
      )
      if (!validationResult) {
        if (payload.confirm_account_number !== payload.account_number) {
          this.props.form.setFields({
            account_number: {
              value: payload.account_number,
              errors: [
                new Error('Two account number that you enter is inconsistent!')
              ]
            }
          })
        }
      }
    }
  };

  submitForm = async (
    identifier,
    fieldsName,
    formIdentifier,
    formVal,
    paymentForm = null
  ) => {
    this.props.resetReduxStateClaim()
    this.setState({ messageSaveAttributes: '' })

    if (fieldsName.includes('cardamages_front_back')) {
      const carDamagesAttribute = formVal.attributes.find(attr => attr.name === 'cardamages_front_back')
      if (carDamagesAttribute) {
        const carDamagesValue = carDamagesAttribute.value
        let imageCount = 0

        if (Array.isArray(carDamagesValue)) {
          imageCount = carDamagesValue.length
        } else if (carDamagesValue) {
          imageCount = 1
        }

        if (imageCount < 4) {
          message.error('Car damages must have at least 4 images')
          return
        }
      }
    }

    const valid = await this.validateForm(fieldsName)
    if (!valid) {
      return
    }
    this.setState({
      loaderForm: {
        ...this.state.loaderForm,
        [formIdentifier]: true
      }
    })

    const { form, verifyBankData = {}, detailClaims } = this.props
    const { params } = this.props.match
    const { displayAccountHolderName } = this.state
    const payload = form.getFieldsValue()
    const { genericDataDocUploadFileName } = detailClaims
    const makeFileUrlPublic = []

    for (const key in payload) {
      if (payload[key] === null) {
        delete payload[key]
      } else {
        const keyName = key.split('---')[0]
        payload[keyName] = payload[key]
        delete payload[key]
      }
    }

    // check for discalimer
    formVal.attributes.forEach((att) => {
      if (att.type === 'disclaimer') {
        if (payload[att.name] === false) {
          payload[att.name] = undefined
          // eslint-disable no-useless-return
          if (att.required) return; // eslint-disable-line
        }
      }
    })

    genericDataDocUploadFileName &&
      fieldsName.forEach((fieldName) => {
        if (fieldName in genericDataDocUploadFileName) {
          if (Array.isArray(genericDataDocUploadFileName[fieldName])) {
            makeFileUrlPublic.push(...genericDataDocUploadFileName[fieldName])
          } else {
            makeFileUrlPublic.push(genericDataDocUploadFileName[fieldName])
          }
        }
      })
    this.props.resetReduxStateClaim(['genericDataDocUploadFileName'])
    if (formVal.is_salvage) {
      // submit salvage form
      const dataPayload = ImageFormSanitizer(formVal, {
        salvage_slug: formVal.salvage_slug,
        salvage_status: formVal.salvage_status,
        form: formVal.name,
        payload: payload,
        claim_id: params.id
      })
      this.props.saveAttributesSalvage({ ...dataPayload, makeFileUrlPublic })
    } else {
      if (
        formIdentifier === 'bank-details' ||
        formIdentifier === 'bank-details-gopay-wallet'
      ) {
        if (verifyBankData.account_holder_name) {
          payload.account_holder_name = verifyBankData.account_holder_name
        }
        payload.account_holder_name = this.state.accountHolderName
      }
      if (payload.bank_name !== undefined) {
        payload.bank_name = payload.bank_name.key
          ? payload.bank_name.key
          : payload.bank_name
      }
      const dataPayload = ImageFormSanitizer(formVal, {
        claim_id: params.id,
        payload,
        form: formIdentifier,
        source: 'control-panel'
      })

      for (const key in dataPayload.payload) {
        if (typeof dataPayload.payload[key] === 'string' && dataPayload.payload[key].includes('?')) {
          dataPayload.payload[key] = dataPayload.payload[key].split('?')[0]
        }
      }
      if (dataPayload.payload.date_of_accident) {
        dataPayload.payload.date_of_accident = normalizeToUtcMidnight(dataPayload.payload.date_of_accident)
      }
      if (dataPayload.payload.date_of_incident) {
        dataPayload.payload.date_of_incident = normalizeToUtcMidnight(dataPayload.payload.date_of_incident)
      }
      if (
        (formIdentifier === 'bank-details' || paymentForm) &&
        !displayAccountHolderName
      ) {
        this.props.verifyBankAccountForms({
          ...dataPayload,
          makeFileUrlPublic
        })
      } else {
        if (paymentForm) {
          this.props.savePaymentForm({
            body: {
              ...dataPayload,
              makeFileUrlPublic
            }
          })
        } else {
          this.props.saveGenericAttributes({
            ...dataPayload,
            makeFileUrlPublic
          })
        }
      }
    }
  };

