  handleMultiUpload = (info, identifier, formIdentifier) => {
    const f = info.file
    if (f.status !== 'done' && f.status !== 'error') return

    if (!this._processedUploads) this._processedUploads = new Set()
    const key = `${identifier}-${f.uid}`
    if (this._processedUploads.has(key)) return
    this._processedUploads.add(key)

    const file = f.originFileObj
    if (!file) return

    const sizeMB = file.size / 1024 / 1024
    if (sizeMB < 0.01) { message.error(`${file.name} terlalu kecil, min 10kb`); return }
    if (sizeMB > 10) { message.error(`${file.name} terlalu besar, max 10MB`); return }

    const defaultAllowed = ['image/jpeg', 'image/jpg', 'image/png', 'video/mp4', 'application/pdf']
    const cardamageAllowed = ['image/jpeg', 'image/jpg', 'image/png']
    const allowedTypes = identifier === 'cardamages_front_back' ? cardamageAllowed : defaultAllowed
    if (!allowedTypes.includes(file.type)) {
      const msg = identifier === 'cardamages_front_back'
        ? 'Only JPG or PNG files are allowed for car damages photos'
        : 'Check your file type'
      notification.error({ message: `${file.name}: ${msg}` })
      return
    }

    const existingNames = this.state.photos[identifier] || []
    if (existingNames.includes(file.name)) {
      message.error('File ini telah diunggah')
      return
    }
    if (existingNames.length > 49) {
      message.error('Tidak dapat mengunggah lebih dari 50 file')
      return
    }

    this.setState((prevState) => ({
      photos: {
        ...prevState.photos,
        [identifier]: [...(prevState.photos[identifier] || []), file.name]
      },
      loader: { ...prevState.loader, [identifier]: true },
      loadingDoc: true,
      loaderImageForm: { ...prevState.loaderImageForm, [formIdentifier]: true },
      pendingUploads: {
        ...prevState.pendingUploads,
        [identifier]: [
          ...(prevState.pendingUploads[identifier] || []),
          { file, name: file.name, uid: f.uid, preview: URL.createObjectURL(file) }
        ]
      }
    }))

    this.uploadSingleFile(file, identifier, formIdentifier, true)
  }

  uploadSingleFile = (file, identifier, formIdentifier, ismultiValue) => {
    const formData = new FormData()
    formData.append('file', file)
    formData.append('attribute', [identifier])
    this.props.generateSignedUrlAndUplaod({
      formData,
      file,
      attribute: identifier,
      form: formIdentifier,
      ismultiValue
    })
  }

  async handleChange (info, identifier, formIdentifier, ismultiValue = false) {
    if (ismultiValue) {
      this.handleMultiUpload(info, identifier, formIdentifier)
      return
    }
    if (info?.file?.status === 'done' || info?.file?.status === 'error') {
      const isLt10KB = info.file.size / 1024 / 1024 < 0.01
      const isGt10MB = info.file.size / 1024 / 1024 > 10
      if (isLt10KB) {
        message.error('Photo terlalu kecil, min 10kb')
        return
      }
      if (isGt10MB) {
        message.error('Photo terlalu besar, max 10MB')
        return
      }
      // Restrict accepted mime types. For `cardamages_front_back` only allow jpg/png images.
      const defaultAllowed = [
        'image/jpeg',
        'image/jpg',
        'image/png',
        'video/mp4',
        'application/pdf'
      ]
      const cardamageAllowed = ['image/jpeg', 'image/jpg', 'image/png']
      const allowedTypes = identifier === 'cardamages_front_back' ? cardamageAllowed : defaultAllowed

      // if file type is not allowed, show specific message for cardamages
      if (!allowedTypes.includes(info.file.type)) {
        if (identifier === 'cardamages_front_back') {
          notification.error({ message: 'Only JPG or PNG files are allowed for car damages photos' })
        } else {
          notification.error({ message: 'Check your file type' })
        }
        return
      }

      if (!isLt10KB && !isGt10MB) {
        const file = info.file.originFileObj

        const duplicateList = this.state.photos[identifier]

        if (duplicateList !== undefined) {
          if (duplicateList.length > 49) {
            message.error('Tidak dapat mengunggah lebih dari 50 file')
            return
          } else if (duplicateList.indexOf(file.name) > -1) {
            message.error('File ini telah diunggah')
            return
          }
        }

        getBase64(info.file.originFileObj, (imageUrl) =>
          this.setState((prevState) => {
            if (
              !!prevState.photos[identifier] &&
              prevState.photos[identifier].length > 0
            ) {
              // move to update from props
              return {
                photos: {
                  ...this.state.photos,
                  [identifier]: [
                    ...prevState.photos[identifier],
                    info.file.name
                  ]
                },
                loading: false
              }
            }
            return {
              photos: {
                ...this.state.photos,
                [identifier]: [info.file.name]
              },
              loading: false
            }
          })
        )
        try {
          this.setState({
            loader: {
              ...this.state.loader,
              [identifier]: true
            },
            loadingDoc: true,
            loaderImageForm: {
              ...this.state.loaderImageForm,
              [formIdentifier]: true
            },
            pendingUploads: {
              ...this.state.pendingUploads,
              [identifier]: [
                ...((this.state.pendingUploads[identifier] || [])),
                { file, name: file.name, uid: `single-${file.name}-${Date.now()}`, preview: URL.createObjectURL(file) }
              ]
            }
          })
          this.uploadSingleFile(file, identifier, formIdentifier, ismultiValue)
        } catch (error) {
          message.error('Ada yang bermasalah, reload dan ulangi kembali')
        }
      } else {
        notification.error({ message: 'Check your file type' })
      }
    }
  }

