  renderFormValue = (attribute) => {
    const { claimBankList = [] } = this.props
    const { name: attributeName, value } = attribute
    const addditionalInfo = get(attribute, 'attribute_info.info')
    switch (attribute.type) {
      case 'boolean':
        return value ? 'Yes' : 'No'
      case 'disclaimer':
        return value ? 'Agree' : 'Not agree'
      case 'string':
      case 'text':
        if (attributeName === 'claim_amount') {
          return Intl.NumberFormat('en-US').format(value)
        }
        return value
      case 'textarea':
        return value
      case 'choices': {
        if (attributeName === 'bank_name') {
          const element = claimBankList.find((item) => item[0] === value)
          return element ? element[1] : ''
        }
        if (attributeName === 'servicecenter_branch') {
          if (!value || typeof value !== 'string') return ''
          const { branch_info: branchInfo = {} } = attribute
          if (!branchInfo) return ''
          const {
            city,
            branch_name: branchName,
            address,
            servicecenter_code: serviceCenterCode,
            is_active: isActive
          } = branchInfo
          return (
            <div>
              <div>Service center code: {serviceCenterCode}</div>
              <div>City: {city} </div>
              <div>Branch Name: {branchName}</div>
              <div>Address: {address}</div>
              <div>
                Branch status:{' '}
                {isActive
                  ? (
                    <StatusContainer isActive={isActive}> Active</StatusContainer>
                    )
                  : (
                    <StatusContainer isActive={isActive}>
                      {' '}
                      Inactive
                    </StatusContainer>
                    )}
              </div>
            </div>
          )
        }
        const choice = attribute.options.reduce((acc, item) => {
          if (
            item[0] === attribute.value ||
            parseInt(item[0]) === attribute.value
          ) {
            acc = [...acc, item[1]]
          }
          return acc
        }, [])
        return choice
      } // eslint-disable-line
      case 'choices_external':
        try {
          return get(JSON.parse(value), 'name')
        } catch (e) {
          return value
        }
      case 'date':
        return attribute.value
          ? momentDefault(attribute.value).format('DD-MM-YYYY')
          : null
      case 'time':
        return attribute.value
          ? momentDefault(attribute.value, 'HH:mm').format('HH:mm')
          : null
      case 'sketch': {
        const extension = getUrlExtension(attribute.value)

        const imgStyle = {
          width: 'auto',
          maxWidth: '244px',
          height: '400px',
          marginTop: '20px',
          marginRight: '7px',
          cursor: 'pointer'
        }

        const imgDivStyle = {
          position: 'relative',
          alignItems: 'center',
          display: 'flex'
        }

        return (
          <ImageComponent
            value={attribute.value}
            divStyle={imgDivStyle}
            imgStyle={imgStyle}
            additionalInfo={addditionalInfo}
            isPDF={extension === 'pdf'}
            onClick={() => this.handlePreview(attribute.name, 0)}
          />
        )
      }
      case 'image': {
        const extension = getUrlExtension(attribute.value)

        const pdfStyle = {
          marginLeft: '10px',
          height: '100px',
          display: 'flex',
          alignItems: 'center',
          fontWeight: 'bold'
        }

        const imgStyle = {
          width: 'auto',
          maxWidth: '200px',
          height: '104px',
          marginTop: '20px',
          marginRight: '7px',
          cursor: 'pointer'
        }

        const imgDivStyle = {
          position: 'relative',
          alignItems: 'center',
          marginTop: 26,
          display: 'flex'
        }

        if (Array.isArray(extension)) {
          return (
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
              {extension.map((val, index) => {
                if (!checkValidURL(attribute.value[index])) {
                  return (
                    <div key={attribute.value[index]}>
                      {attribute.value[index]}{' '}
                      <span className='faded-text'>(Invalid URL)</span>
                    </div>
                  )
                }
                if (val === 'pdf') {
                  return this.renderPdfValue(
                    attribute.value[index],
                    index,
                    pdfStyle
                  )
                } else {
                  return (
                    <ImageComponent
                      value={attribute.value[index]}
                      index={index}
                      divStyle={imgDivStyle}
                      imgStyle={imgStyle}
                      key={attribute.value[index]}
                      // additionalInfo
                      onClick={() => this.handlePreview(attribute.name, index)}
                    />
                  )
                }
              })}
            </div>
          )
        } else {
          if (attribute.value) {
            if (!checkValidURL(attribute.value)) {
              return (
                <div>
                  {attribute.value}{' '}
                  <span className='faded-text'>(Invalid URL)</span>
                </div>
              )
            }
            if (extension === 'pdf' && !addditionalInfo) {
              return this.renderPdfValue(attribute.value, 0, {}, pdfStyle)
            } else {
              return (
                <ImageComponent
                  value={attribute.value}
                  divStyle={imgDivStyle}
                  imgStyle={imgStyle}
                  additionalInfo={addditionalInfo}
                  isPDF={extension === 'pdf'}
                  onClick={() => this.handlePreview(attribute.name, 0)}
                />
              )
            }
          }
        }
        break
      }
      default:
        return value
    }
  };

