  removeUploadedImage (removeImage, formIdentifier, attributeIdentifier) {
    const { detailData } = this.state
    const formArr = detailData.forms.slice()
    formArr.forEach((val) => {
      if (val.name === formIdentifier) {
        for (let i = 0; i < val.attributes.length; i++) {
          if (val.attributes[i].name === attributeIdentifier) {
            const image = []
            if (Array.isArray(val.attributes[i].value)) {
              val.attributes[i].value = val.attributes[i].value.filter(
                (img) => img !== removeImage
              )
            }
            if (val.attributes[i].value === removeImage) {
              val.attributes[i].value = image
            }
          }
        }
      }
    })
    this.setState({
      detailData: {
        ...this.state.detailData,
        forms: formArr
      }
    })
  }

  removeImage (value, formIdentifier, attributeIdentifier) {
    const { uploadedPhotos, photos } = this.state
    const formPhotos =
      uploadedPhotos?.genericDataDocUpload?.[formIdentifier]
    const attributePhotos = formPhotos?.[attributeIdentifier]
    if (attributePhotos) {
      const attributes = attributePhotos.filter(
        (val) => val !== value
      )
      const fileName = value.split('/').pop().split('?')[0]
      const cleanedPhotos = photos[attributeIdentifier]
        ? {
            [attributeIdentifier]: photos[attributeIdentifier].filter(
              (n) => n !== fileName
            )
          }
        : {}
      this.setState({
        uploadedPhotos: {
          ...this.state.uploadedPhotos,
          genericDataDocUpload: {
            ...(this.state.uploadedPhotos?.genericDataDocUpload || {}),
            [formIdentifier]: {
              ...(this.state.uploadedPhotos?.genericDataDocUpload?.[formIdentifier] || {}),
              [attributeIdentifier]: attributes
            }
          }
        },
        photos: {
          ...this.state.photos,
          ...cleanedPhotos
        }
      })
    }
  }

