  checkValuesMatch (info) {
    if (typeof info !== 'object') {
      // if info not object, consider as non auto verify
      return false
    }

    const objectKeys = Object.keys(info)
    if (objectKeys.length < 1) return false // if info object is empty, consider as non auto verify

    let hasCheck = false
    let allMatch = true
    objectKeys.forEach((key) => {
      const requiredAttribute = info[key]
      const {
        extracted_value: extractedValue,
        original_value: requiredValue,
        check_match: requiredCheck
      } = requiredAttribute
      if (requiredCheck) {
        // if attribute info has check, flag as hasCheck
        hasCheck = true
        if (sanitizeString(extractedValue) !== sanitizeString(requiredValue)) {
          allMatch = false
        }
      }
    })

    if (!hasCheck) return false // if this attribute was supposed to be checked in the first place

    return allMatch
  }

  isAutoVerified = (attribute) => {
    const {
      attribute_info: attributeInfo = {
        process_status: '',
        info: {}
      },
      status
    } = attribute
    const { process_status: processStatus, info } = attributeInfo
    const isCompleted = processStatus === 'COMPLETED'
    const verificationAtt = this.getVerificationStatus(status)

    if (isCompleted && this.checkValuesMatch(info)) {
      return (
        <Tag
          color='green'
          style={{
            whiteSpace: 'unset',
            height: 'auto'
          }}
        >
          Auto-Verified
        </Tag>
      )
    } else if (
      ['valid', 'validated_by_pp', 'invalidated_by_pp'].includes(status)
    ) {
      return (
        <Tag
          color={verificationAtt[1]}
          style={{
            whiteSpace: 'unset',
            height: 'auto'
          }}
        >
          {verificationAtt[0]}
        </Tag>
      )
    }
  };

