  renderInputType = (form, attribute, initValue, update) => {
    const {
      claimBankList = [],
      externalChoicesData = [],
      externalChoicesDataLoading
    } = this.props
    const { is_hidden: isHidden, name: attributeName } = attribute
    const { detailData } = this.state

    const renderOptions = () => {
      if (isHidden) return null

      if (attributeName === 'bank_name') {
        if (claimBankList && Array.isArray(claimBankList)) {
          return claimBankList.map((bank) => (
            <Option key={bank[0]} value={bank[0]}>
              {bank[1]}
            </Option>
          ))
        }
        return null
      }

      if (attribute.options && Array.isArray(attribute.options)) {
        return attribute.options.map((bank, index) => (
          <Option key={index} value={bank[0]}>
            {bank[1]}
          </Option>
        ))
      }

      return null
    }
    const disabledDate = (current) => {
      if (!current) return false

      const toJakartaDay = (date) =>
        moment.utc(date).tz('Asia/Jakarta').startOf('day')

      const currentJakarta = moment(current).tz('Asia/Jakarta').startOf('day')

      const startDate = attribute.calendar_date_starting_from
        ? toJakartaDay(attribute.calendar_date_starting_from)
        : null

      const endDate = attribute.calendar_date_end_on
        ? moment
            .utc(attribute.calendar_date_end_on)
            .tz('Asia/Jakarta')
            .endOf('day')
        : null

      if (startDate && endDate) {
        return (
          currentJakarta.isBefore(startDate, 'day') ||
          currentJakarta.isAfter(endDate, 'day')
        )
      }

      if (startDate) {
        return currentJakarta.isBefore(startDate, 'day')
      }

      if (endDate) {
        return currentJakarta.isAfter(endDate, 'day')
      }

      return false
    }
    switch (attribute.type) {
      case 'image':
      case 'pdf':
        return (
          <Spin
            spinning={this.state.loader[attribute.name] === true}
            tip='Uploading ...'
          >
            <div>
              {this.renderUpload(attribute, form)}
              <Col>
                {!!initValue && (
                  <div
                    style={{
                      display: 'flex',
                      flexWrap: 'wrap'
                    }}
                  >
                    {this.renderImage(form, attribute)}
                    {this.renderAnotherButton(attribute, form)}
                  </div>
                )}
                {this.renderFailedUploads(form, attribute)}
              </Col>
            </div>
          </Spin>
        )
      case 'date':

        return (
          <DatePicker
            format='DD-MM-YYYY'
            disabledDate={disabledDate}
            disabled={!attribute.is_editable}
            onChange={this.handleChangeDate}
          />
        )
      case 'choices':
        return (
          <Select
            showSearch
            // labelInValue={labelInValueCheck}
            placeholder='Pilih ...'
            style={{
              width: '100%'
            }}
            dropdownMatchSelectWidth={false}
            onChange={this.handleInputChange}
            filterOption={(input, option) =>
              option.props.children
                .toLowerCase()
                .indexOf(input.toLowerCase()) >= 0}
            getPopupContainer={() => document.getElementById('area')}
          >
            {renderOptions()}
          </Select>
        )
      case 'choices_external':
        return (
          <Select
            showSearch
            placeholder='Pilih...'
            dropdownMatchSelectWidth={false}
            onSearch={(value) =>
              this.handleExternalChoiceChange(
                value,
                get(attribute, 'options', [])[0]
              )}
            loading={!!externalChoicesDataLoading}
            filterOption={(input, option) =>
              option.props.children
                .toLowerCase()
                .indexOf(input.toLowerCase()) >= 0}
          >
            {Array.isArray(externalChoicesData) && externalChoicesData.map((data) => (
              <Option key={data.code} value={JSON.stringify(data)}>
                {data.name}
              </Option>
            ))}
          </Select>
        )
      case 'textarea':
      case 'text':
        return <TextArea autosize={{ minRows: 2, maxRows: 8 }} />
      case 'asterisk':
        return (
          <Input.Password
            disabled={!attribute.is_editable}
            autocomplete='new-password'
          />
        )
      case 'radio':
        return (
          <RadioGroup
            onChange={(e) => this.onChangeRadio(e, attribute.name, form.name)}
          >
            {attribute.options && Array.isArray(attribute.options) && attribute.options.map((checkbox, index) => (
              <Radio key={index} value={checkbox[0]}>
                {checkbox[1]}
              </Radio>
            ))}
          </RadioGroup>
        )
      case 'disclaimer':
        return (
          <Checkbox
            defaultChecked={!!initValue}
            // checked='checked'
            // value='value'
            // style={{
            //   display: 'none'
            // }}
          />
        )
      case 'checkbox':
        return (
          <Checkbox
            disabled={!attribute.is_editable}
            onChange={this.handleCheckBox}
          />
        )
      case 'int':
        return <InputNumber style={{ width: '100%' }} min={0} />
      case 'boolean':
        return (
          <Select disabled={!attribute.is_editable}>
            {FORM_BOOLEAN.map((option) => (
              <Select.Option key={option.displayName} value={option.value}>
                {option.displayName}
              </Select.Option>
            ))}
          </Select>
        )
      case 'sketch':
        return (
          <CarSketch
            claimId={detailData.claim_id}
            value={attribute.value}
            identifier={attribute.name}
            formIdentifier={form.name}
            generateSignedUrlAndUpload={this.handleChange}
            statusGroup={detailData.status_group}
          />
        )
      default:
        if (attribute.name === 'account_number') {
          return (
            <Input
              type={attribute.type}
              onChange={this.handleInputChange}
              onBlur={() => {
                this.handleConfirmBlur(form, attribute)
              }}
            />
          )
        } else if (attribute.name === 'claim_amount') {
          return (
            <Input
              type='number'
              inputMode='numeric'
              pattern='[0-9]*'
            />
          )
        } else {
          return (
            <Input
              type={attribute.type}
              // defaultValue={attribute.value}
              disabled={!attribute.is_editable && !update}
              onKeyPress={() => this.removeVerifyStatus(attribute)}
              onKeyDown={() => this.removeVerifyStatus(attribute)}
            />
          )
        }
    }
  };

