import React, { Component } from 'react'
import moment from 'moment-timezone'
import { connect } from 'react-redux'
import { MessageContainer } from './claimsCommentBox.style'
import {
  Row,
  Col,
  Modal,
  Spin,
  Button
} from 'antd'

class ClaimCommentMessageContainer extends Component {
  constructor (props) {
    super(props)
    this.state = {
      listcommentsData: [],
      data: '',
      visible: false
    }
  }

  UNSAFE_componentWillReceiveProps(nextProps) {
    const {
      listcommentsData,
      listcommentsTicketStatus,
      getDetailsClaimStatus,
      detailData={}
    } = nextProps.detailClaims

    if (listcommentsTicketStatus !== '' && listcommentsTicketStatus === 'success') {
      if (this.props.ticketId === listcommentsData.ticketId) {
        this.setState({
          listcommentsData: listcommentsData.data
        })
      }
    }

    if (getDetailsClaimStatus !== "") {
      this.setState({ detailData });
    }

  }
  
  openImageModal = (url) => {
       this.setState({
         data: url,
         visible: true
       })
  }
  
  handleCancel = () => {
      this.setState({ visible: false })
  };

  getReceivingName = (userId=null) => {
    if(!userId) {
      return "USER"
    }
    const { detailData } = this.state;

    if(userId === detailData?.userid) {
      return detailData["user_name"] || "USER"
    }

    if(userId === detailData?.external_userid) {
      return detailData["agent_user_name"] || "USER"
    }
    return "USER"
    }

     render () {
       const {
         listcommentsData,
         data
       } = this.state
       const {
         ticketLoading
       } = this.props

       return (
         <React.Fragment>
           <Modal
             title='Image Viewer'
             visible={this.state.visible}
             footer={null}
             onCancel={this.handleCancel}
           >
             <img src={data} width='100%' alt='' />
           </Modal>

           <div
             className='chat-box'
           >
             <Spin spinning={!!ticketLoading}>
               
             {
                 (listcommentsData && listcommentsData.data) && listcommentsData.data.length
                   ? listcommentsData.data.map((val) => {
                     if (val.comment_source === 'policy_panel') {
                       return (
                         <React.Fragment>

                           <MessageContainer
                             width={(val.attachments && val.attachments.length)}
                           >
                             <p>{val.comment}</p>
                             {
                               (val.attachments && val.attachments.length)
                                 ? val.attachments.map((item) => {
                                  if (item.type === 'image/png' || item.type === 'image/jpeg') {
                                    return (
                                      <p>
                                        <img alt='' src={item.url} height={80} width={100} onClick={() => this.openImageModal(item.url)} style={{ cursor: 'pointer' }} />
                                      </p>
                                    )
                                  } else {
                                    return (
                                      <a href={item.url} target='_blank' rel='noopener noreferrer'>File</a>
                                    )
                                  }
                                })
                                 : ''
                             }
                             {/* <p> Email Template key adding left</p> */}
                             <Row type='flex' justify='space-between'>
                               <Col>
                                 {this.getReceivingName(val?.user_id)}
                               </Col>
                               <Col>
                                 {moment.utc(val.created_at).tz(this.props.timezone).format('lll')}
                               </Col>
                             </Row>
                           </MessageContainer>
                         </React.Fragment>
                       )
                     } else if (val.comment_source === 'email') {
                       return (
                         <React.Fragment>

                           <MessageContainer
                             width={(val.attachments && val.attachments.length)}
                           >
                           <p>{val.comment}</p>
                             {
                               (val.attachments && val.attachments.length)
                                 ? val.attachments.map((item) => {
                                   if (item?.content_type === 'image/png' || item?.content_type === 'image/jpeg' || item?.content_type === 'image/jpg') {
                                     return (
                                       <p>
                                         <img alt='' src={item?.content_url} height={80} width={100} onClick={() => this.openImageModal(item.url)} style={{ cursor: 'pointer' }} />
                                       </p>
                                     )
                                   } else {
                                     return (
                                       <a href={item?.content_url} target='_blank' rel='noopener noreferrer'>File</a>
                                     )
                                   }
                                 })
                                 : ''
                             }
                             {/* <p> Email Template key adding left</p> */}
                             <Row type='flex' justify='space-between'>
                               <Col>
                               {this.getReceivingName(val?.user_id)}
                               </Col>
                               <Col>
                                 {moment.utc(val.created_at).tz(this.props.timezone).format('lll')}
                               </Col>
                             </Row>
                           </MessageContainer>
                           {
                             val.first_email !== null
                               ? <div className='email-box-wrapper'>
                                 <Button onClick={() => { this.props.openEmailModal(val.first_email) }}>
                                  View PP Email
                                 </Button>
                               </div>
                               : ''
                           }
                         </React.Fragment>
                       )
                     } else if (val.comment_source === 'email') {
                       return (
                         <React.Fragment>

                           <MessageContainer
                             width={(val.attachments && val.attachments.length)}
                           >
                             <p>{val.comment}</p>
                             {
                               (val.attachments && val.attachments.length)
                                 ? val.attachments.map((item) => {
                                   if (item.type === 'image/png' || item.type === 'image/jpeg') {
                                     return (
                                       <p>
                                         <img alt='' src={item.url} height={80} width={100} onClick={() => this.openImageModal(item.url)} style={{ cursor: 'pointer' }} />
                                       </p>
                                     )
                                   } else {
                                     return (
                                       <a href={item.url} target='_blank' rel='noopener noreferrer'>File</a>
                                     )
                                   }
                                 })
                                 : ''
                             }
                             {/* <p> Email Template key adding left</p> */}
                             <Row type='flex' justify='space-between'>
                               <Col>
                               {this.getReceivingName(val?.user_id)}

                               </Col>
                               <Col>
                                 {moment.utc(val.created_at).tz(this.props.timezone).format('lll')}
                               </Col>
                             </Row>
                           </MessageContainer>

                           {
                             val.first_email !== null
                               ? <div className='email-box-wrapper'>
                                 <Button onClick={() => { this.props.openEmailModal(val.first_email) }}>
                                  View PP Email
                                 </Button>
                               </div>
                               : ''
                           }
                         </React.Fragment>
                       )
                     }
                     return (
                       <div
                         className='messages'
                       >
                         <p>{val.comment}</p>
                         {
                           (val.attachments && val.attachments.length)
                             ? val.attachments.map((item) => {
                               if (item.type === 'image/png' || item.type === 'image/jpeg') {
                                 return (
                                   <p>
                                     <img alt='' src={item.url} height={80} width={100} onClick={() => this.openImageModal(item.url)} style={{ cursor: 'pointer' }} />
                                   </p>
                                 )
                               } else {
                                 return (
                                   <a href={item.url} target='_blank' rel='noopener noreferrer' >File</a>
                                 )
                               }
                             })
                             : ''
                         }
                         {/* <p> Email Template key adding left</p> */}
                         <Row type='flex' justify='space-between'>
                           <Col>
                             {val.user_id}
                           </Col>
                           <Col>
                             {moment.utc(val.created_at).tz(this.props.timezone).format('lll')}
                           </Col>
                         </Row>
                       </div>
                     )
                   })
                   : ''
               }
             </Spin>
           </div>
         </React.Fragment>
       )
     }
}

export default connect(state => ({
  detailClaims: state.Claims,
  ticketLoading: state.Loading.LIST_COMMENTS_TICKET,
  ticketError: state.Error.LIST_COMMENTS_TICKET
}), {
})(ClaimCommentMessageContainer)
