import React, { useState, useEffect, useCallback, useRef } from 'react'
import { Modal, Row, Col, Spin, Card, Alert, Icon } from 'antd'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import agentActions from '../../../redux/agent/actions'
import policyActions from '../../../../redux/policy/actions'
import PDFModal from './PDFModal'

const ComparePolicyDataModal = ({
  visible,
  onCancel,
  detailData,
  claimAttribute,
  agentPolicyDetails,
  policyDetail,
  getAgentPolicyDetails,
  getPolicyDetails
}) => {
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState(null)
  const [previewVisible, setPreviewVisible] = useState(false)
  const [previewImage, setPreviewImage] = useState([])
  const [activeIndexImage, setActiveIndexImage] = useState(0)
  const [showPDFModal, setShowPDFModal] = useState(false)
  const [pdfFile, setPdfFile] = useState(null)
  const [numPages, setNumPages] = useState(null)
  const [pdfRotation, setPdfRotation] = useState(0)
  const [imageRotation, setImageRotation] = useState(0)
  const [imageScale, setImageScale] = useState(1)
  const [imageOffset, setImageOffset] = useState({ x: 0, y: 0 })
  const [isPanning, setIsPanning] = useState(false)

  // refs used for panning calculations so event handlers don't close over stale state
  const panStartRef = useRef({ x: 0, y: 0 })
  const imageOffsetRef = useRef({ x: 0, y: 0 })

  const fetchPolicyData = useCallback(async () => {
    if (!detailData?.internal_id) {
      setError('No policy ID available')
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      // Primary policy type detection - use explicit type first
      let isAgencyPolicy = false

      // Primary check: explicit type
      if (detailData?.type === 'agency') {
        isAgencyPolicy = true
      } else if (detailData?.source === 'agency') {
        isAgencyPolicy = true
      } else if (detailData?.agent_user_name || detailData?.agent_user_email) {
        isAgencyPolicy = true
      } else {
        isAgencyPolicy = false
      }

      if (isAgencyPolicy) {
        // Fetch agency policy data only
        await getAgentPolicyDetails(detailData.internal_id)
      } else {
        // Fetch non-agency policy data only
        await getPolicyDetails({
          query: {
            id: detailData.internal_id,
            er: 1,
            field: 'endorsement,retry_policy,closure'
          }
        })
      }
    } catch (error) {
      console.error('Error fetching policy data:', error)
      setError('Failed to fetch policy data')
    } finally {
      setIsLoading(false)
    }
  }, [detailData, getAgentPolicyDetails, getPolicyDetails])

  useEffect(() => {
    if (visible && detailData) {
      fetchPolicyData()
    }
  }, [visible, detailData, fetchPolicyData])

  // Helper functions for file type detection
  const isPdfFile = (url) => {
    if (!url || typeof url !== 'string') return false
    return url.toLowerCase().includes('.pdf') || url.toLowerCase().includes('pdf')
  }

  // Popup handlers
  const handlePreview = (fileUrl, index = 0, allFiles = null) => {
    if (isPdfFile(fileUrl)) {
      handleOpenPDFModal(fileUrl)
    } else {
      // If allFiles is provided, use it; otherwise create array with single file
      const imageFiles = allFiles ? allFiles.filter(file => !isPdfFile(file)) : [fileUrl]
      const imageIndex = allFiles ? imageFiles.findIndex(img => img === fileUrl) : 0

      setPreviewImage(imageFiles)
      setPreviewVisible(true)
      setActiveIndexImage(Math.max(0, imageIndex))
    }
  }

  const handleCancelShowImg = () => {
    setPreviewImage([])
    setPreviewVisible(false)
    setImageRotation(0) // Reset rotation when closing modal
    setImageScale(1) // Reset zoom when closing modal
    imageOffsetRef.current = { x: 0, y: 0 }
    setImageOffset({ x: 0, y: 0 })
  }

  // Keyboard navigation for image preview
  useEffect(() => {
    const handleKeyPress = (e) => {
      if (previewVisible) {
        if (e.key === 'ArrowLeft' && previewImage.length > 1) {
          setActiveIndexImage((prev) => prev > 0 ? prev - 1 : previewImage.length - 1)
          setImageRotation(0) // Reset rotation when changing images
          setImageScale(1) // Reset zoom when changing images
          imageOffsetRef.current = { x: 0, y: 0 }
          setImageOffset({ x: 0, y: 0 })
        } else if (e.key === 'ArrowRight' && previewImage.length > 1) {
          setActiveIndexImage((prev) => prev < previewImage.length - 1 ? prev + 1 : 0)
          setImageRotation(0) // Reset rotation when changing images
          setImageScale(1) // Reset zoom when changing images
          imageOffsetRef.current = { x: 0, y: 0 }
          setImageOffset({ x: 0, y: 0 })
        } else if (e.key === 'Escape') {
          handleCancelShowImg()
        } else if (e.key === 'r' || e.key === 'R') {
          if (e.shiftKey) {
            handleRotateLeftImage() // Shift+R for rotate left
          } else {
            handleRotateRightImage() // R for rotate right
          }
        } else if (e.key === '+' || e.key === '=') {
          // Zoom in on '+' or '='
          setImageScale((s) => Math.min(3, Number((s + 0.1).toFixed(2))))
        } else if (e.key === '-') {
          // Zoom out on '-'
          setImageScale((s) => Math.max(0.2, Number((s - 0.1).toFixed(2))))
        }
      }
    }

    if (previewVisible) {
      document.addEventListener('keydown', handleKeyPress)
      return () => document.removeEventListener('keydown', handleKeyPress)
    }
  }, [previewVisible, previewImage.length])

  const handleOpenPDFModal = (fileUrl) => {
    setShowPDFModal(true)
    setPdfFile(fileUrl)
    setNumPages(null)
    setPdfRotation(0)
  }

  const handleClosePDFModal = () => {
    setShowPDFModal(false)
    setPdfFile(null)
    setNumPages(null)
    setPdfRotation(0)
  }

  const handleOnDocumentLoadSuccess = ({ numPages }) => {
    setNumPages(numPages)
  }

  const handleRotateRightPDF = () => {
    setPdfRotation((prevState) => (prevState + 90) % 360)
  }

  const handleRotateLeftPDF = () => {
    setPdfRotation((prevState) => (prevState - 90) % 360)
  }

  const handleRotateLeftImage = () => {
    setImageRotation((prevState) => (prevState - 90) % 360)
  }

  const handleRotateRightImage = () => {
    setImageRotation((prevState) => (prevState + 90) % 360)
  }

  const handleZoomInImage = () => setImageScale((s) => Math.min(3, Number((s + 0.1).toFixed(2))))
  const handleZoomOutImage = () => setImageScale((s) => Math.max(0.2, Number((s - 0.1).toFixed(2))))

  // Panning (drag-to-pan) handlers and helpers
  const handleWindowMouseMove = (e) => {
    // compute delta since last recorded point
    const dx = e.clientX - panStartRef.current.x
    const dy = e.clientY - panStartRef.current.y

    panStartRef.current = { x: e.clientX, y: e.clientY }
    imageOffsetRef.current = {
      x: imageOffsetRef.current.x + dx,
      y: imageOffsetRef.current.y + dy
    }
    setImageOffset({ ...imageOffsetRef.current })
  }

  const handleWindowMouseUp = () => {
    setIsPanning(false)
    document.body.style.userSelect = ''
    window.removeEventListener('mousemove', handleWindowMouseMove)
    window.removeEventListener('mouseup', handleWindowMouseUp)
  }

  const handleMouseDownOnImage = (e) => {
    if (imageScale === 1) return
    e.preventDefault()
    panStartRef.current = { x: e.clientX, y: e.clientY }
    setIsPanning(true)
    document.body.style.userSelect = 'none'
    window.addEventListener('mousemove', handleWindowMouseMove)
    window.addEventListener('mouseup', handleWindowMouseUp)
  }

  // Touch handlers for mobile
  const handleTouchStart = (e) => {
    if (!e.touches || e.touches.length === 0) return
    if (imageScale === 1) return
    const t = e.touches[0]
    panStartRef.current = { x: t.clientX, y: t.clientY }
    setIsPanning(true)
    document.body.style.userSelect = 'none'
  }

  const handleTouchMove = (e) => {
    if (!e.touches || e.touches.length === 0) return
    if (!isPanning) return
    const t = e.touches[0]
    const dx = t.clientX - panStartRef.current.x
    const dy = t.clientY - panStartRef.current.y
    panStartRef.current = { x: t.clientX, y: t.clientY }
    imageOffsetRef.current = {
      x: imageOffsetRef.current.x + dx,
      y: imageOffsetRef.current.y + dy
    }
    setImageOffset({ ...imageOffsetRef.current })
    e.preventDefault()
  }

  const handleTouchEnd = () => {
    setIsPanning(false)
    document.body.style.userSelect = ''
  }

  const renderClaimImages = (attribute) => {
    if (!attribute || !attribute.value) {
      return (
        <div style={{ padding: '20px', textAlign: 'center', border: '1px dashed #ccc', borderRadius: '4px' }}>
          <p><strong>Claim Files</strong></p>
          <p>No claim files available</p>
        </div>
      )
    }

    // Extract claim files and convert to consistent format
    const files = Array.isArray(attribute.value) ? attribute.value : [attribute.value]
    const claimFiles = files
      .filter(file => file && typeof file === 'string' && file.trim() !== '')
      .map((url, index) => ({ url, label: `File ${index + 1}` }))

    if (claimFiles.length === 0) {
      return (
        <div style={{ padding: '20px', textAlign: 'center', border: '1px dashed #ccc', borderRadius: '4px' }}>
          <p><strong>Claim Files</strong></p>
          <p>No claim files available</p>
        </div>
      )
    }

    return (
      <div>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(2, 1fr)',
          gap: '10px',
          padding: '10px',
          justifyItems: 'center'
        }}
        >
          {claimFiles.map((file, index) => {
            const isPdf = isPdfFile(file.url)

            if (isPdf) {
              return (
                <div key={index} style={{ textAlign: 'center', marginBottom: '10px' }}>
                  <div style={{ fontSize: '12px', marginBottom: '5px', fontWeight: 'bold' }}>
                    {file.label} PDF
                  </div>
                  <div
                    onClick={() => handlePreview(file.url, index)}
                    style={{
                      width: '120px',
                      height: '90px',
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'center',
                      border: '1px solid #d9d9d9',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      fontSize: '12px',
                      color: '#1890ff',
                      backgroundColor: '#f9f9f9'
                    }}
                  >
                    <Icon type='file-pdf' style={{ fontSize: '24px', marginBottom: '5px' }} />
                    View PDF
                  </div>
                </div>
              )
            } else {
              return (
                <div key={index} style={{ textAlign: 'center', marginBottom: '10px' }}>
                  <div style={{ fontSize: '12px', marginBottom: '5px', fontWeight: 'bold' }}>
                    {file.label}
                  </div>
                  <img
                    src={file.url}
                    alt={`Claim ${file.label}`}
                    style={{
                      width: '250px',
                      height: '150px',
                      objectFit: 'cover',
                      borderRadius: '4px',
                      border: '1px solid #d9d9d9',
                      cursor: 'pointer'
                    }}
                    onClick={() => {
                      const allImageFiles = claimFiles.filter(f => !isPdfFile(f.url))
                      const imageUrls = allImageFiles.map(f => f.url)
                      handlePreview(file.url, 0, imageUrls)
                      setImageScale(1)
                      imageOffsetRef.current = { x: 0, y: 0 }
                      setImageOffset({ x: 0, y: 0 })
                    }}
                    onError={(e) => {
                      e.target.style.display = 'none'
                      e.target.nextSibling.style.display = 'flex'
                    }}
                  />
                  <div style={{
                    width: '120px',
                    height: '90px',
                    display: 'none',
                    alignItems: 'center',
                    justifyContent: 'center',
                    border: '1px dashed #ccc',
                    borderRadius: '4px',
                    fontSize: '12px',
                    color: '#999'
                  }}
                  >
                    File failed to load
                  </div>
                </div>
              )
            }
          })}
        </div>
      </div>
    )
  }

  const renderPolicyImages = () => {
    // Extract policy images from different sources
    let policyFiles = []

    // Determine policy type and extract vehicle images
    const isAgencyPolicy = detailData?.type === 'agency' ||
                          detailData?.source === 'agency' ||
                          detailData?.agent_user_name ||
                          detailData?.agent_user_email

    if (isAgencyPolicy && agentPolicyDetails) {
      try {
        const policyDetail = JSON.parse(agentPolicyDetails.policy_detail || '{}')
        const objectInsuredImage = policyDetail.images || {}

        const vehicleImages = {
          back: objectInsuredImage.back || null,
          front: objectInsuredImage.front || null,
          left: objectInsuredImage.left || null,
          right: objectInsuredImage.right || null,
          dashboard: objectInsuredImage.dashboard || null
        }

        // Convert to array format similar to claim files
        policyFiles = Object.entries(vehicleImages)
          .filter(([_, url]) => url)
          .map(([position, url]) => ({ url, label: position }))
      } catch (error) {
        console.error('Error parsing agency policy detail:', error)
      }
    } else if (!isAgencyPolicy && policyDetail) {
      const insuredData = policyDetail.Request?.insured_data || {}

      const vehicleImages = {
        back: insuredData.back || null,
        front: insuredData.front || null,
        left: insuredData.left || null,
        right: insuredData.right || null,
        dashboard: insuredData.dashboard || null
      }

      // Convert to array format similar to claim files
      policyFiles = Object.entries(vehicleImages)
        .filter(([_, url]) => url)
        .map(([position, url]) => ({ url, label: position }))
    }

    if (policyFiles.length === 0) {
      return (
        <div style={{ padding: '20px', textAlign: 'center', border: '1px dashed #ccc', borderRadius: '4px' }}>
          <p><strong>Policy Files</strong></p>
          <p>No policy files available</p>
        </div>
      )
    }

    return (
      <div>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(2, 1fr)',
          gap: '10px',
          padding: '10px',
          justifyItems: 'center'
        }}
        >
          {policyFiles.map((file, index) => {
            const isPdf = isPdfFile(file.url)

            if (isPdf) {
              return (
                <div key={index} style={{ textAlign: 'center', marginBottom: '10px' }}>
                  <div style={{ fontSize: '12px', marginBottom: '5px', fontWeight: 'bold', textTransform: 'capitalize' }}>
                    {file.label} PDF
                  </div>
                  <div
                    onClick={() => handlePreview(file.url, index)}
                    style={{
                      width: '120px',
                      height: '90px',
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'center',
                      border: '1px solid #d9d9d9',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      fontSize: '12px',
                      color: '#1890ff',
                      backgroundColor: '#f9f9f9'
                    }}
                  >
                    <Icon type='file-pdf' style={{ fontSize: '24px', marginBottom: '5px' }} />
                    View PDF
                  </div>
                </div>
              )
            } else {
              return (
                <div key={index} style={{ textAlign: 'center', marginBottom: '10px' }}>
                  <div style={{ fontSize: '12px', marginBottom: '5px', fontWeight: 'bold', textTransform: 'capitalize' }}>
                    {file.label}
                  </div>
                  <img
                    src={file.url}
                    alt={`Vehicle ${file.label}`}
                    style={{
                      width: '250px',
                      height: '150px',
                      objectFit: 'cover',
                      borderRadius: '4px',
                      border: '1px solid #d9d9d9',
                      cursor: 'pointer'
                    }}
                    onClick={() => {
                      const allImageFiles = policyFiles.filter(f => !isPdfFile(f.url))
                      const imageUrls = allImageFiles.map(f => f.url)
                      handlePreview(file.url, 0, imageUrls)
                      setImageScale(1)
                      imageOffsetRef.current = { x: 0, y: 0 }
                      setImageOffset({ x: 0, y: 0 })
                    }}
                    onError={(e) => {
                      e.target.style.display = 'none'
                      e.target.nextSibling.style.display = 'block'
                    }}
                  />
                  <div style={{
                    width: '120px',
                    height: '90px',
                    display: 'none',
                    alignItems: 'center',
                    justifyContent: 'center',
                    border: '1px dashed #ccc',
                    borderRadius: '4px',
                    fontSize: '12px',
                    color: '#999'
                  }}
                  >
                    File failed to load
                  </div>
                </div>
              )
            }
          })}
        </div>
      </div>
    )
  }

  const renderClaimAttribute = (attribute) => {
    if (!attribute) return null

    // Safely render the attribute value
    const renderAttributeValue = () => {
      try {
        if (attribute.type === 'image' || attribute.type === 'pdf') {
          return renderClaimImages(attribute)
        } else {
          // Handle different value types safely
          if (attribute.value === null || attribute.value === undefined) {
            return 'N/A'
          }

          // If it's an object or array, stringify it
          if (typeof attribute.value === 'object') {
            return JSON.stringify(attribute.value)
          }

          // Convert to string safely
          return String(attribute.value)
        }
      } catch (error) {
        console.error('Error rendering claim attribute:', error, attribute)
        return 'Error rendering data'
      }
    }

    return (
      <Card size='small' style={{ marginBottom: '10px' }}>
          {renderAttributeValue()}
      </Card>
    )
  }

  return (
    <Modal
      title='Compare With Policy Data'
      visible={visible}
      onCancel={onCancel}
      footer={null}
      width='95%'
      style={{ top: 20 }}
      bodyStyle={{ maxHeight: '80vh', overflowY: 'auto' }}
    >
      {error && (
        <Alert
          message='Error'
          description={error}
          type='error'
          showIcon
          style={{ marginBottom: '20px' }}
        />
      )}

      <Spin spinning={isLoading || (detailData?.type === 'agency' && !agentPolicyDetails) || (detailData?.type !== 'agency' && !policyDetail)}>
        <Row gutter={24}>
          <Col span={12}>
            <div style={{ textAlign: 'center', marginBottom: '20px' }}>
              <h3>Object Insured Image</h3>
            </div>
            <div style={{
              borderRadius: '4px',
              padding: '16px',
              minHeight: '400px',
              maxHeight: '600px',
              overflowY: 'auto'
            }}
            >

              <Card size='small'>
                {renderPolicyImages()}
              </Card>
            </div>
          </Col>

          <Col span={12}>
            <div style={{ textAlign: 'center', marginBottom: '20px' }}>
              <h3>Claim Image</h3>
            </div>
            <div style={{
              borderRadius: '4px',
              padding: '16px',
              minHeight: '400px',
              maxHeight: '600px',
              overflowY: 'auto',
            }}
            >
              {claimAttribute ? renderClaimAttribute(claimAttribute) : <p>No claim data available</p>}
            </div>
          </Col>
        </Row>
      </Spin>

      {/* Image Preview Modal */}
      <Modal
        visible={previewVisible}
        title={`Image Preview (${activeIndexImage + 1} of ${previewImage.length})${imageRotation !== 0 ? ` - Rotated ${imageRotation}°` : ''}`}
        footer={null}
        onCancel={handleCancelShowImg}
        width='80%'
        style={{ top: 20 }}
        bodyStyle={{
          overflow: 'auto',
          display: 'flex',
          justifyContent: 'center',
          paddingBottom: '60px'
        }}
      >
        {previewImage && previewImage.length > 0 ? (
          <>
            {/* Main Image Display */}
            <div style={{ textAlign: 'center', position: 'relative', width: '100%' }}>
              {previewImage[activeIndexImage] && (
                <img
                  alt={`preview ${activeIndexImage + 1}`}
                  src={previewImage[activeIndexImage]}
                  draggable={false}
                  onMouseDown={handleMouseDownOnImage}
                  onTouchStart={handleTouchStart}
                  onTouchMove={handleTouchMove}
                  onTouchEnd={handleTouchEnd}
                  style={{
                    width: '100%',
                    maxWidth: '800px',
                    height: 'auto',
                    transform: `translate(${imageOffset.x}px, ${imageOffset.y}px) rotate(${imageRotation}deg) scale(${imageScale})`,
                    transformOrigin: 'center center',
                    transition: isPanning ? 'none' : 'transform 0.3s ease',
                    cursor: isPanning ? 'grabbing' : (imageScale === 1 ? 'auto' : 'grab')
                  }}
                  onError={(e) => {
                    e.target.style.display = 'none'
                    e.target.nextSibling.style.display = 'block'
                  }}
                />
              )}
              <div style={{
                display: 'none',
                padding: '50px',
                textAlign: 'center',
                color: '#999',
                fontSize: '16px'
              }}
              >
                Failed to load image
              </div>

              {/* Floating Navigation Buttons */}
              {previewImage.length > 1 && (
                <>
                  <div
                    onClick={() => setActiveIndexImage((prev) => prev > 0 ? prev - 1 : previewImage.length - 1)}
                    style={{
                      position: 'absolute',
                      left: '10px',
                      top: '50%',
                      transform: 'translateY(-50%)',
                      backgroundColor: 'rgba(0, 0, 0, 0.6)',
                      color: 'white',
                      borderRadius: '50%',
                      width: '40px',
                      height: '40px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      cursor: 'pointer',
                      fontSize: '18px',
                      zIndex: 10,
                      transition: 'all 0.3s ease',
                      opacity: 0.7
                    }}
                    onMouseEnter={(e) => { e.target.style.opacity = 1 }}
                    onMouseLeave={(e) => { e.target.style.opacity = 0.7 }}
                    title='Previous image (←)'
                  >
                    <Icon type='left' />
                  </div>
                  <div
                    onClick={() => { setActiveIndexImage((prev) => prev < previewImage.length - 1 ? prev + 1 : 0); setImageScale(1); setImageRotation(0) }}
                    style={{
                      position: 'absolute',
                      right: '10px',
                      top: '50%',
                      transform: 'translateY(-50%)',
                      backgroundColor: 'rgba(0, 0, 0, 0.6)',
                      color: 'white',
                      borderRadius: '50%',
                      width: '40px',
                      height: '40px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      cursor: 'pointer',
                      fontSize: '18px',
                      zIndex: 10,
                      transition: 'all 0.3s ease',
                      opacity: 0.7
                    }}
                    onMouseEnter={(e) => { e.target.style.opacity = 1 }}
                    onMouseLeave={(e) => { e.target.style.opacity = 0.7 }}
                    title='Next image (→)'
                  >
                    <Icon type='right' />
                  </div>
                </>
              )}
            </div>

            {/* Thumbnail strip for multiple images */}
            {previewImage.length > 1 && (
              <div style={{
                position: 'absolute',
                bottom: '70px',
                left: '50%',
                transform: 'translateX(-50%)',
                display: 'flex',
                justifyContent: 'center',
                gap: '10px',
                padding: '10px',
                backgroundColor: 'rgba(255, 255, 255, 0.9)',
                borderRadius: '8px',
                zIndex: 10
              }}
              >
                {previewImage.map((imgUrl, index) => (
                  <div
                    key={index}
                    onClick={() => {
                      setActiveIndexImage(index)
                      setImageRotation(0) // Reset rotation when switching images
                      imageOffsetRef.current = { x: 0, y: 0 }
                      setImageOffset({ x: 0, y: 0 })
                    }}
                    style={{
                      width: '60px',
                      height: '45px',
                      border: index === activeIndexImage ? '2px solid #1890ff' : '1px solid #d9d9d9',
                      borderRadius: '4px',
                      overflow: 'hidden',
                      cursor: 'pointer',
                      opacity: index === activeIndexImage ? 1 : 0.7
                    }}
                  >
                    <img
                      src={imgUrl}
                      alt={`thumbnail ${index + 1}`}
                      style={{
                        width: '100%',
                        height: '100%',
                        objectFit: 'cover'
                      }}
                      onError={(e) => {
                        e.target.style.display = 'none'
                      }}
                    />
                  </div>
                ))}
              </div>
            )}

            {/* Bottom Controls Bar (like PDF Modal) */}
            <div
              style={{
                position: 'fixed',
                bottom: 0,
                width: '80%',
                backgroundColor: '#fff',
                padding: '10px 20px',
                borderTop: '1px solid #ddd',
                textAlign: 'right',
                zIndex: 1000,
                display: 'flex',
                gap: '16px',
                alignItems: 'center',
                justifyContent: 'flex-end'
              }}
            >
              <div
                type='default' onClick={handleRotateLeftImage} style={{
                  borderRadius: '4px',
                  padding: '4px 15px',
                  cursor: 'pointer',
                  backgroundColor: '#fff',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  minHeight: '32px',
                  transition: 'all 0.3s ease'
                }}
                onMouseEnter={(e) => {
                  e.target.style.borderColor = '#40a9ff'
                  e.target.style.color = '#40a9ff'
                }}
                onMouseLeave={(e) => {
                  e.target.style.borderColor = '#d9d9d9'
                  e.target.style.color = 'rgba(0, 0, 0, 0.65)'
                }}
              >
                <Icon type='rollback' style={{ fontSize: 20 }} />
              </div>
              <div
                type='default' onClick={handleZoomOutImage} style={{
                  borderRadius: '4px',
                  padding: '4px 15px',
                  cursor: 'pointer',
                  backgroundColor: '#fff',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  minHeight: '32px',
                  transition: 'all 0.3s ease'
                }}
                onMouseEnter={(e) => {
                  e.target.style.borderColor = '#40a9ff'
                  e.target.style.color = '#40a9ff'
                }}
                onMouseLeave={(e) => {
                  e.target.style.borderColor = '#d9d9d9'
                  e.target.style.color = 'rgba(0, 0, 0, 0.65)'
                }}
              >
                <Icon type='zoom-out' style={{ fontSize: 20 }} />
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 14 }}>
                <span style={{ color: '#595959' }}>{Math.round(imageScale * 100)}%</span>
              </div>
              <div
                type='default' onClick={handleZoomInImage} style={{
                  borderRadius: '4px',
                  padding: '4px 15px',
                  cursor: 'pointer',
                  backgroundColor: '#fff',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  minHeight: '32px',
                  transition: 'all 0.3s ease'
                }}
                onMouseEnter={(e) => {
                  e.target.style.borderColor = '#40a9ff'
                  e.target.style.color = '#40a9ff'
                }}
                onMouseLeave={(e) => {
                  e.target.style.borderColor = '#d9d9d9'
                  e.target.style.color = 'rgba(0, 0, 0, 0.65)'
                }}
              >
                <Icon type='zoom-in' style={{ fontSize: 20 }} />
              </div>
              <div
                type='default' onClick={handleRotateRightImage} style={{
                  borderRadius: '4px',
                  padding: '4px 15px',
                  cursor: 'pointer',
                  backgroundColor: '#fff',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  minHeight: '32px',
                  transition: 'all 0.3s ease'
                }}
                onMouseEnter={(e) => {
                  e.target.style.borderColor = '#40a9ff'
                  e.target.style.color = '#40a9ff'
                }}
                onMouseLeave={(e) => {
                  e.target.style.borderColor = '#d9d9d9'
                  e.target.style.color = 'rgba(0, 0, 0, 0.65)'
                }}
              >
                <Icon type='rollback' style={{ fontSize: 20, transform: 'scaleX(-1)' }} />
              </div>
            </div>
          </>
        ) : null}
      </Modal>

      {/* PDF Preview Modal */}
      <PDFModal
        visible={showPDFModal}
        pdfFile={pdfFile}
        numPages={numPages}
        pdfRotation={pdfRotation}
        onCancel={handleClosePDFModal}
        onDocumentLoadSuccess={handleOnDocumentLoadSuccess}
        onRotateLeft={handleRotateLeftPDF}
        onRotateRight={handleRotateRightPDF}
      />
    </Modal>
  )
}

ComparePolicyDataModal.propTypes = {
  visible: PropTypes.bool,
  onCancel: PropTypes.func,
  detailData: PropTypes.object,
  claimAttribute: PropTypes.object,
  agentPolicyDetails: PropTypes.object,
  policyDetail: PropTypes.object,
  getAgentPolicyDetails: PropTypes.func.isRequired,
  getPolicyDetails: PropTypes.func.isRequired
}

ComparePolicyDataModal.defaultProps = {
  visible: false,
  onCancel: () => {},
  detailData: null,
  claimAttribute: null,
  agentPolicyDetails: null,
  policyDetail: null
}

const mapStateToProps = (state) => ({
  agentPolicy: state.Agent.agentPolicy,
  agentPolicyDetails: state.Agent.agentPolicyDetails,
  policyDetail: state.Insurance.policyDetail,
  agentPolicyLoading: state.Loading.GET_AGENT_INSURANCE_DATA,
  policyDetailLoading: state.Loading.GET_POLICY_DETAILS
})

const mapDispatchToProps = {
  getAgentInsuranceData: agentActions.getAgentInsuranceData,
  getAgentPolicyDetails: agentActions.getAgentPolicyDetails,
  getPolicyDetails: policyActions.getPolicyDetails
}

export default connect(mapStateToProps, mapDispatchToProps)(ComparePolicyDataModal)
