import React, { Component } from 'react'
import BoxWrapper from './claimsCommentBox.style'
import ClaimCommentMessageContainer from './claimCommentMessageContainer'
import {
  Row,
  Col,
  Button,
  Modal,
  message
  // Upload,
  // Input,
} from 'antd'
// import SendButton from '../../../image/send-icn.png'
// import UploadButton from '../../../image/attach-icon.png'
import moment from 'moment-timezone'
import claimActions from '../../redux/claims/actions'
import { connect } from 'react-redux'
import errorAction from '../../../redux/error/actions'
import loadingAction from '../../../redux/loading/actions'
import UserActions from '../../redux/user/actions'

const { listcommentsticketData, uploadImage, addCommentInTickets } =
  claimActions

const { getInternalUsers } = UserActions
const { resetErrorRedux } = errorAction
const { resetLoadingRedux } = loadingAction

class ClaimCommentBox extends Component {
  constructor (props) {
    super(props)
    this.state = {
      openStatus: this.props.boxStatus,
      listcommentsData: [],
      message: '',
      showCommentEmailModalContent: '',
      showCommentEmailModal: false,
      noshowingModal: true,
      imageMessage: '',
      ticketId: this.props.ticketId,
      claimId: this.props.claimId
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      listcommentsData,
      listcommentsTicketStatus,
      url,
      addcommentStatusMessage
    } = nextProps.detailClaims

    if (url !== '' && url !== undefined) {
      this.setState({
        visible: true,
        url
      })
    }
    if (addcommentStatusMessage === 'success') {
      this.setState({
        visible: false,
        url
      })
    }
    if (
      listcommentsTicketStatus !== '' &&
      listcommentsTicketStatus === 'success'
    ) {
      this.setState({
        listcommentsData
      })
    }
  }

  componentDidMount () {
    const { ticketId, claimId, openStatus } = this.state
    if (openStatus) {
      this.showContent(ticketId, claimId)
    }
    this.props.getInternalUsers()
  }

  handleClose = () => {
    // this.props.resetRedux();
    this.setState({
      noshowingModal: false,
      visible: false,
      imageMessage: ' '
    })
  };

  async handleChangeComments (info) {
    if (info.file.status === 'done' || info.file.status === 'error') {
      // const isLt10KB = info.file.size / 1024 / 1024 < 0.01
      const isGt20MB = info.file.size / 1024 / 1024 > 20
      // if (isLt10KB) {
      //   message.error('File is to small, min 10kb')
      //   return
      // }
      if (isGt20MB) {
        message.error('File is to big, max 20mb')
        return
      }
      if (!isGt20MB) {
        // eslint-disable-line
        const file = info.file.originFileObj
        this.setState({
          filename: file.name,
          filesize: file.size,
          file,
          fileType: info.file.type
        })
        this.startUpload(file)
      } else {
        message.error('File is not supported')
      }
    }
  }

  startUpload = (file) => {
    this.setState({ loading: true, noshowingModal: true })
    const formData = new FormData()
    formData.append('file', file)
    this.props.uploadImage({ formData })
  };

  handleCommentContentOk = () => {
    this.setState({ showCommentEmailModal: false })
  };

  handleCommentContentCancel = () => {
    this.setState({ showCommentEmailModal: false })
  };

  reolvingTicket = (id) => {
    this.props.resolvingCard(id)
    setTimeout(() => {
      this.setState({
        openStatus: false
      })
    }, 4000)
  };

  showContent = (claimTicketId, claimId) => {
    this.showChat(claimTicketId, claimId)
  };

  windowChat = (claimTicketId, claimId) => {
    this.setState(
      {
        openStatus: !this.state.openStatus
      },
      () => {
        if (this.state.openStatus) {
          this.showContent(claimTicketId, claimId)
        }
      }
    )
  };

  sendingMessage = () => {
    const { message, claimId, ticketId } = this.state
    const { dataProfile } = this.props

    const data = {
      claim_id: claimId,
      content: {
        ops_user_id: dataProfile.name,
        comment: message,
        parent_comment_id: null,
        attachments: []
      }
    }
    this.props.addCommentInTickets(data)
    this.setState({
      message: ''
    })
    this.props.resetLoadingRedux(['LIST_COMMENTS_TICKET'])
    this.props.resetErrorRedux(['LIST_COMMENTS_TICKET'])

    setTimeout(() => {
      this.props.listcommentsticketData({
        claimId: claimId,
        ticketId: ticketId
      })
    }, 1000)
  };

  messageTyping = (e) => {
    this.setState({
      message: e.target.value
    })
  };

  showChat = (ticketId, claimId) => {
    this.setState(
      {
        claimId: claimId,
        ticketId: ticketId
      },
      () => {
        const data = {
          claimId: claimId,
          ticketId: ticketId
        }
        this.props.listcommentsticketData(data)
      }
    )
  };

  openEmailModal = (val) => {
    this.setState({
      showCommentEmailModal: true,
      showCommentEmailModalContent: val
    })
  };

  imageMessage = (e) => {
    this.setState({
      imageMessage: e.target.value
    })
  };

  handleOk = (url) => {
    const { fileType, imageMessage, claimId, ticketId } = this.state
    const { dataProfile } = this.props

    const data = {
      claim_id: claimId,
      content: {
        ops_user_id: dataProfile.name,
        comment: imageMessage,
        parent_comment_id: null,
        attachments: [
          {
            url: url,
            type: fileType
          }
        ]
      }
    }

    this.props.addCommentInTickets(data)

    this.props.resetLoadingRedux(['LIST_COMMENTS_TICKET'])
    this.props.resetErrorRedux(['LIST_COMMENTS_TICKET'])

    this.setState(
      {
        visible: false,
        attachments: [],
        comment: imageMessage
      },
      () => {
        setTimeout(() => {
          this.props.listcommentsticketData({
            claimId: claimId,
            ticketId: ticketId
          })
          this.setState({
            imageMessage: ' '
          })
        }, 2000)
      }
    )
  };

  render () {
    const {
      openStatus,
      showCommentEmailModal,
      showCommentEmailModalContent,
      noshowingModal,
      url
    } = this.state

    const {
      content
      // dummyRequest,
    } = this.props

    return (
      <BoxWrapper>
        <Modal
          title='Email Content'
          visible={showCommentEmailModal}
          onOk={this.handleCommentContentOk}
          onCancel={this.handleCommentContentCancel}
          width='100%'
          bodyStyle={{
            height: `${window.innerHeight * 0.75}px`
          }}
        >
          <iframe
            width='100%'
            height='100%'
            srcDoc={showCommentEmailModalContent}
            title='Email Content'
          />
        </Modal>

        <Modal
          title='Preview'
          visible={this.state.visible && noshowingModal}
          onOk={() => {
            this.handleOk(url)
          }}
          onCancel={this.handleClose}
        >
          <Row type='flex' style={{ flexDirection: 'column' }} gutter={40}>
            <Col
              span={24}
              style={{ display: 'flex', justifyContent: 'center' }}
            >
              <img
                src={url}
                alt=''
                style={{
                  maxWidth: 384,
                  width: 'auto',
                  height: 'auto',
                  maxHeight: 400
                }}
              />
            </Col>
            <Col
              span={24}
              style={{
                display: 'flex',
                justifyContent: 'space-around',
                paddingTop: 10
              }}
            >
              <span>Message</span>
              <input
                type='text'
                onChange={(e) => {
                  this.imageMessage(e)
                }}
                style={{
                  width: '80%',
                  border: '1px solid black',
                  borderRadius: 8
                }}
                value={this.state.imageMessage}
              />
            </Col>
          </Row>
        </Modal>

        <div
          style={{
            border: '1px solid #777',
            padding: '5px 10px',
            marginBottom: 10
          }}
        >
          <Row type='flex' justify='space-between' gutter={60}>
            <Col>
              Ticket Id -<b>{content.ticket_no}</b>
            </Col>
            {!openStatus
              ? (
                <>
                  <Col>
                    Status -<b>{content.status}</b>
                  </Col>
                  <Col>
                    Resolved By-<b>{content.resolved_by}</b>
                  </Col>
                  <Col>
                    Start Date-
                    <b>
                      {moment
                        .utc(content.created_at)
                        .tz(this.props.timezone)
                        .format('lll')}
                    </b>
                  </Col>
                  {content.resolved_on
                    ? (
                      <Col>
                        End Date -{' '}
                        <b>
                          {moment
                            .utc(content.resolved_on)
                            .tz(this.props.timezone)
                            .format('lll')}
                        </b>
                      </Col>
                      )
                    : null}
                </>
                )
              : null}

            <Col>
              {!openStatus
                ? (
                  <Button
                    type='primary'
                    onClick={() => {
                      this.windowChat(
                        content.claim_ticket_id,
                        content.claim_id,
                        content.status
                      )
                    }}
                  >
                    Show Chat
                  </Button>
                  )
                : (
                  <>
                    {content.status !== 'Resolved'
                      ? (
                        <Row type='flex' gutter={20}>
                          <Col>
                            <Button
                              type='primary'
                              onClick={() => {
                                this.reolvingTicket(content.claim_ticket_id)
                              }}
                            >
                              Mark as Resolved
                            </Button>
                          </Col>
                          <Col>
                            <Button
                              type='primary'
                              onClick={() => this.setState({ openStatus: false })}
                            >
                              Close Chat
                            </Button>
                          </Col>
                        </Row>
                        )
                      : (
                        <Button
                          type='primary'
                          onClick={() => this.setState({ openStatus: false })}
                        >
                          Close Chat
                        </Button>
                        )}
                  </>
                  )}
            </Col>
          </Row>

          {openStatus
            ? (
              <Row>
                <Col span={24}>
                  <div className='chat-box-wrapper'>
                    <ClaimCommentMessageContainer
                      timezone={this.props.timezone}
                      openEmailModal={this.openEmailModal}
                      ticketId={this.state.ticketId}
                      claimId={this.state.claimId}
                    />
                  </div>
                </Col>
              </Row>
              )
            : null}
        </div>
      </BoxWrapper>
    )
  }
}

export default connect(
  (state) => ({
    dataProfile: state.Auth.profile,
    detailClaims: state.Claims,
    internalUsers: state.User.internalUsers,
    internalUsersLoading: state.Loading.GET_INTERNAL_USERS,
    internalUsersError: state.Error.GET_INTERNAL_USERS
  }),
  {
    listcommentsticketData,
    addCommentInTickets,
    uploadImage,
    resetLoadingRedux,
    resetErrorRedux,
    getInternalUsers
  }
)(ClaimCommentBox)
