import React, { Component } from 'react'
import { connect } from 'react-redux'
import { get } from 'lodash'
import { Button, Form, Row, Input } from 'antd'

import claimActions from '../../../redux/claims/actions'

const FormItem = Form.Item
const { TextArea } = Input

const { softDeleteClaim } = claimActions

class DeleteReason extends Component {
  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((error, values) => {
      if (!error) {
        const { detailData } = this.props
        const claimID = get(detailData, 'claim_id')
        this.props.softDeleteClaim({
          query: {
            ...values,
            claim_id: claimID
          }
        })
      }
    })
  }

  render () {
    const { form } = this.props
    const { getFieldDecorator } = form

    return (
      <>
        <Form onSubmit={this.handleSubmit}>
          <FormItem>
            {
              getFieldDecorator('delete_reason',
                {
                  rules: [
                    {
                      required: true,
                      message: 'Delete Reason tidak boleh kosong'
                    }
                  ]
                }
              )(<TextArea placeholder='Enter reason for deleting this claim' />
              )
            }
          </FormItem>
          <Row
            type='flex'
            justify='end'
          >
            <Button
              htmlType='submit'
              type='primary'
            >
              Delete
            </Button>
          </Row>
        </Form>
      </>
    )
  }
}

const DeleteReasonWarpper = Form.create()(DeleteReason)

export default connect(state => ({
}), {
  softDeleteClaim
})(DeleteReasonWarpper)
