import { Card, Col, Row, Spin } from 'antd'
import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { connect } from 'react-redux'
import { Link } from 'react-router-dom'
import claimActions from '../../../../redux/claims/actions'
import { currencyChange } from '../../../ASOWallet/constant'
import { ActionButton, PageButton, PaginationContainer, StyledTable, TableCell, TableContainer, TableHeader, TableRow } from './styles'

const { getClaimLists, resetReduxStateClaim, getTotalClaimsAmount } = claimActions

const ClaimListHistory = React.memo(({
  data,
  totalClaimsAmount,
  getTotalClaimsAmount,
  getClaimLists,
  getClaimListsStatus,
  applicationNo,
  resetReduxStateClaim,
  claimDetail,
  handleClaimNumberClick
}) => {
  const [historyClaimData, setHistoryClaimData] = useState(null)
  const [historyClaimMetaData, setHistoryClaimMetaData] = useState(null)
  const [claimListLoading, setClaimListLoading] = useState(false)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize, setPageSize] = useState(10)
  const [numPage, setNumPage] = useState(1)


  const totalSumInsured =
    claimDetail?.object_insured_images?.total_sum_insured ?? 0
  const claimRemainingAmount = totalClaimsAmount ? (totalSumInsured - totalClaimsAmount) : totalSumInsured

  const dataHistoryClaims = useMemo(() => {
    const source = historyClaimData || []
    return source.map((val, index) => ({
      key: index,
      claim_no: val.claim_no,
      benefit: val.benefit,
      claim_amount: val.claim_amount,
      created_at: val.created_at,
      status: val.status,
      claim_id: val.claim_id
    }))
  }, [historyClaimData])

  const onHandleNavClaim = useCallback((claimId) => {
    handleClaimNumberClick(claimId)
    window.scrollTo({
         top: 0,
         behavior: 'smooth'
       });

  }, [handleClaimNumberClick])

  useEffect(() => {
    if (getClaimListsStatus === 'success' && data) {
      setHistoryClaimData(data.data)
      setHistoryClaimMetaData(data.meta_data)
    }
  }, [getClaimListsStatus, data, applicationNo])

  useEffect(() => {
    if (applicationNo) {
      getClaimLists({ application_no: applicationNo,page: currentPage, page_size: pageSize })
    }
    return () => {
      resetReduxStateClaim(['getClaimListsStatus'])
    }
  }, [applicationNo, resetReduxStateClaim])

  // fetch total API amount when available
  useEffect(() => {
    if (applicationNo) {
      getTotalClaimsAmount({ application_no: applicationNo, status: 'settled' })
    }
  }, [applicationNo,getTotalClaimsAmount])


  useEffect(() => {
    if (historyClaimData && historyClaimMetaData) {
      setClaimListLoading(false)
      setCurrentPage(historyClaimMetaData.page)
      setPageSize(historyClaimMetaData.page_size)
      setNumPage(historyClaimMetaData.num_page)
    }
  }, [historyClaimData, historyClaimMetaData])
  const handlePaginationChange = useCallback((page) => {
    setClaimListLoading(true)
    setCurrentPage(page)
    if (applicationNo) {
      getClaimLists({ application_no: applicationNo, page: page, page_size: pageSize })
    }
  }, [applicationNo, getClaimLists, pageSize])

  return dataHistoryClaims?.length
    ? (
      <TableContainer>
      <Card title='Claim History'>
        <div className='section-block'>
          <Row gutter={16}>
            <Col span={12} className='item-container'>
              <div className='header'>Total claims</div>
                <div className='value'>{ historyClaimMetaData?.total_records || 0}</div>
            </Col>
            <Col span={12} className='item-container'>
              <div className='header'>Total Sum Insured</div>
              <div className='value'>{`Rp ${currencyChange(totalSumInsured)}`}</div>
            </Col>
          </Row>
          </div>
          <div className='section-block'>
            <Row gutter={16}>
              <Col span={12} className='item-container'>
                <div className='header'>Claim Remaining Amount</div>
                <div className='value'>{`Rp ${claimRemainingAmount ? currencyChange(claimRemainingAmount) : '-'}`}</div>
              </Col>
              <Col span={12} className='item-container'>
                <div className='header'>Total Claim Amount</div>
                <div className='value'>{`Rp ${currencyChange(totalClaimsAmount)}`}</div>
              </Col>
            </Row>
          </div>
        {claimListLoading
          ? (
            <Spin style={{ display: 'block', margin: '10px auto' }} />
            )
          : (
            <>
              <StyledTable>
                <thead>
                  <TableRow>
                    <TableHeader>Claim No</TableHeader>
                    <TableHeader>Benefit</TableHeader>
                    <TableHeader>Created At</TableHeader>
                    <TableHeader>Status</TableHeader>
                    <TableHeader>Claim Amount</TableHeader>
                    <TableHeader>Action</TableHeader>
                  </TableRow>
                </thead>
                <tbody>
                  {dataHistoryClaims.map((val, index) => (
                    <TableRow key={index}>
                      <TableCell>{val.claim_no}</TableCell>
                      <TableCell>{val.benefit}</TableCell>
                      <TableCell>{val.created_at}</TableCell>
                      <TableCell>{val.status}</TableCell>
                      <TableCell>{`Rp ${val.claim_amount ? currencyChange(val.claim_amount) : '-'}`}</TableCell>
                      <TableCell align='center'>
                        <Link to={`/claims/${val.claim_id}`} onClick={() => onHandleNavClaim(val.claim_id)}>
                          <ActionButton>Detail</ActionButton>
                        </Link>
                      </TableCell>
                    </TableRow>
                  ))}
                </tbody>
              </StyledTable>

              <PaginationContainer>
                <PageButton disabled={currentPage === 1} onClick={() => handlePaginationChange(currentPage - 1)}>Prev</PageButton>
                <span>Page {currentPage} of {numPage}</span>
                <PageButton disabled={currentPage === numPage} onClick={() => handlePaginationChange(currentPage + 1)}>Next</PageButton>
              </PaginationContainer>
            </>
            )}
        </Card>
      </TableContainer>
      )
    : null
})


export default connect(
  (state) => ({
    data: state.Claims.data,
    getClaimListsStatus: state.Claims.getClaimListsStatus,
    claimListsError: state.Error.GET_CLAIM_LISTS,
    claimListsMessage: state.Claims.getClaimListsMessage,
    totalClaimsAmount: state.Claims.totalClaimsAmount,
    totalClaimsAmountStatus: state.Claims.totalClaimsAmountStatus
  }),
  {
    getClaimLists,
    resetReduxStateClaim,
    getTotalClaimsAmount
  }
)(ClaimListHistory)
