import { Card, Col, Row } from 'antd'
import moment from 'moment'
import { useEffect, useMemo } from 'react'
import { connect } from 'react-redux'
import agentAction from '../../../redux/agent/actions'
import { PolicyInformationStyles } from './PolicyInformation.styles'

const formatValue = (v) => (v === undefined || v === null ? '-' : v)
const displayDate = (d) => {
  if (!d) return '-'
  const parsed = moment(d)
  return parsed.isValid() ? parsed.format('DD-MM-YYYY') : d
}


const { getAgentInsuranceData } = agentAction;

const PolicyInformation = ({
  data = {},
  loading = false,
  claimDetail,
  getAgentInsuranceData,
  agentInsuranceData,
}) => {
  const objectInsured = claimDetail?.object_insured_images;
  const dateOfLoss = claimDetail?.forms
    ?.find((form) => form?.title === "Formulir Klaim")
    ?.attributes?.find((attr) => attr?.name === "date_of_accident")?.value;

  const plateByPolicy = useMemo(() => {
    if (objectInsured?.plate_number && objectInsured?.back_plate) {
      return `${objectInsured?.region_code} ${objectInsured?.plate_number} ${objectInsured?.back_plate}`
    }
    if (objectInsured?.vehicle_plate_no) {
      return `${objectInsured?.region_code} ${objectInsured?.vehicle_plate_no}`
    }
    return 'N/A'
  }, [objectInsured])

  const businessInfo = data.businessInformation || {};
  const policyItems = [
    {
      label: "Insurance Period",
      value: `${displayDate(objectInsured?.start_date)} to ${displayDate(objectInsured?.end_date)}`,
    },
    {
      label: "Date of Loss",
      value: displayDate(dateOfLoss),
    },
  ];
  const businessItems = [
    { label: "Source of Business", value: businessInfo.sourceOfBusiness },
    { label: "Agent Name", value: claimDetail?.agent_user_name },
    {
      label: "Marketing",
      value: agentInsuranceData?.agent?.pic_marketing?.marketing_pic,
    },
  ];
  const vehicleItems = [
    { label: "Brand", value: objectInsured?.brand },
    { label: "Model", value: objectInsured?.model },
    { label: "Variant", value: objectInsured?.variant },
    { label: "Chasis Number", value: objectInsured?.chasis_number },
    { label: "Machine Number", value: objectInsured?.machine_number },
    {
      label: "Vehicle Plate Number",
      value: plateByPolicy,
    },
    { label: "Color", value: objectInsured?.color },
    // { label: 'Vehicle Type', value: vehicleInfo.vehicleType },
    { label: "Year", value: objectInsured?.year },
    { label: "Transmission", value: objectInsured?.transmission_type },
  ];

  useEffect(() => {
    if (claimDetail?.policy_ref_number) {
      getAgentInsuranceData({ policyId: claimDetail?.policy_ref_number });
    }
  }, [claimDetail?.policy_ref_number]);

  return (
    <PolicyInformationStyles>
      <Card loading={loading} className="card-container" bordered>
        <div className="section-block">
          <div className="section-title">Policy Information</div>
          <Row gutter={[0, 16]}>
            {policyItems.map((it, idx) => (
              <Col key={idx} span={12} className="item-container">
                <div className="header">{it.label}</div>
                <div className="value">{formatValue(it.value)}</div>
              </Col>
            ))}
          </Row>
        </div>
        <hr className="section-sep" />
        <div className="section-block">
          <div className="section-title">Business Information</div>
          <Row gutter={[0, 16]}>
            {businessItems.map((it, idx) => (
              <Col key={idx} span={12} className="item-container">
                <div className="header">{it.label}</div>
                <div className="value">{formatValue(it.value)}</div>
              </Col>
            ))}
          </Row>
        </div>
        <hr className="section-sep" />
        <div className="section-block">
          <div className="section-title">Vehicle Information</div>
          <Row gutter={[0, 16]}>
            {vehicleItems.map((it, idx) => (
              <Col key={idx} span={12} className="item-container">
                <div className="header">{it.label}</div>
                <div className="value">{formatValue(it.value)}</div>
              </Col>
            ))}
          </Row>
        </div>
      </Card>
    </PolicyInformationStyles>
  );
};

export default connect(
  (state) => {
    return {
      agentInsuranceData: state.Agent.agentPolicy,
    };
  },
  {
    getAgentInsuranceData,
  },
)(PolicyInformation);
