import moment from 'moment'

export function normalizeToUtcMidnight (isoString) {
  const date = new Date(isoString)

  const year = date.getFullYear()
  const month = date.getMonth()
  const day = date.getDate()

  const utcMidnight = new Date(Date.UTC(year, month, day))
  return utcMidnight.toISOString()
}
// date string 26-06-2030
export function isNotExpired (dateString) {
  if (!dateString) return false
  return moment(dateString, 'DD-MM-YYYY').toDate() > new Date()
}
