import { Component } from 'react'
import {
  Form,
  Input, InputNumber,
  message, Select, Tooltip
} from 'antd'

import validator from '../../../helpers/validator'
import {
  ApproveButton, AutoApprovalWrapper, BenefitContainer,
  ButtonContainer, ChangeStatus, InfoContainer, RejectButton
} from './multiBenefitAutoApproval.style'
import UploadImg from './UploadImg'


const { Option } = Select
const FormItem = Form.Item
const { TextArea } = Input

class MultiBenefitAutoApprovalEvent extends Component {

  constructor(props) {
    super(props)
    this.state = {
      openCommentBox: false,
      openCommentBoxText: '',
      uploadLoader: false,
    }
  }

  handleChangeSelect = (value) => {
    if (value === 'other') {
      this.setState({ openCommentBox: true })
    } else {
      const { openCommentBox } = this.state
      if (openCommentBox) {
        this.setState({ openCommentBox: false })
      }
    }
  }

  imageCancelClickHandler = (name) => {
    const { updateMultiBenefitAutoApproval, multiBenefitAutoApprovalPayload, benefit } = this.props
    let payload = {
      ...multiBenefitAutoApprovalPayload[benefit],
      [name]: undefined
    }

    updateMultiBenefitAutoApproval(benefit, payload)
  }

  renderInputType = (attribute = {}) => {
    const {
      type,
      options,
      name,
      value
    } = attribute
    switch (type) {
      case 'choices':
        return (
          <Select disabled={options?.length === 1} className='remarks-select' onSelect={this.handleChangeSelect}>
            {
              options.map((val, index) => (
                <Option
                  key={index}
                  value={val[0]}
                  className='select-option'
                >
                  <Tooltip placement='top' title={val[1]}>
                    <div>{val[1]}</div>
                  </Tooltip>
                </Option>
              ))
            }
          </Select>
        )
      case 'image':
        return value ?
          <div>
            <img src={value} alt="auto_approval_image" style={{
              width: 100,
              height: 100,
            }} />
            <div onClick={() => this.imageCancelClickHandler(name)}>Change</div>
          </div>
          : (
            <UploadImg
              attribute={attribute}
              state={this.state}
              setState={this.setState}
              form={this.props.form}
            />
          )
      case 'text':
        if (name === 'amount') {
          return (
            <InputNumber
              formatter={value => `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
              parser={value => value.replace(/\$\s?|(,*)/g, '')}
              className='input-number'
            />
          )
        } else {
          return <Input />
        }

      default:
        return <TextArea />
    }
  }

  approveOrRejectClickHandler = async (e, isApproved) => {
    e.preventDefault()
    const { form, updateMultiBenefitAutoApproval, benefit } = this.props
    const { openCommentBox } = this.state

    const valid = await form.validateFields()
    if (!valid) {
      return
    }
    const payload = form.getFieldsValue()

    if (openCommentBox) {
      const comments = document.getElementById('commentBox').value
      if (comments !== '') { payload.remarks = comments } else {
        message.error('comments are required')
        this.setState({ submitEventLoader: false })
        return
      }
    }
    payload.is_approved = isApproved
    updateMultiBenefitAutoApproval(benefit, payload)
  }

  changeStatusClickHandler = () => {
    const { updateMultiBenefitAutoApproval, multiBenefitAutoApprovalPayload, benefit } = this.props
    const payload = {
      ...multiBenefitAutoApprovalPayload[benefit],
      is_approved: undefined
    }
    updateMultiBenefitAutoApproval(benefit, payload)
  }

  componentDidUpdate(prevprops) {

    const { multiBenefitAutoApprovalPayload: prevMultiBenefitAutoApprovalPayload } = prevprops
    const { multiBenefitAutoApprovalPayload, benefit, form_data: formAttributes = [] } = this.props

    if (multiBenefitAutoApprovalPayload[benefit] !== prevMultiBenefitAutoApprovalPayload[benefit]) {
      formAttributes.forEach((attribute) => {
        const { name, type, options } = attribute
        let { value } = attribute
        if (multiBenefitAutoApprovalPayload.hasOwnProperty(benefit)) {
          value = multiBenefitAutoApprovalPayload[benefit][name]
        }
        let otherFlag = true
        let openCommentBoxText = ''
        if (type === 'choices' && value) {
          otherFlag = options.every(([optionValue]) => optionValue !== value)
          if (otherFlag) {
            openCommentBoxText = value
            value = 'other'
            attribute.value = 'other'
          }
          this.setState({ openCommentBoxText, openCommentBox: true })
        }
      })

    }
  }


  render() {
    const {
      data, form, selectedBenefit,
      changeBenefitSelected, benefit,
      multiBenefitAutoApprovalPayload = {} } = this.props
    const { is_auto_approved: isAutoApproved = false, form_data: formAttributes = [] } = data
    const { getFieldDecorator } = form
    const { openCommentBox } = this.state

    const { remarks = '', amount = '', images = '' } = multiBenefitAutoApprovalPayload[benefit] || {}

    let autoApprovedAmount = null
    formAttributes.forEach(element => {
      const { value, name } = element
      if (name === 'amount' && value) {
        autoApprovedAmount = value
      }
    });

    return (
      <Form>
        <BenefitContainer isAutoApproved={isAutoApproved} onClick={() => changeBenefitSelected(data.benefit_id)}>
          {data.name}
        </BenefitContainer>
        {selectedBenefit && selectedBenefit.includes(data.benefit_id) ?
          isAutoApproved
            ?
            <AutoApprovalWrapper>
              <div>The claim has been approved by JARVIS</div>
              <InfoContainer>
                <div>Claim Amount:</div>
                <div>{autoApprovedAmount}</div>
              </InfoContainer>
            </AutoApprovalWrapper>
            :
            <>
              {
                multiBenefitAutoApprovalPayload.hasOwnProperty(benefit) &&
                  multiBenefitAutoApprovalPayload[benefit].is_approved !== undefined
                  ?
                  <div>
                    {remarks ? <InfoContainer><div>Remarks:</div> <div>{remarks}</div></InfoContainer> : null}
                    {images ? <InfoContainer>
                      <div>
                        Images:
                      </div>
                      <div>
                        <img src={images} alt="auto_approval_image" style={{
                          width: 100,
                          height: 100,
                        }} />
                      </div>
                    </InfoContainer> : null}
                    {amount ? <InfoContainer>
                      <div> Amount: </div>
                      <div> {amount}</div>
                    </InfoContainer> : null}
                  </div>
                  :
                  formAttributes.map((attribute) => {
                    const { name, required, regex, type, label, options } = attribute
                    let { value } = attribute
                    if (multiBenefitAutoApprovalPayload.hasOwnProperty(benefit)) {
                      value = multiBenefitAutoApprovalPayload[benefit][name]
                    }
                    let otherFlag = true
                    let openCommentBoxText = ''
                    if (type === 'choices' && value) {
                      otherFlag = options.every(([optionValue]) => optionValue !== value)
                      if (otherFlag) {
                        openCommentBoxText = value
                        value = 'other'
                        attribute.value = 'other'
                      }
                    }
                    return (
                      <FormItem label={label}>
                        {
                          getFieldDecorator(name, {
                            rules: [
                              {
                                required: required,
                                message: required
                                  ? `${name.replace(/'_'/g, ' ')} can not be empty`
                                  : ''
                              }, {
                                validator: validator.checkValidator !== undefined && validator.checkValidator,
                                regex: regex
                              }
                            ],
                            initialValue: type === 'choices' && options?.length === 1 ? options[0][0] : value
                          })(this.renderInputType(attribute))
                        }
                        {(openCommentBox) && type === 'choices' && (<TextArea id='commentBox' defaultValue={openCommentBoxText} />)}
                      </FormItem>)
                  })
              }
              {
                multiBenefitAutoApprovalPayload.hasOwnProperty(benefit) &&
                  multiBenefitAutoApprovalPayload[benefit].is_approved !== undefined
                  ?
                  (
                    <div>
                      <div>Status: {multiBenefitAutoApprovalPayload[benefit].is_approved === true ? 'Approved' : 'Rejected'}</div>
                      <ChangeStatus onClick={this.changeStatusClickHandler}>Change status</ChangeStatus>
                    </div>

                  )
                  :
                  <ButtonContainer>
                    <ApproveButton onClick={(e) => this.approveOrRejectClickHandler(e, true)}>
                      Approve
                    </ApproveButton>
                    <RejectButton onClick={(e) => this.approveOrRejectClickHandler(e, false)}>Reject</RejectButton>
                  </ButtonContainer>
              }
            </>
          : null
        }
      </Form>)
  }
}

export default Form.create()(MultiBenefitAutoApprovalEvent)
