import { Table, Tag, Icon, Collapse } from 'antd'

const DataComparisonTable = ({ title = 'Verification', rows = [] }) => {

  const getStatus = (isMatch) => {
    if (isMatch === true) {
      return {
        label: 'Match',
        icon: 'check-circle',
        color: 'green',
        bgColor: 'rgba(82, 196, 26, 0.15)',
        rowBgColor: 'rgba(82, 196, 26, 0.1)'
      }
    }

    if (isMatch === false) {
      return {
        label: 'Not Match',
        icon: 'close-circle',
        color: 'red',
        bgColor: 'rgba(245, 34, 45, 0.15)',
        rowBgColor: 'rgba(245, 34, 45, 0.1)'
      }
    }

    return {
      label: '',
      icon: 'exclamation-circle',
      color: 'orange',
      bgColor: 'rgba(250, 173, 20, 0.15)',
      rowBgColor: 'rgba(250, 173, 20, 0.1)'
    }
  }

  const columns = [
    {
      title: 'Data',
      dataIndex: 'label',
      key: 'label',
      render: (text) => <span style={{ fontWeight: 500 }}>{text}</span>
    },
    {
      title: 'OCR Claim',
      dataIndex: 'ocrValue',
      key: 'ocrValue',
      render: (text) => text || '-'
    },
    {
      title: 'Data Policy',
      dataIndex: 'policyValue',
      key: 'policyValue',
      render: (text) => text || '-'
    },
    {
      title: 'Status',
      key: 'status',
      align: 'right',
      render: (_, record) => {
        const status = getStatus(record.isMatch)
        return (
          <Tag
            color={status.color}
            style={{
              borderRadius: 12,
              padding: '2px 12px'
            }}
          >
            <Icon type={status.icon} style={{ marginRight: 4 }} />
            {status.label}
          </Tag>
        )
      }
    }
  ]



  return (
    <Collapse defaultActiveKey={['1']}>
      <Collapse.Panel key='1' header={title}>
        <Table
          columns={columns}
          dataSource={rows}
          rowKey='label'
          pagination={false}
          size='middle'
          bordered
          onRow={(record, index) => ({
            style: { backgroundColor: getStatus(record.isMatch).rowBgColor }
          })}
        />
      </Collapse.Panel>
    </Collapse>
  )
}

export default DataComparisonTable
