import EditableServiceCenterForm from './editableServiceCenterForm'
import ViewServiceCenterForm from './ViewServiceCenterForm'

export default function ServiceCenterForm ({
  thisInstance,
  formData,
  form,
  submitForm,
  getInitValue,
  confirmReject,
  permissions,
  disableEventButtons
}) {
  const { attributes, is_valid: isValid, name: formName } = formData

  return (
    isValid
      ? <ViewServiceCenterForm
          thisInstance={thisInstance}
          formName={formName}
          attributes={attributes}
          permissions={permissions}
          confirmReject={confirmReject}
          disableEventButtons={disableEventButtons}
          formData={formData}
          form={form}
          submitForm={submitForm}
        />
      : <EditableServiceCenterForm
          formData={formData}
          form={form}
          submitForm={submitForm}
          getInitValue={getInitValue}
          confirmReject={confirmReject}
          permissions={permissions}
        />)
}
