import { Fragment, useEffect } from 'react'
import { connect } from 'react-redux'
import { useParams } from 'react-router'
import { Form, Select, Row, Col, Button, Tag } from 'antd'
import PermissionChecker from '../../../../components/permissionChecker'

import claimActions from '../../../redux/claims/actions'

const {
  getBengkelnetProvinceList,
  getBengkelnetCityList,
  getBengkelnetWorkshopList,
  resetReduxStateClaim
} = claimActions

const { Option } = Select
const FormItem = Form.Item

const provinceConst = 'sc_province'
const cityConst = 'sc_city'
const workshopConst = 'sc_workshop'

function AddressForm ({
  form,
  submitForm,
  formData = {},
  confirmReject,
  permissions = [],
  provinceList = [],
  cityList = [],
  workshopList = [],
  provinceLoader,
  cityLoader,
  workshopLoader,
  getBengkelnetProvinceList,
  getBengkelnetCityList,
  getBengkelnetWorkshopList,
  resetReduxStateClaim
}) {
  const params = useParams()
  const claimId = params.id

  const { getFieldDecorator } = form
  const { attributes = [] } = formData

  useEffect(() => {
    const payload = form.getFieldsValue()

    for (const key in payload) {
      if (payload[key] === null) {
        delete payload[key]
      } else {
        const keyName = key.split('---')[0]
        payload[keyName] = payload[key]
        delete payload[key]
      }
    }

    getBengkelnetProvinceList()

    if (payload[provinceConst]) {
      getBengkelnetCityList({
        province_id: payload[provinceConst],
      })
    }

    if (payload[provinceConst] && payload[cityConst]) {
      getBengkelnetWorkshopList({
        province_id: payload[provinceConst],
        city_id: payload[cityConst],
        claim_id: claimId
      })
    }
  },
// eslint-disable-next-line
[claimId, form.getFieldsValue, getBengkelnetProvinceList, getBengkelnetCityList, getBengkelnetWorkshopList])

  const getOptions = (name) => {
    switch (name) {
      case provinceConst:
        return provinceList
      case cityConst:
        return cityList
      case workshopConst:
        return workshopList
      default:
        return []
    }
  }

  const changeHandler = (value, name) => {
    const payload = { ...form.getFieldsValue() }
    for (const key in payload) {
      if (payload[key] === null) {
        delete payload[key]
      } else {
        const keyName = key.split('---')[0]
        payload[keyName] = payload[key]
        delete payload[key]
      }
    }

    switch (name) {
      case provinceConst:
        getBengkelnetCityList({
          province_id: value,
        })

        resetReduxStateClaim([
          'bengkelnetCityList',
          'bengkelnetWorkshopList'
        ])
        form.resetFields([
          `${cityConst}---${formData.name}`,
          `${workshopConst}---${formData.name}`
        ])
        return

      case cityConst:
        getBengkelnetWorkshopList({
          province_id: payload[provinceConst],
          city_id: value,
          claim_id: claimId
        })

        resetReduxStateClaim([
          'bengkelnetWorkshopList'
        ])
        form.resetFields([
          `${workshopConst}---${formData.name}`
        ])
        break

      default:
    }
  }

  const getLoadingState = (name) => {
    if (name === provinceConst) return provinceLoader
    if (name === cityConst) return cityLoader
    if (name === workshopConst) return workshopLoader
    return false
  }

  const renderInputType = (form, attribute, initValue) => {
    const { name } = attribute
    const loading = getLoadingState(name)
    const options = getOptions(name)

    return (
      <Select
        key={name}
        showSearch
        placeholder='Select...'
        style={{
          width: '100%'
        }}
        onChange={(value) => changeHandler(value, name)}
        filterOption={(input, option) => {
          const search = option?.props?.children

          if (!search) return true

          return (String(search)?.toLowerCase()
            ?.indexOf(input?.toLowerCase()) >= 0)
        }}
        getPopupContainer={() => document.getElementById('area')}
        loading={loading}
      >
        {Array.isArray(options)
          ? options.map(({ value, displayName }) => (
            <Option key={value} value={value}>
              {displayName}
            </Option>
            ))
          : null}
      </Select>
    )
  }

  const fieldsName = attributes.map(({ name }) => name)
  const identifier = formData.name
  const decoratedFieldNames = fieldsName.map(f => `${f}---${formData.name}`)

  const handleSubmit = () => {
    form.validateFields(decoratedFieldNames, (err) => {
      if (err) return

      const values = form.getFieldsValue()
      const nameSuffix = `---${formData.name}`
      const displayValues = {}

      const findDisplayName = (list, id) => {
        const match = list.find(item => String(item.value) === String(id))
        return match ? match.displayName : undefined
      }

      const provinceVal = values[`${provinceConst}${nameSuffix}`]
      if (provinceVal) {
        const displayName = findDisplayName(provinceList, provinceVal)
        if (displayName) displayValues[`${provinceConst}_display_value${nameSuffix}`] = displayName
      }

      const cityVal = values[`${cityConst}${nameSuffix}`]
      if (cityVal) {
        const displayName = findDisplayName(cityList, cityVal)
        if (displayName) displayValues[`${cityConst}_display_value${nameSuffix}`] = displayName
      }

      const workshopVal = values[`${workshopConst}${nameSuffix}`]
      if (workshopVal) {
        const displayName = findDisplayName(workshopList, workshopVal)
        if (displayName) displayValues[`${workshopConst}_display_value${nameSuffix}`] = displayName
      }

      if (Object.keys(displayValues).length > 0) {
        form.setFieldsValue(displayValues)
      }

      submitForm(identifier, fieldsName, formData.name, formData)
    })
  }

  return (
    <>
      {attributes.map((attribute, index) => {
        const { is_hidden: isHidden } = attribute
        const initValue = attribute.id || (attribute.value || undefined)
        return (
          <Fragment key={index}>
            <Row key={index} className={isHidden && 'hidden'}>
              <Col sm={24} md={7} style={{ marginTop: '5px' }}>
                <>
                  <div>
                    {attribute.required && (
                      <span
                        style={{
                          color: 'red'
                        }}
                      >
                        *
                      </span>
                    )}
                    &nbsp;
                    <label>
                      <strong>{attribute.label}</strong>
                    </label>
                  </div>
                  <div>
                    {attribute.status === 'invalid' && (
                      <Tag
                        color='red'
                        style={{
                          whiteSpace: 'unset',
                          height: 'auto'
                        }}
                      >
                        Rejected
                      </Tag>
                    )}
                  </div>
                </>
              </Col>
              <Col xs={24} sm={24} md={11} lg={11}>
                <FormItem>
                  {getFieldDecorator(
                    `${attribute.name}---${formData.name}`,
                    {
                      rules: [
                        {
                          required: attribute.required,
                          message: attribute.required
                            ? `${attribute.label} tidak boleh kosong`
                            : ''
                        }
                      ],
                      initialValue: initValue
                    }
                  )(renderInputType(formData, attribute, initValue))}
                </FormItem>
                <FormItem style={{ display: 'none' }}>
                  {getFieldDecorator(`${attribute.name}_display_value---${formData.name}`)(
                    <input type='hidden' />
                  )}
                </FormItem>
              </Col>

              <Col xs={24} sm={24} md={6} lg={6}>
                {!!attribute.events &&
                  attribute.events.map((d, index) => {
                    return (
                      <PermissionChecker
                        key={index}
                        permissionSetter='ops.document_approve'
                        permissionGetter={permissions}
                      >
                        <Button
                          key={index}
                          type={d.display_name === 'Accept' ? 'primary' : 'error'}
                          onClick={() =>
                            confirmReject(d, attribute.name, formData.name)}
                          style={{
                            width: ['Accept', 'Reject'].includes(d.display_name)
                              ? 80
                              : 170
                          }}
                          disabled={attribute.status !== 'pending'}
                        >
                          {d.display_name}
                        </Button>
                      </PermissionChecker>
                    )
                  })}
              </Col>
            </Row>
          </Fragment>
        )
      })}
      <PermissionChecker
        permissionGetter={permissions}
        permissionSetter='ops.save_uploaded_document'
      >
        <FormItem>
          <Button
            style={{ float: 'right' }}
            type='primary'
            className='button'
            htmlType='submit'
            onClick={handleSubmit}
            disabled={form.is_valid}
          >
            Save
          </Button>
        </FormItem>
      </PermissionChecker>
    </>
  )
}

const WorkshopSelectionForm = connect((state) => ({
  provinceList: state.Claims.bengkelnetProvinceList,
  cityList: state.Claims.bengkelnetCityList,
  workshopList: state.Claims.bengkelnetWorkshopList,

  provinceLoader: state.Loading.GET_BENGKELNET_PROVINCE_LIST,
  cityLoader: state.Loading.GET_BENGKELNET_CITY_LIST,
  workshopLoader: state.Loading.GET_BENGKELNET_WORKSHOP_LIST
}), {
  getBengkelnetProvinceList,
  getBengkelnetCityList,
  getBengkelnetWorkshopList,
  resetReduxStateClaim
})(AddressForm)

export default WorkshopSelectionForm
