import { useMemo } from 'react'
import { isNotExpired } from '../../../../../../helpers/formatDate'
import CarIncidentDescription from "../CarIncidentDesc"
import DataComparisonTable from "../DataComparisonTable"
import DataValidationTable from "../DataValidationTable"

const TITLE_FORM = 'Formulir Klaim'
export const InformationOCRFormAUS = (props) => {
  const { form, attribute, ocrData, policy } = props
  const ocrList = useMemo(() => ocrData?.ocr_data || [], [ocrData])
  const plateByPolicy = useMemo(() => {
    if (policy?.plate_number && policy?.back_plate) {
      return `${policy?.region_code} ${policy?.plate_number} ${policy?.back_plate}`
    }
    if (policy?.vehicle_plate_no) {
      return `${policy?.region_code} ${policy?.vehicle_plate_no}`
    }
    return 'N/A'
  }, [policy])
  const stnkData = useMemo(() => {
    if (!ocrList.length || !policy) return []
    const stnkOcr = ocrList.find(item => item.category === 'STNK')
    const fields = stnkOcr?.fields || {}
    return [
      {
        label: "License plate",
        ocrValue: fields.license_plate || '-',
        policyValue: plateByPolicy || '-',
        isMatch: fields.license_plate?.replace(/\s/g, '')?.toUpperCase() === plateByPolicy?.replace(/\s/g, '')?.toUpperCase()
      },
      {
        label: "Brand",
        ocrValue: fields.brand || '-',
        policyValue: policy.brand || '-',
        isMatch: fields.brand === policy.brand
      },
      {
        label: "Machine number",
        ocrValue: fields.machine_number || '-',
        policyValue: policy.machine_number || '-',
        isMatch: fields.machine_number === policy.machine_number
      },
      {
        label: "Color",
        ocrValue: fields.color || '-',
        policyValue: policy.color || '-',
        isMatch: fields.color === policy.color
      },
      {
        label: "Year",
        ocrValue: fields.year?.toString() || '-',
        policyValue: policy.year?.toString() || '-',
        isMatch: fields.year?.toString() === policy.year?.toString()
      },
      {
        label: "Chassis number (VIN)",
        ocrValue: fields.chassis_number || '-',
        policyValue: policy.chasis_number || '-',
        isMatch: fields.chassis_number === policy.chasis_number
      },
      {
        label: "Is the STNK original (not tampered or altered)?",
        ocrValue: !fields?.is_tampered ? "Original / Not modified" : "Tampered / Modified",
        policyValue: '-',
        isMatch: !fields.is_tampered
      }
    ]
  }, [ocrList, plateByPolicy, policy])

  const simData = useMemo(() => {
    if (!ocrList.length) return []
    const simOcr = ocrList.find(item => item.category === 'Driving Licence')
    const fields = simOcr?.fields || {}

    return [
      {
        label: "Is the driver's license still valid?",
        value: fields.valid_till || '-',
        isMatch: isNotExpired(fields.valid_till)
      },
      {
        label: "Is the license original (not tampered or altered)?",
        value: !fields.is_tampered ? "Original / Not modified" : "Tampered / Modified",
        isMatch: !fields.is_tampered
      },
      {
        label: "Is the license type A?",
        value: fields.sim_type || '-',
        isMatch: fields.sim_type === 'A'
      }
    ]
  }, [ocrList])

  const { damages: carDamageData } = useMemo(() => {
    if (!ocrList.length) return { damages: [], isMatch: true }
    const vehicleDamageOcr = ocrList.find(item => item.category === 'Vehicle Damage')
    const fields = vehicleDamageOcr?.fields
    const damageList = Array.isArray(fields) ? fields : []

    return {
      damages: damageList.map(item => ({
        panel: item.panel,
        description: item.is_damaged ? (item.description || "Can't show message") : 'Tidak terdeteksi kerusakan / No damage Found',
        image: item.gcp_url || '',
        isDamaged: item.is_damaged,
        isTempered: item.is_tampered,
        plate: item.registration_number,
        isPlateMatch: item.registration_number?.replace(/\s/g, '')?.toUpperCase() === plateByPolicy?.replace(/\s/g, '')?.toUpperCase(),
        temperedReason: item.is_tampered ? item.tamper_reason : null,
        hasTimestamp: item.has_timestamp,
        timestampValue: item.timestamp_value,
      })),
      isMatch: damageList.some(item =>
        item.registration_number?.replace(/\s/g, '')?.toUpperCase() === plateByPolicy?.replace(/\s/g, '')?.toUpperCase()
      )
    }
  }, [ocrList, plateByPolicy])

  return (
    <>
      {form.title === TITLE_FORM &&
        <>
          {attribute?.name === 'vehicle_registration' && <DataComparisonTable title="Verification STNK" rows={stnkData} />}
          {attribute?.name === 'driving_licence' && <DataValidationTable title='Verification SIM' rows={simData} />}
          {attribute?.name === 'cardamages_front_back' && <CarIncidentDescription plateNumber={plateByPolicy || 'N/A'} damages={carDamageData} brand={policy?.brand || 'N/A'} color={policy?.color || 'N/A'} />}
        </>
      }
    </>
  )
}
