import EditableWorkshopSelectionForm from './editableWorkshopSelectionForm'
import ViewWorkshopSelectionForm from './ViewWorkshopSelectionForm'

export default function WorkshopSelectionForm ({
  thisInstance,
  formData,
  form,
  submitForm,
  confirmReject,
  permissions,
  disableEventButtons
}) {
  const { attributes, is_valid: isValid, name: formName } = formData

  return (
    isValid
      ? <ViewWorkshopSelectionForm
          thisInstance={thisInstance}
          formName={formName}
          attributes={attributes}
          permissions={permissions}
          confirmReject={confirmReject}
          disableEventButtons={disableEventButtons}
        />
      : <EditableWorkshopSelectionForm
          formData={formData}
          form={form}
          submitForm={submitForm}
          confirmReject={confirmReject}
          permissions={permissions}
        />)
}
