import { useEffect, useState } from 'react'
import { Form, Modal, Input, Select, notification } from 'antd'
import { connect } from 'react-redux'
import pencilIcon from '../../../../image/pencil-icon.png'

import claimActions from '../../../redux/claims/actions'

const { updateClaimUserFraudStatus, resetReduxStateClaim } = claimActions

const FormItem = Form.Item
const { Option } = Select

const formAttributes = [
  {
    name: 'user_status',
    label: 'User Status',
    required: true,
    type: 'choices',
    options: [['FRAUD_SUSPECT', 'Fraud Suspected']]
  },
  {
    name: 'remarks',
    label: 'Remarks',
    required: true,
    type: 'text'
  }
]

function UserFraud({
  form,
  claimId,
  userFraudStatus,
  resetReduxStateClaim,
  updateClaimUserFraudStatus,
  updateClaimUserFraudMessage,
  updateClaimUserFraudSuccessOrFailure
}) {


  const { getFieldDecorator } = form

  const [isModalVisible, setModalVisible] = useState(false)

  const editFraudStatusClickHandler = () => {
    setModalVisible(true)
  }

  const closeModal = () => {
    setModalVisible(false)
  }

  useEffect(() => {
    if (updateClaimUserFraudSuccessOrFailure === 'Success') {
      notification.success({
        message: updateClaimUserFraudMessage || updateClaimUserFraudSuccessOrFailure
      })
      resetReduxStateClaim(['updateClaimUserFraudMessage', 'updateClaimUserFraudStatus'])
      closeModal()
      return
    }
    if (updateClaimUserFraudSuccessOrFailure && updateClaimUserFraudSuccessOrFailure !== 'Success') {
      notification.error({
        message: updateClaimUserFraudMessage || updateClaimUserFraudSuccessOrFailure
      })
      resetReduxStateClaim(['updateClaimUserFraudMessage', 'updateClaimUserFraudStatus'])
    }

  }, [updateClaimUserFraudSuccessOrFailure, updateClaimUserFraudMessage, resetReduxStateClaim])

  const updateFraudStatus = () => {
    form.validateFields((err, payload) => {
      if (err) return
      updateClaimUserFraudStatus({
        payload,
        query: { claim_id: claimId }
      })
    })
  }

  const renderAttribute = formAttributes.map((att) => {
    const { name, label, type, options, required } = att
    const fieldConfig = {
      rules: [
        {
          required,
          message: `${label} is required`
        }
      ]
    }

    if (type === 'choices') {
      return <FormItem label={label} >
        {getFieldDecorator(
          name, fieldConfig
        )(
          <Select style={{ width: '100%' }}>
            {options.map(([value, displayName]) => {
              return <Option key={value} value={value}>{displayName}</Option>
            })}
          </Select>
        )}
      </FormItem>
    }
    return (
      <FormItem label={label}>
        {getFieldDecorator(
          name, fieldConfig
        )(<Input />)}
      </FormItem>
    )
  })

  const modal = <Modal
    title="Change Fraud Status"
    visible={isModalVisible}
    onOk={updateFraudStatus}
    onCancel={closeModal}
    okText="Update"
  >
    {renderAttribute}
  </Modal>

  if (userFraudStatus === 'VERIFIED') {
    return (
      <div style={{ color: 'green' }}>
        {userFraudStatus}
        <img src={pencilIcon} className='btn-icon-pencil' alt='' onClick={editFraudStatusClickHandler} />
        {isModalVisible && modal}
      </div>
    )
  }

  if (userFraudStatus === 'FRAUD_SUSPECT') {
    return <span style={{ color: '#FFC800' }}>Fraud Suspect</span>
  }

  if (userFraudStatus === 'FRAUD_CONFIRM') {
    return <span style={{ color: 'red' }}>Fraud Confirmed</span>
  }

  return null
}

export default connect(state => ({
  updateClaimUserFraudSuccessOrFailure: state.Claims.updateClaimUserFraudStatus,
  updateClaimUserFraudMessage: state.Claims.updateClaimUserFraudMessage,
}), {
  updateClaimUserFraudStatus,
  resetReduxStateClaim
})(Form.create()(UserFraud))